import { Entity } from '../interfaces';
import { BusinessId } from '../value-objects/business-id.value-object';
import { RegistrationNumber } from '../value-objects/registration-number.value-object';
import { TaxId } from '../value-objects/tax-id.value-object';
import { BusinessAddress } from '../value-objects/business-address.value-object';
import {
  BusinessType,
  BusinessStatus,
  VerificationStatus,
  ComplianceStatus
} from '../types/business.types';

export {
  BusinessType,
  BusinessStatus,
  VerificationStatus,
  ComplianceStatus
} from '../types/business.types';

export interface BusinessProps {
  id: string;
  name: string;
  businessType: BusinessType;
  registrationNumber: RegistrationNumber;
  taxId?: TaxId;
  status: BusinessStatus;
  verificationStatus: VerificationStatus;
  complianceStatus: ComplianceStatus;
  ownerId: string;
  description?: string;
  industry?: string;
  website?: string;
  email?: string;
  phoneNumber?: string;
  verifiedAt?: Date;
  verifiedBy?: string;
  addresses?: BusinessAddress[];
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Business Entity
 * Represents a business in the Maysar marketplace system
 */
export class Business implements Entity {
  public readonly id: string;
  public readonly name: string;
  public readonly businessType: BusinessType;
  public readonly registrationNumber: RegistrationNumber;
  public readonly taxId?: TaxId;
  public readonly status: BusinessStatus;
  public readonly verificationStatus: VerificationStatus;
  public readonly complianceStatus: ComplianceStatus;
  public readonly ownerId: string;
  public readonly description?: string;
  public readonly industry?: string;
  public readonly website?: string;
  public readonly email?: string;
  public readonly phoneNumber?: string;
  public readonly verifiedAt?: Date;
  public readonly verifiedBy?: string;
  public readonly addresses: BusinessAddress[];
  public readonly createdAt: Date;
  public readonly updatedAt: Date;

  constructor(props: BusinessProps) {
    this.id = props.id;
    this.name = props.name;
    this.businessType = props.businessType;
    this.registrationNumber = props.registrationNumber;
    this.taxId = props.taxId;
    this.status = props.status;
    this.verificationStatus = props.verificationStatus;
    this.complianceStatus = props.complianceStatus;
    this.ownerId = props.ownerId;
    this.description = props.description;
    this.industry = props.industry;
    this.website = props.website;
    this.email = props.email;
    this.phoneNumber = props.phoneNumber;
    this.verifiedAt = props.verifiedAt;
    this.verifiedBy = props.verifiedBy;
    this.addresses = props.addresses ?? [];
    this.createdAt = props.createdAt;
    this.updatedAt = props.updatedAt;
  }

  /**
   * Create a new business (register)
   */
  static register(props: {
    id: string;
    name: string;
    businessType: BusinessType;
    registrationNumber: RegistrationNumber;
    taxId?: TaxId;
    ownerId: string;
    description?: string;
    industry?: string;
    website?: string;
    email?: string;
    phoneNumber?: string;
    addresses?: BusinessAddress[];
  }): Business {
    return new Business({
      ...props,
      status: BusinessStatus.PENDING,
      verificationStatus: VerificationStatus.UNVERIFIED,
      complianceStatus: ComplianceStatus.UNDER_REVIEW,
      addresses: props.addresses ?? [],
      createdAt: new Date(),
      updatedAt: new Date()
    });
  }

  /**
   * Verify the business
   */
  verify(verifiedBy: string): Business {
    return new Business({
      ...this,
      verificationStatus: VerificationStatus.VERIFIED,
      verifiedAt: new Date(),
      verifiedBy,
      status: this.status === BusinessStatus.PENDING ? BusinessStatus.ACTIVE : this.status,
      updatedAt: new Date()
    });
  }

  /**
   * Suspend the business
   */
  suspend(): Business {
    return new Business({
      ...this,
      status: BusinessStatus.SUSPENDED,
      updatedAt: new Date()
    });
  }

  /**
   * Reactivate the business
   */
  reactivate(): Business {
    return new Business({
      ...this,
      status: BusinessStatus.ACTIVE,
      updatedAt: new Date()
    });
  }

  /**
   * Update business details
   */
  updateDetails(props: {
    name?: string;
    description?: string;
    industry?: string;
    website?: string;
    email?: string;
    phoneNumber?: string;
    addresses?: BusinessAddress[];
  }): Business {
    return new Business({
      ...this,
      ...props,
      updatedAt: new Date()
    });
  }

  /**
   * Validate business entity
   */
  validate(): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!this.id || this.id.trim().length === 0) {
      errors.push('Business ID is required');
    }

    if (!this.name || this.name.trim().length === 0) {
      errors.push('Business name is required');
    }

    if (!this.registrationNumber || !this.registrationNumber.isValid()) {
      errors.push('Valid registration number is required');
    }

    if (!this.ownerId || this.ownerId.trim().length === 0) {
      errors.push('Owner ID is required');
    }

    if (this.taxId && !this.taxId.isValid()) {
      errors.push('Invalid tax ID format');
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  isActive(): boolean {
    return this.status === BusinessStatus.ACTIVE;
  }

  isVerified(): boolean {
    return this.verificationStatus === VerificationStatus.VERIFIED;
  }

  isSuspended(): boolean {
    return this.status === BusinessStatus.SUSPENDED;
  }

  canOperate(): boolean {
    return this.isActive() && this.isVerified() && this.complianceStatus !== ComplianceStatus.NON_COMPLIANT;
  }
}

import express from 'express';
import { PrismaClient } from '@prisma/client';
import { eventBus, EventEnvelope } from '@shared-events/eventBus';
import { v4 as uuidv4 } from 'uuid';
import dotenv from 'dotenv';
import { SearchEngineInitializer } from './src/infrastructure/search-initializer';
import { createMaintenanceRoutes } from './src/api/routes/maintenance.routes';
import { createPrismaClient } from '@shared/database/prisma-client';
import { requireRoleOrService } from '@shared/middleware/auth-context.middleware';

dotenv.config();

const app = express();
const prisma = createPrismaClient();
const legacyWholesalePricingModel = (prisma as unknown as {
  wholesalePricing: {
    findMany(args: Record<string, unknown>): Promise<unknown[]>;
    create(args: Record<string, unknown>): Promise<unknown>;
    upsert(args: Record<string, unknown>): Promise<unknown>;
  };
}).wholesalePricing;

app.use(express.json());
app.use('/api/v1/system/maintenance', requireRoleOrService(['admin', 'system']), createMaintenanceRoutes(prisma));

let searchEngine: any;
let indexManager: any;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type LegacyPayload = Record<string, any>;

interface LegacySagaEvent extends Omit<EventEnvelope, 'data' | 'payload' | 'metadata'> {
  data: LegacyPayload;
  payload: LegacyPayload;
  metadata?: Record<string, unknown>;
  sagaId?: string;
}

const asLegacyPayload = (value: unknown): LegacyPayload =>
  typeof value === 'object' && value !== null ? (value as LegacyPayload) : {};

const asLegacyEvent = (envelope: EventEnvelope): LegacySagaEvent => {
  const metadata = envelope.metadata;
  const metadataSagaId = typeof metadata?.sagaId === 'string' ? metadata.sagaId : undefined;
  return {
    ...envelope,
    data: asLegacyPayload(envelope.data),
    payload: asLegacyPayload(envelope.payload),
    metadata,
    sagaId: envelope.sagaId || metadataSagaId
  };
};

const subscribeLegacy = (
  eventType: string,
  handler: (event: LegacySagaEvent) => Promise<void>
): void => {
  eventBus.subscribe(eventType, async (envelope: EventEnvelope) => {
    await handler(asLegacyEvent(envelope));
  });
};

async function initializeServices() {
  const { searchEngine: engine, indexManager: manager } = await SearchEngineInitializer.initialize(prisma);
  searchEngine = engine;
  indexManager = manager;
}

initializeEventHandlers();
initializeSupplierPricingHandlers();
initializeSellerSagaHandlers();

function initializeSellerSagaHandlers() {
  // Product Catalog Management Saga Events
  subscribeLegacy('ProductCreationStarted', async (event) => {
    const { sellerId, productName, category, sagaId } = event.payload;

    const product = await prisma.product.create({
      data: {
        title: String(productName),
        categoryId: String(category),
        sellerId: String(sellerId),
        slug: `legacy-${uuidv4()}`,
        tags: [],
        status: 'draft'
      }
    });

    await eventBus.publish({
      event: 'ProductCreated',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { productId: product.id, sellerId, sagaId }
    });
  });

  subscribeLegacy('ProductImagesUploaded', async (event) => {
    const { images, sagaId } = event.payload;

    await eventBus.publish({
      event: 'ProductSEOOptimized',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { seoData: { optimized: true }, sagaId }
    });
  });

  subscribeLegacy('ProductSEOOptimized', async (event) => {
    const { seoData, sagaId } = event.payload;

    await eventBus.publish({
      event: 'ProductCatalogSynced',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { sagaId }
    });
  });

  subscribeLegacy('ProductCatalogSynced', async (event) => {
    const { sagaId } = event.payload;

    await eventBus.publish({
      event: 'ProductPublished',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { publishedAt: new Date(), sagaId }
    });
  });

  // Pricing Management Saga Events
  subscribeLegacy('PricingValidationRequested', async (event) => {
    const { sellerId, productId, pricing, sagaId } = event.payload;

    const isValid = pricing.price > 0;

    if (isValid) {
      await eventBus.publish({
        event: 'ProductPricingUpdated',
        version: 'v1',
        eventId: uuidv4(),
        producer: 'catalog-service',
        timestamp: new Date().toISOString(),
        payload: { sellerId, productId, pricing, sagaId }
      });
    }
  });

  subscribeLegacy('ProductPricingUpdated', async (event) => {
    const { productId, pricing, sagaId } = event.payload;

    await prisma.productVariant.updateMany({
      where: { productId },
      data: {
        price: pricing.price,
        compareAtPrice: pricing.compareAtPrice
      }
    });

    await eventBus.publish({
      event: 'PricingChangeNotificationSent',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { productId, sagaId }
    });
  });

  // Promotional Campaign Saga Events
  subscribeLegacy('CampaignValidationRequested', async (event) => {
    const { sellerId, campaign, sagaId } = event.payload;

    const isValid = campaign.startDate && campaign.endDate && campaign.discountPercentage > 0;

    if (isValid) {
      await eventBus.publish({
        event: 'PromotionalCampaignCreated',
        version: 'v1',
        eventId: uuidv4(),
        producer: 'catalog-service',
        timestamp: new Date().toISOString(),
        payload: { sellerId, campaign, sagaId }
      });
    }
  });

  subscribeLegacy('PromotionalCampaignCreated', async (event) => {
    const { sellerId, campaign, sagaId } = event.payload;

    await eventBus.publish({
      event: 'CampaignActivated',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { sellerId, campaignId: campaign.id, sagaId }
    });
  });

  subscribeLegacy('CampaignActivated', async (event) => {
    const { sellerId, campaignId, sagaId } = event.payload;

    await eventBus.publish({
      event: 'CampaignNotificationSent',
      version: 'v1',
      eventId: uuidv4(),
      producer: 'catalog-service',
      timestamp: new Date().toISOString(),
      payload: { sellerId, campaignId, sagaId }
    });
  });
}

