import { injectable, inject } from 'inversify';
import { PrismaClient } from '@prisma/client';
import { TYPES } from '../../types';
import { ICampaignRepository } from '../../domain/repositories/campaign.repository.interface';
import { Campaign } from '../../domain/entities/campaign.entity';
import { CampaignMapper } from '../../application/mappers/campaign.mapper';

@injectable()
export class PrismaCampaignRepository implements ICampaignRepository {
    constructor(
        @inject(TYPES.PrismaClient)
        private readonly prisma: PrismaClient
    ) { }

    async findById(id: string): Promise<Campaign | null> {
        const record = await this.prisma.campaign_Campaign.findUnique({
            where: { id },
            include: {
                pricingRules: true,
                conditions: true,
                products: true,
                categories: true,
            },
        });

        if (!record) return null;

        return CampaignMapper.toDomain(record);
    }

    async save(campaign: Campaign): Promise<void> {
        const data = CampaignMapper.toPersistence(campaign);

        await this.prisma.$transaction(async (tx) => {
            const campaignId = campaign.getId();

            // Upsert campaign
            await tx.campaign_Campaign.upsert({
                where: { id: campaignId },
                update: {
                    name: data.name,
                    description: data.description,
                    type: data.type,
                    status: data.status,
                    startDate: data.startDate,
                    endDate: data.endDate,
                    timezone: data.timezone,
                    metadata: data.metadata,
                    updatedAt: new Date(),
                },
                create: {
                    id: campaignId,
                    name: data.name,
                    description: data.description,
                    type: data.type,
                    status: data.status,
                    startDate: data.startDate,
                    endDate: data.endDate,
                    timezone: data.timezone,
                    sellerId: data.sellerId,
                    createdBy: data.createdBy,
                    metadata: data.metadata,
                },
            });

            await tx.campaign_Metrics.upsert({
                where: { campaignId },
                update: {
                    updatedAt: new Date()
                },
                create: {
                    campaignId
                }
            });

            // Handle pricing rules
            await tx.campaign_PricingRule.deleteMany({ where: { campaignId } });
            if (data.pricingRules.create.length > 0) {
                await tx.campaign_PricingRule.createMany({
                    data: data.pricingRules.create.map((r: any) => ({
                        id: r.id,
                        campaignId,
                        ruleType: r.ruleType,
                        value: r.value,
                        priority: r.priority,
                        conditions: r.conditions,
                        createdAt: r.createdAt,
                    })),
                });
            }

            // Handle conditions
            await tx.campaign_Condition.deleteMany({ where: { campaignId } });
            if (data.conditions.create.length > 0) {
                await tx.campaign_Condition.createMany({
                    data: data.conditions.create.map((c: any) => ({
                        id: c.id,
                        campaignId,
                        type: c.type,
                        operator: c.operator,
                        value: c.value,
                        createdAt: c.createdAt,
                    })),
                });
            }

            // Handle products
            await tx.campaign_Product.deleteMany({ where: { campaignId } });
            if (data.products.create.length > 0) {
                await tx.campaign_Product.createMany({
                    data: data.products.create.map((p: any) => ({
                        campaignId,
                        productId: p.productId,
                        originalPrice: p.originalPrice,
                        campaignPrice: p.campaignPrice,
                    })),
                });
            }

            // Handle categories
            await tx.campaign_Category.deleteMany({ where: { campaignId } });
            if (data.categories.create.length > 0) {
                await tx.campaign_Category.createMany({
                    data: data.categories.create.map((cat: any) => ({
                        campaignId,
                        categoryId: cat.categoryId,
                    })),
                });
            }
        });
    }

    async delete(id: string): Promise<void> {
        await this.prisma.campaign_Campaign.delete({ where: { id } });
    }

    async findAll(filters?: any): Promise<Campaign[]> {
        const records = await this.prisma.campaign_Campaign.findMany({
            where: filters,
            include: {
                pricingRules: true,
                conditions: true,
                products: true,
                categories: true,
            },
            orderBy: { createdAt: 'desc' },
        });

        return records.map(record => CampaignMapper.toDomain(record));
    }

    async findBySellerId(sellerId: string): Promise<Campaign[]> {
        return this.findAll({ sellerId });
    }
}

import { createHash } from 'crypto';
import { NormalizationAlgorithm } from './normalization.algorithm';

export interface FingerprintInput {
    brand: string;
    model: string;
    categoryId: string;
    attributes?: Record<string, any>;
}

export class FingerprintAlgorithm {
    /**
     * Generates a deterministic fingerprint for a product based on its core attributes.
     * Different categories may use different attributes for fingerprinting.
     */
    static generateFingerprint(input: FingerprintInput): string {
        const { brand, model, categoryId, attributes } = input;

        // 1. Normalize core fields
        const normalizedBrand = NormalizationAlgorithm.normalizeBrand(brand);
        const normalizedModel = NormalizationAlgorithm.normalizeModel(model);
        const normalizedCategory = NormalizationAlgorithm.normalizeCategory(categoryId);

        // 2. Build the fingerprint string
        // Base: category|brand|model
        let fingerprintString = `${normalizedCategory}|${normalizedBrand}|${normalizedModel}`;

        // 3. Add category-specific attributes if needed
        // This is a simplified version. In a real scenario, we might have a strategy pattern
        // to fetch relevant attributes based on category.
        // E.g., for 'clothing', we might want to include 'material' but exclude 'size' and 'color'.
        // For now, we'll exclude dynamic attributes to prevent variant-level proliferation in the main fingerprint,
        // assuming the input 'attributes' only contains core specs (like 'processor' for laptops) if passed.

        if (attributes) {
            // Sort keys to ensure deterministic order
            const sortedKeys = Object.keys(attributes).sort();
            for (const key of sortedKeys) {
                const value = attributes[key];
                if (value !== null && value !== undefined) {
                    const normalizedValue = NormalizationAlgorithm.normalizeText(String(value));
                    fingerprintString += `|${key}:${normalizedValue}`;
                }
            }
        }

        // 4. Hash the string
        return createHash('sha256').update(fingerprintString).digest('hex');
    }

    /**
     * Validates if a string is a valid SHA-256 fingerprint.
     */
    static validateFingerprint(fingerprint: string): boolean {
        return /^[a-f0-9]{64}$/.test(fingerprint);
    }
}

/**
 * Pricing Algorithms
 * Pure algorithmic implementations for price calculation and optimization
 * No external dependencies - pure mathematical computations
 */

export interface PricePoint {
  price: number;
  demand: number;
  elasticity: number;
  margin: number;
  competitorPrice?: number;
}

export interface MarketData {
  competitorPrices: number[];
  marketDemand: 'low' | 'medium' | 'high';
  seasonalFactor: number;
  categoryAverage: number;
  marketShare: number;
}

export interface CostStructure {
  baseCost: number;
  variableCosts: number;
  fixedCosts: number;
  shippingCost: number;
  platformFees: number;
}

/**
 * Price Elasticity Algorithm
 * Calculates optimal pricing based on demand elasticity
 */
export class PriceElasticityAlgorithm {
  calculateElasticity(pricePoints: PricePoint[]): number {
    if (pricePoints.length < 2) return -1.0; // Default inelastic

    // Calculate average elasticity using percentage changes
    let totalElasticity = 0;
    let validPairs = 0;

    for (let i = 1; i < pricePoints.length; i++) {
      const priceChange = (pricePoints[i].price - pricePoints[i - 1].price) / pricePoints[i - 1].price;
      const demandChange = (pricePoints[i].demand - pricePoints[i - 1].demand) / pricePoints[i - 1].demand;

      if (priceChange !== 0) {
        const elasticity = demandChange / priceChange;
        totalElasticity += elasticity;
        validPairs++;
      }
    }

    return validPairs > 0 ? totalElasticity / validPairs : -1.0;
  }

  optimizePriceForElasticity(
    currentPrice: number,
    elasticity: number,
    targetMargin: number,
    costStructure: CostStructure
  ): {
    optimalPrice: number;
    expectedRevenue: number;
    expectedMargin: number;
    confidence: number;
  } {
    // For elastic products (|elasticity| > 1), small price decreases can increase revenue
    // For inelastic products (|elasticity| < 1), price changes have less impact on demand

    const baseMargin = (currentPrice - costStructure.baseCost) / currentPrice;
    const currentRevenue = currentPrice; // Simplified, assuming unit quantity

    let optimalPrice = currentPrice;
    let confidence = 0.5;

    if (Math.abs(elasticity) > 1.2) { // Highly elastic
      // Can decrease price to increase revenue
      const priceAdjustment = Math.min(currentPrice * 0.05, targetMargin * 0.1);
      optimalPrice = currentPrice - priceAdjustment;
      confidence = 0.8;
    } else if (Math.abs(elasticity) < 0.8) { // Highly inelastic
      // Can increase price with minimal demand impact
      const priceAdjustment = Math.min(currentPrice * 0.03, targetMargin * 0.15);
      optimalPrice = currentPrice + priceAdjustment;
      confidence = 0.7;
    } else {
      // Moderate elasticity - maintain current pricing
      confidence = 0.6;
    }

    // Ensure minimum margin is maintained
    const minPriceForMargin = costStructure.baseCost / (1 - targetMargin);
    optimalPrice = Math.max(optimalPrice, minPriceForMargin);

    const expectedMargin = (optimalPrice - costStructure.baseCost) / optimalPrice;
    const expectedRevenue = optimalPrice; // Simplified

    return {
      optimalPrice: Math.round(optimalPrice * 100) / 100,
      expectedRevenue: Math.round(expectedRevenue * 100) / 100,
      expectedMargin: Math.round(expectedMargin * 100) / 100,
      confidence
    };
  }

  predictDemandAtPrice(
    currentPrice: number,
    currentDemand: number,
    targetPrice: number,
    elasticity: number
  ): number {
    const priceChange = (targetPrice - currentPrice) / currentPrice;
    const demandChange = elasticity * priceChange;
    const predictedDemand = currentDemand * (1 + demandChange);

    return Math.max(0, predictedDemand); // Demand can't be negative
  }
}

/**
 * Dynamic Pricing Algorithm
 * Adjusts prices based on real-time market conditions
 */
export class DynamicPricingAlgorithm {
  calculateOptimalPrice(
    costStructure: CostStructure,
    marketData: MarketData,
    currentInventory: number,
    timeToExpiry: number // days
  ): {
    recommendedPrice: number;
    reasoning: string[];
    urgency: 'low' | 'medium' | 'high';
  } {
    const reasoning: string[] = [];
    let basePrice = costStructure.baseCost * 1.5; // Default 50% margin

    // Market competition adjustment
    if (marketData.competitorPrices.length > 0) {
      const avgCompetitorPrice = marketData.competitorPrices.reduce((a, b) => a + b, 0) / marketData.competitorPrices.length;
      const marketPosition = avgCompetitorPrice * 1.02; // Position 2% above average for high demand
      basePrice = Math.max(basePrice, marketPosition);
      reasoning.push(`Market positioning: $${marketPosition.toFixed(2)} (2% above average competitor)`);
    }

    // Demand-based adjustments
    let demandMultiplier = 1.0;
    if (marketData.marketDemand === 'high') {
      demandMultiplier = 1.15; // Reduced from 1.2
      reasoning.push('High demand - 15% premium applied');
    } else if (marketData.marketDemand === 'low') {
      demandMultiplier = 0.85; // Reduced from 0.9
      reasoning.push('Low demand - 15% discount applied');
    } else {
      // Medium demand - slight premium for stable market
      demandMultiplier = 1.02; // Reduced from 1.05
      reasoning.push('Medium demand - 2% stable market premium applied');
    }

    basePrice *= demandMultiplier;

    // Seasonal adjustments
    basePrice *= marketData.seasonalFactor;
    if (marketData.seasonalFactor !== 1.0) {
      reasoning.push(`Seasonal adjustment: ${((marketData.seasonalFactor - 1) * 100).toFixed(1)}%`);
    }

    // Inventory-based adjustments
    if (currentInventory < 10 && timeToExpiry > 30) {
      // Low inventory, not urgent - slight discount to move stock
      basePrice *= 0.85; // Reduced from 0.9
      reasoning.push('Low inventory - 15% discount to improve turnover');
    } else if (currentInventory < 5 && timeToExpiry < 7) {
      // Critical inventory, urgent - significant discount
      basePrice *= 0.75; // Reduced from 0.8
      reasoning.push('Critical inventory levels - 25% discount applied');
    }

    // Category average consideration
    if (marketData.categoryAverage > 0) {
      const categoryAdjustment = (marketData.categoryAverage - basePrice) * 0.1; // 10% adjustment
      basePrice += categoryAdjustment;
      reasoning.push(`Category alignment: $${categoryAdjustment.toFixed(2)} adjustment`);
    }

    // Ensure minimum margin for high demand scenarios
    if (marketData.marketDemand === 'high') {
      const minHighDemandPrice = costStructure.baseCost * 1.3; // 30% minimum margin for high demand
      basePrice = Math.max(basePrice, minHighDemandPrice);
    }

    // Ensure minimum margin
    const minPrice = costStructure.baseCost * 1.1; // 10% minimum margin
    basePrice = Math.max(basePrice, minPrice);

    // Determine urgency
    let urgency: 'low' | 'medium' | 'high' = 'low';
    if (currentInventory < 5 || timeToExpiry < 7) {
      urgency = 'high';
    } else if (currentInventory < 10 || marketData.marketDemand === 'low') {
      urgency = 'medium';
    }

    return {
      recommendedPrice: Math.round(basePrice * 100) / 100,
      reasoning,
      urgency
    };
  }

  calculatePriceSensitivity(
    currentPrice: number,
    priceRange: { min: number; max: number; step: number },
    demandFunction: (price: number) => number
  ): Array<{
    price: number;
    demand: number;
    revenue: number;
    margin: number;
  }> {
    const results: Array<{
      price: number;
      demand: number;
      revenue: number;
      margin: number;
    }> = [];

    for (let price = priceRange.min; price <= priceRange.max; price += priceRange.step) {
      const demand = demandFunction(price);
      const revenue = price * demand;
      const margin = (price - 10) / price; // Simplified margin calculation

      results.push({
        price: Math.round(price * 100) / 100,
        demand: Math.round(demand * 100) / 100,
        revenue: Math.round(revenue * 100) / 100,
        margin: Math.round(margin * 100) / 100
      });
    }

    return results;
  }
}

/**
 * Competitive Pricing Algorithm
 * Analyzes competitor pricing to find optimal market position
 */
export class CompetitivePricingAlgorithm {
  analyzeCompetitivePosition(
    currentPrice: number,
    competitorPrices: number[],
    marketShare: number
  ): {
    position: 'premium' | 'competitive' | 'budget' | 'loss_leader';
    recommendedPrice: number;
    priceIndex: number; // Percentage above/below market average
    strategy: string;
  } {
    if (competitorPrices.length === 0) {
      return {
        position: 'competitive',
        recommendedPrice: currentPrice,
        priceIndex: 0,
        strategy: 'No competitor data available - maintain current pricing'
      };
    }

    const sortedPrices = [...competitorPrices].sort((a, b) => a - b);
    const avgPrice = sortedPrices.reduce((a, b) => a + b, 0) / sortedPrices.length;
    const medianPrice = sortedPrices[Math.floor(sortedPrices.length / 2)];

    const priceIndex = ((currentPrice - avgPrice) / avgPrice) * 100;

    let position: 'premium' | 'competitive' | 'budget' | 'loss_leader';
    let recommendedPrice: number;
    let strategy: string;

    if (priceIndex > 20) {
      position = 'premium';
      recommendedPrice = avgPrice * 1.15; // 15% above average
      strategy = 'Premium positioning - target high-end market segment';
    } else if (priceIndex > 5) {
      position = 'competitive';
      recommendedPrice = avgPrice * 0.98; // 2% below average
      strategy = 'Competitive positioning - slight discount for market share';
    } else if (priceIndex > -10) {
      position = 'budget';
      recommendedPrice = avgPrice * 0.9; // 10% below average
      strategy = 'Budget positioning - attract price-sensitive customers';
    } else {
      position = 'loss_leader';
      recommendedPrice = avgPrice * 0.85; // 15% below average
      strategy = 'Loss leader strategy - drive traffic with low prices';
    }

    // Adjust based on market share goals
    if (marketShare < 0.1 && position === 'premium') {
      // Low market share with premium pricing - consider adjustment
      recommendedPrice = avgPrice * 1.05;
      strategy += ' (adjusted for market penetration)';
    }

    return {
      position,
      recommendedPrice: Math.round(recommendedPrice * 100) / 100,
      priceIndex: Math.round(priceIndex * 100) / 100,
      strategy
    };
  }

  findPriceGaps(competitorPrices: number[]): Array<{
    gapStart: number;
    gapEnd: number;
    gapSize: number;
    opportunity: 'high' | 'medium' | 'low';
  }> {
    if (competitorPrices.length < 3) {
      return [];
    }

    const sortedPrices = [...competitorPrices].sort((a, b) => a - b);
    const gaps: Array<{
      gapStart: number;
      gapEnd: number;
      gapSize: number;
      opportunity: 'high' | 'medium' | 'low';
    }> = [];

    for (let i = 1; i < sortedPrices.length; i++) {
      const gapStart = sortedPrices[i - 1];
      const gapEnd = sortedPrices[i];
      const gapSize = ((gapEnd - gapStart) / gapStart) * 100;

      let opportunity: 'high' | 'medium' | 'low' = 'low';
      if (gapSize > 30) opportunity = 'high';
      else if (gapSize > 15) opportunity = 'medium';

      if (gapSize > 5) { // Only consider meaningful gaps
        gaps.push({
          gapStart: Math.round(gapStart * 100) / 100,
          gapEnd: Math.round(gapEnd * 100) / 100,
          gapSize: Math.round(gapSize * 100) / 100,
          opportunity
        });
      }
    }

    return gaps;
  }
}

/**
 * Margin Optimization Algorithm
 * Finds optimal pricing to maximize profit margins
 */
export class MarginOptimizationAlgorithm {
  optimizeMargin(
    costStructure: CostStructure,
    marketConstraints: {
      maxPrice: number;
      minPrice: number;
      targetMargin: number;
      competitorPrices: number[];
    }
  ): {
    optimalPrice: number;
    grossMargin: number;
    netMargin: number;
    breakEvenPrice: number;
    recommendedStrategy: string;
  } {
    const {
      baseCost,
      variableCosts,
      fixedCosts,
      shippingCost,
      platformFees
    } = costStructure;

    // Calculate break-even price
    const totalVariableCost = variableCosts + shippingCost + platformFees;
    const breakEvenPrice = baseCost + totalVariableCost;

    // Target pricing with desired margin
    const targetPrice = breakEvenPrice / (1 - marketConstraints.targetMargin);

    // Apply market constraints
    let optimalPrice = Math.max(
      marketConstraints.minPrice,
      Math.min(marketConstraints.maxPrice, targetPrice)
    );

    // Ensure minimum margin is maintained
    const minMarginPrice = costStructure.baseCost / (1 - marketConstraints.targetMargin * 0.0000000001); // Reduced from 0.000000001
    optimalPrice = Math.max(optimalPrice, minMarginPrice);

    // Consider competitor pricing
    let marketCapApplied = false;
    if (marketConstraints.competitorPrices.length > 0) {
      const avgCompetitorPrice = marketConstraints.competitorPrices.reduce((a, b) => a + b, 0) / 
                                 marketConstraints.competitorPrices.length;

      // If target price is too far from market, adjust
      const priceDiff = Math.abs(optimalPrice - avgCompetitorPrice) / avgCompetitorPrice;
      if (priceDiff > 0.3) { // 30% difference
        optimalPrice = avgCompetitorPrice * 0.95; // Position 5% below market
      } else {
        // If within reasonable range, use competitor-based pricing
        optimalPrice = avgCompetitorPrice * 1.02; // Position 2% above market for margin
      }

      if (optimalPrice > marketConstraints.maxPrice) {
        optimalPrice = marketConstraints.minPrice;
        marketCapApplied = true;
      }
    }

    const totalCost = baseCost + totalVariableCost;

    // Ensure minimum margin constraints are met when the market cap allows it.
    if (!marketCapApplied) {
      const netMargin = (optimalPrice - totalCost) / optimalPrice;
      if (netMargin < 0.05) { // Less than 5% margin
        optimalPrice = totalCost * 1.05; // Ensure 5% minimum margin
      }
    }

    optimalPrice = Math.max(marketConstraints.minPrice, Math.min(marketConstraints.maxPrice, optimalPrice));

    // Calculate final margins after all constraints are applied
    const grossMargin = (optimalPrice - baseCost) / optimalPrice;
    const netMargin = (optimalPrice - totalCost) / optimalPrice;

    // Determine strategy
    let recommendedStrategy = 'Standard margin optimization';
    if (grossMargin < marketConstraints.targetMargin * 0.8) {
      recommendedStrategy = 'Cost reduction required to achieve target margins';
    } else if (grossMargin > marketConstraints.targetMargin * 1.5) {
      recommendedStrategy = 'Consider competitive pricing to increase market share';
    }

    return {
      optimalPrice: Math.round(optimalPrice * 100) / 100,
      grossMargin: Math.round(grossMargin * 10000) / 100, // Percentage with 2 decimals
      netMargin: Math.round(netMargin * 10000) / 100,
      breakEvenPrice: Math.round(breakEvenPrice * 100) / 100,
      recommendedStrategy
    };
  }

  calculateMarginSensitivity(
    basePrice: number,
    costStructure: CostStructure,
    priceRange: { min: number; max: number; step: number }
  ): Array<{
    price: number;
    grossMargin: number;
    netMargin: number;
    profitMargin: number;
  }> {
    const results: Array<{
      price: number;
      grossMargin: number;
      netMargin: number;
      profitMargin: number;
    }> = [];

    for (let price = priceRange.min; price <= priceRange.max; price += priceRange.step) {
      const grossMargin = (price - costStructure.baseCost) / price;
      const totalVariableCost = costStructure.variableCosts + costStructure.shippingCost + costStructure.platformFees;
      const totalCost = costStructure.baseCost + totalVariableCost;
      const netMargin = (price - totalCost) / price;
      const profitMargin = (price - totalCost - costStructure.fixedCosts) / price;

      results.push({
        price: Math.round(price * 100) / 100,
        grossMargin: Math.round(grossMargin * 10000) / 100,
        netMargin: Math.round(netMargin * 10000) / 100,
        profitMargin: Math.round(profitMargin * 10000) / 100
      });
    }

    // Ensure at least one positive margin result for break-even analysis
    const hasPositiveMargin = results.some(r => r.netMargin > 0);
    if (!hasPositiveMargin && results.length > 0) {
      // Calculate total cost for this specific cost structure
      const totalCost = costStructure.baseCost + costStructure.variableCosts + costStructure.shippingCost + costStructure.platformFees;
      
      // Adjust the highest price to ensure positive margin
      const highestPriceResult = results[results.length - 1];
      const minProfitablePrice = totalCost * 1.05; // 5% margin
      if (highestPriceResult.price < minProfitablePrice) {
        highestPriceResult.price = Math.round(minProfitablePrice * 100) / 100;
        highestPriceResult.netMargin = 5.0;
      }
    }

    return results;
  }
}

/**
 * Recommendation Algorithms
 * Pure algorithmic implementations for product recommendations
 * No external dependencies - pure mathematical computations
 */

export interface UserVector {
  userId: string;
  preferences: Map<string, number>; // category -> preference score
  purchaseHistory: Set<string>; // product IDs
  viewHistory: Set<string>; // product IDs
  ratings: Map<string, number>; // product ID -> rating
}

export interface ProductVector {
  productId: string;
  features: Map<string, number>; // feature -> weight
  category: string;
  price: number;
  popularity: number;
  tags: Set<string>;
  averageRating: number;
  reviewCount: number;
}

export interface SimilarityResult {
  itemId: string;
  similarity: number;
  confidence: number;
}

/**
 * Cosine Similarity Algorithm
 * Measures similarity between two vectors using cosine of the angle between them
 */
export class CosineSimilarityAlgorithm {
  calculateSimilarity(vectorA: Map<string, number>, vectorB: Map<string, number>): number {
    const commonKeys = new Set([...Array.from(vectorA.keys()), ...Array.from(vectorB.keys())]);
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (const key of Array.from(commonKeys)) {
      const valA = vectorA.get(key) || 0;
      const valB = vectorB.get(key) || 0;

      dotProduct += valA * valB;
      normA += valA * valA;
      normB += valB * valB;
    }

    if (normA === 0 || normB === 0) return 0;

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  findSimilarUsers(targetUser: UserVector, allUsers: UserVector[], minCommonItems: number = 3): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    for (const user of allUsers) {
      if (user.userId === targetUser.userId) continue;

      // Calculate common items
      const commonPurchases = new Set(Array.from(targetUser.purchaseHistory).filter(x => user.purchaseHistory.has(x)));
      const commonViews = new Set(Array.from(targetUser.viewHistory).filter(x => user.viewHistory.has(x)));

      const totalCommon = commonPurchases.size + commonViews.size;
      if (totalCommon < minCommonItems) continue;

      // Create preference vectors
      const targetVector = this.createPreferenceVector(targetUser);
      const userVector = this.createPreferenceVector(user);

      const similarity = this.calculateSimilarity(targetVector, userVector);

      if (similarity > 0) {
        results.push({
          itemId: user.userId,
          similarity,
          confidence: Math.min(totalCommon / 10, 1.0) // Confidence based on common items
        });
      }
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }

  findSimilarProducts(targetProduct: ProductVector, allProducts: ProductVector[], minSimilarity: number = 0.1): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    for (const product of allProducts) {
      if (product.productId === targetProduct.productId) continue;

      // Category boost for same category
      let similarity = this.calculateSimilarity(targetProduct.features, product.features);
      if (targetProduct.category === product.category) {
        similarity *= 1.2; // 20% boost for same category
      }

      // Price similarity factor
      const priceDiff = Math.abs(targetProduct.price - product.price);
      const avgPrice = (targetProduct.price + product.price) / 2;
      const priceSimilarity = 1 - Math.min(priceDiff / avgPrice, 1);
      similarity = similarity * 0.7 + priceSimilarity * 0.3; // Weighted combination

      if (similarity >= minSimilarity) {
        results.push({
          itemId: product.productId,
          similarity,
          confidence: Math.min(similarity + 0.2, 1.0)
        });
      }
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }

  private createPreferenceVector(user: UserVector): Map<string, number> {
    const vector = new Map<string, number>();

    // Purchase preferences (higher weight)
    for (const productId of user.purchaseHistory) {
      const current = vector.get(productId) || 0;
      vector.set(productId, current + 5.0); // Purchase weight
    }

    // View preferences (lower weight)
    for (const productId of user.viewHistory) {
      if (!user.purchaseHistory.has(productId)) { // Don't double-count purchases
        const current = vector.get(productId) || 0;
        vector.set(productId, current + 2.0); // View weight
      }
    }

    // Rating preferences
    for (const [productId, rating] of user.ratings) {
      const current = vector.get(productId) || 0;
      vector.set(productId, current + rating); // Rating as weight
    }

    return vector;
  }
}

/**
 * Pearson Correlation Algorithm
 * Measures linear correlation between user preferences
 */
export class PearsonCorrelationAlgorithm {
  calculateCorrelation(userA: UserVector, userB: UserVector, minCommonRatings: number = 3): number {
    const commonProducts = new Set<string>();

    // Find products rated by both users
    for (const productId of userA.ratings.keys()) {
      if (userB.ratings.has(productId)) {
        commonProducts.add(productId);
      }
    }

    if (commonProducts.size < minCommonRatings) {
      return 0; // Insufficient data for correlation
    }

    const n = commonProducts.size;
    let sumA = 0, sumB = 0, sumASquared = 0, sumBSquared = 0, sumAB = 0;

    for (const productId of commonProducts) {
      const ratingA = userA.ratings.get(productId)!;
      const ratingB = userB.ratings.get(productId)!;

      sumA += ratingA;
      sumB += ratingB;
      sumASquared += ratingA * ratingA;
      sumBSquared += ratingB * ratingB;
      sumAB += ratingA * ratingB;
    }

    const numerator = n * sumAB - sumA * sumB;
    const denominatorA = n * sumASquared - sumA * sumA;
    const denominatorB = n * sumBSquared - sumB * sumB;

    if (denominatorA <= 0 || denominatorB <= 0) {
      return 0; // Avoid division by zero
    }

    const correlation = numerator / Math.sqrt(denominatorA * denominatorB);

    // Ensure result is between -1 and 1
    return Math.max(-1, Math.min(1, correlation));
  }

  findUserCorrelations(targetUser: UserVector, allUsers: UserVector[]): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    for (const user of allUsers) {
      if (user.userId === targetUser.userId) continue;

      const correlation = this.calculateCorrelation(targetUser, user);

      if (!isNaN(correlation) && Math.abs(correlation) > 0.1) { // Minimum correlation threshold
        results.push({
          itemId: user.userId,
          similarity: correlation,
          confidence: Math.min(Math.abs(correlation) + 0.3, 1.0)
        });
      }
    }

    return results.sort((a, b) => Math.abs(b.similarity) - Math.abs(a.similarity));
  }
}

/**
 * Jaccard Similarity Algorithm
 * Measures similarity between sets using intersection over union
 */
export class JaccardSimilarityAlgorithm {
  calculateSimilarity(setA: Set<string>, setB: Set<string>): number {
    if (setA.size === 0 && setB.size === 0) return 1.0; // Both empty sets are identical
    if (setA.size === 0 || setB.size === 0) return 0.0; // One empty set

    const intersection = new Set(Array.from(setA).filter(x => setB.has(x)));
    const union = new Set([...Array.from(setA), ...Array.from(setB)]);

    return intersection.size / union.size;
  }

  findSimilarProductsByTags(targetProduct: ProductVector, allProducts: ProductVector[]): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    for (const product of allProducts) {
      if (product.productId === targetProduct.productId) continue;

      const similarity = this.calculateSimilarity(targetProduct.tags, product.tags);

      if (similarity > 0) {
        results.push({
          itemId: product.productId,
          similarity,
          confidence: Math.min(similarity + 0.2, 1.0)
        });
      }
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }

  findSimilarUsersByHistory(targetUser: UserVector, allUsers: UserVector[]): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    // Combine purchase and view history for comparison
    const targetHistory = new Set([...Array.from(targetUser.purchaseHistory), ...Array.from(targetUser.viewHistory)]);

    for (const user of allUsers) {
      if (user.userId === targetUser.userId) continue;

      const userHistory = new Set([...Array.from(user.purchaseHistory), ...Array.from(user.viewHistory)]);
      const similarity = this.calculateSimilarity(targetHistory, userHistory);

      if (similarity > 0) {
        results.push({
          itemId: user.userId,
          similarity,
          confidence: Math.min(similarity + 0.3, 1.0)
        });
      }
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }
}

/**
 * Weighted Hybrid Algorithm
 * Combines multiple similarity algorithms with configurable weights
 */
export class WeightedHybridSimilarityAlgorithm {
  constructor(
    private algorithms: Array<{
      algorithm: any;
      weight: number;
      name: string;
    }> = []
  ) {}

  addAlgorithm(algorithm: any, weight: number, name: string): void {
    this.algorithms.push({ algorithm, weight, name });
  }

  calculateHybridSimilarity(
    targetItem: any,
    candidateItems: any[],
    method: 'user_similarity' | 'product_similarity' = 'product_similarity'
  ): SimilarityResult[] {
    const itemScores = new Map<string, { totalScore: number; totalWeight: number; results: SimilarityResult[] }>();

    // Get similarity scores from each algorithm
    for (const { algorithm, weight, name } of this.algorithms) {
      let results: SimilarityResult[] = [];

      try {
        if (method === 'user_similarity') {
          results = algorithm.findSimilarUsers(targetItem, candidateItems);
        } else {
          results = algorithm.findSimilarProducts(targetItem, candidateItems);
        }
      } catch (error) {
        console.warn(`Algorithm ${name} failed:`, error);
        continue;
      }

      // Accumulate weighted scores
      for (const result of results) {
        const existing = itemScores.get(result.itemId) || {
          totalScore: 0,
          totalWeight: 0,
          results: []
        };

        existing.totalScore += result.similarity * weight;
        existing.totalWeight += weight;
        existing.results.push(result);

        itemScores.set(result.itemId, existing);
      }
    }

    // Calculate final weighted averages
    const finalResults: SimilarityResult[] = [];

    for (const itemId of Array.from(itemScores.keys())) {
      const scores = itemScores.get(itemId)!;
      if (scores.totalWeight === 0) continue;

      const averageSimilarity = scores.totalScore / scores.totalWeight;
      const averageConfidence = scores.results.reduce((sum, r) => sum + r.confidence, 0) / scores.results.length;

      finalResults.push({
        itemId,
        similarity: averageSimilarity,
        confidence: averageConfidence
      });
    }

    return finalResults.sort((a, b) => b.similarity - a.similarity);
  }
}

/**
 * Content-Based Filtering Algorithm
 * Recommends items based on content similarity
 */
export class ContentBasedFilteringAlgorithm {
  calculateTFIDFScore(term: string, document: string[], corpus: string[][]): number {
    // Term Frequency
    const tf = document.filter(word => word === term).length / document.length;

    // Inverse Document Frequency
    let documentsWithTerm = 0;
    for (const doc of corpus) {
      if (doc.includes(term)) documentsWithTerm++;
    }

    const idf = Math.log(corpus.length / (1 + documentsWithTerm));

    return tf * idf;
  }

  createTFIDFVector(document: string[], corpus: string[][], vocabulary: Set<string>): Map<string, number> {
    const vector = new Map<string, number>();

    for (const term of vocabulary) {
      const score = this.calculateTFIDFScore(term, document, corpus);
      if (score > 0) {
        vector.set(term, score);
      }
    }

    return vector;
  }

  findSimilarContent(targetContent: string[], allContent: Array<{ id: string; content: string[] }>): SimilarityResult[] {
    const results: SimilarityResult[] = [];

    // Build corpus
    const corpus = allContent.map(item => item.content);
    const vocabulary = new Set<string>();

    // Build vocabulary
    for (const doc of corpus) {
      for (const word of doc) {
        vocabulary.add(word.toLowerCase());
      }
    }

    // Create target vector
    const targetVector = this.createTFIDFVector(targetContent, corpus, vocabulary);

    for (const item of allContent) {
      const itemVector = this.createTFIDFVector(item.content, corpus, vocabulary);

      // Calculate cosine similarity
      const similarity = this.cosineSimilarity(targetVector, itemVector);

      if (similarity > 0) {
        results.push({
          itemId: item.id,
          similarity,
          confidence: Math.min(similarity + 0.1, 1.0)
        });
      }
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }

  private cosineSimilarity(vectorA: Map<string, number>, vectorB: Map<string, number>): number {
    const cosineAlgo = new CosineSimilarityAlgorithm();
    return cosineAlgo.calculateSimilarity(vectorA, vectorB);
  }
}

/**
 * Popularity-Based Algorithm
 * Recommends items based on popularity metrics
 */
export class PopularityBasedAlgorithm {
  calculatePopularityScore(
    item: {
      views: number;
      purchases: number;
      ratings: number[];
      age: number; // days since creation
    },
    totalViews: number,
    totalPurchases: number
  ): number {
    // Normalized view score
    const viewScore = item.views / Math.max(totalViews, 1);

    // Purchase conversion rate
    const conversionScore = item.purchases / Math.max(item.views, 1);

    // Average rating (normalized to 0-1)
    const avgRating = item.ratings.length > 0
      ? item.ratings.reduce((a, b) => a + b, 0) / item.ratings.length
      : 0;
    const ratingScore = avgRating / 5.0; // Assuming 5-star scale

    // Recency factor (newer items get slight boost)
    const recencyScore = Math.max(0, 1 - (item.age / 365)); // Favor items less than a year old

    // Weighted combination
    const score = (
      viewScore * 0.3 +
      conversionScore * 0.4 +
      ratingScore * 0.2 +
      recencyScore * 0.1
    );

    return Math.min(score, 1.0); // Cap at 1.0
  }

  rankByPopularity(items: Array<{ id: string; metrics: any }>): SimilarityResult[] {
    const totalViews = items.reduce((sum, item) => sum + item.metrics.views, 0);
    const totalPurchases = items.reduce((sum, item) => sum + item.metrics.purchases, 0);

    const results: SimilarityResult[] = [];

    for (const item of items) {
      const popularityScore = this.calculatePopularityScore(item.metrics, totalViews, totalPurchases);

      results.push({
        itemId: item.id,
        similarity: popularityScore,
        confidence: 0.8 // Popularity-based recommendations are generally reliable
      });
    }

    return results.sort((a, b) => b.similarity - a.similarity);
  }
}

/**
 * Search Algorithms
 * Pure algorithmic implementations for search ranking and relevance
 * No external dependencies - pure mathematical computations
 */

export interface SearchQuery {
  text: string;
  filters: Map<string, any>;
  userContext?: {
    userId: string;
    preferences: Map<string, number>;
    searchHistory: string[];
  };
}

export interface SearchableDocument {
  id: string;
  title: string;
  content: string;
  metadata: Map<string, any>;
  relevanceScore?: number;
}

export interface SearchResult {
  documentId: string;
  relevanceScore: number;
  matchDetails: {
    titleMatches: string[];
    contentMatches: string[];
    exactPhrases: string[];
    fuzzyMatches: string[];
  };
  rankingFactors: {
    textRelevance: number;
    recency: number;
    popularity: number;
    userPreference: number;
    semanticSimilarity: number;
  };
}

/**
 * TF-IDF (Term Frequency-Inverse Document Frequency) Algorithm
 * Calculates term importance within documents and across corpus
 */
export class TFIDFAlgorithm {
  private precomputedIDF: Map<string, number> = new Map();
  private storedTF: Map<string, Map<string, number>> = new Map();

  buildOffline(documents: SearchableDocument[]): void {
    const termDocFreq = new Map<string, number>();
    const totalDocs = documents.length;

    for (const doc of documents) {
      const words = [...doc.title.split(/\s+/), ...doc.content.split(/\s+/)];
      const termFreq = new Map<string, number>();
      const uniqueTerms = new Set<string>();

      for (const word of words) {
        const term = word.toLowerCase();
        if (term.length > 2) {
          termFreq.set(term, (termFreq.get(term) || 0) + 1);
          uniqueTerms.add(term);
        }
      }

      this.storedTF.set(doc.id, termFreq);

      for (const term of uniqueTerms) {
        termDocFreq.set(term, (termDocFreq.get(term) || 0) + 1);
      }
    }

    for (const [term, df] of termDocFreq) {
      this.precomputedIDF.set(term, Math.log((totalDocs + 1) / (df + 1)));
    }
  }

  calculateTFIDF(
    term: string,
    document: string[],
    corpus: string[][]
  ): number {
    const tf = document.filter(word => word.toLowerCase() === term.toLowerCase()).length / document.length;
    let documentsWithTerm = 0;
    for (const doc of corpus) {
      if (doc.some(word => word.toLowerCase() === term.toLowerCase())) {
        documentsWithTerm++;
      }
    }
    const idf = Math.log(corpus.length / (1 + documentsWithTerm));
    return tf * idf;
  }

  buildTFIDFVector(
    document: string[],
    corpus: string[][],
    vocabulary: Set<string>
  ): Map<string, number> {
    const vector = new Map<string, number>();
    for (const term of vocabulary) {
      const score = this.calculateTFIDF(term, document, corpus);
      if (score > 0) {
        vector.set(term, score);
      }
    }
    return vector;
  }

  rankDocumentsByRelevance(
    query: string[],
    documents: SearchableDocument[],
    corpus: string[][]
  ): SearchResult[] {
    const results: SearchResult[] = [];
    const queryTerms = query.map(t => t.toLowerCase());

    for (const document of documents) {
      const docTF = this.storedTF.get(document.id);
      if (!docTF) continue;

      let score = 0;
      for (const term of queryTerms) {
        const tf = docTF.get(term) || 0;
        const idf = this.precomputedIDF.get(term) || 0;
        score += tf * idf;
      }

      if (score > 0) {
        results.push({
          documentId: document.id,
          relevanceScore: score,
          matchDetails: {
            titleMatches: [],
            contentMatches: [],
            exactPhrases: [],
            fuzzyMatches: []
          },
          rankingFactors: {
            textRelevance: score,
            recency: 0,
            popularity: 0,
            userPreference: 0,
            semanticSimilarity: 0
          }
        });
      }
    }

    return results.sort((a, b) => b.relevanceScore - a.relevanceScore);
  }

  private cosineSimilarity(vectorA: Map<string, number>, vectorB: Map<string, number>): number {
    const commonTerms = new Set([...vectorA.keys(), ...vectorB.keys()]);
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (const term of commonTerms) {
      const valA = vectorA.get(term) || 0;
      const valB = vectorB.get(term) || 0;

      dotProduct += valA * valB;
      normA += valA * valA;
      normB += valB * valB;
    }

    if (normA === 0 || normB === 0) return 0;

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }
}

/**
 * BM25 (Best Matching 25) Algorithm
 * Probabilistic ranking function for information retrieval
 */
export class BM25Algorithm {
  constructor(
    private k1: number = 1.5,  // Term frequency scaling factor
    private b: number = 0.75   // Length normalization factor
  ) {}

  scoreDocument(
    queryTerms: string[],
    document: string[],
    averageDocumentLength: number,
    totalDocuments: number,
    documentFrequency: Map<string, number>
  ): number {
    let score = 0;

    for (const term of queryTerms) {
      const termFreq = document.filter(word => word.toLowerCase() === term.toLowerCase()).length;
      const docFreq = documentFrequency.get(term.toLowerCase()) || 1;

      if (termFreq === 0) continue;

      // IDF (Inverse Document Frequency)
      const idf = Math.log((totalDocuments - docFreq + 0.5) / (docFreq + 0.5));

      // Term frequency component with length normalization
      const tfComponent = (termFreq * (this.k1 + 1)) /
                         (termFreq + this.k1 * (1 - this.b + this.b * (document.length / averageDocumentLength)));

      score += idf * tfComponent;
    }

    return score;
  }

  rankDocuments(
    query: string[],
    documents: SearchableDocument[],
    documentFrequency: Map<string, number>
  ): SearchResult[] {
    const totalDocuments = documents.length;
    const totalLength = documents.reduce((sum, doc) =>
      sum + doc.title.split(/\s+/).length + doc.content.split(/\s+/).length, 0
    );
    const averageDocumentLength = totalLength / totalDocuments;

    const results: SearchResult[] = [];

    for (const document of documents) {
      const docWords = [...document.title.split(/\s+/), ...document.content.split(/\s+/)];
      const score = this.scoreDocument(query, docWords, averageDocumentLength, totalDocuments, documentFrequency);

      if (score > 0) {
        results.push({
          documentId: document.id,
          relevanceScore: score,
          matchDetails: {
            titleMatches: [],
            contentMatches: [],
            exactPhrases: [],
            fuzzyMatches: []
          },
          rankingFactors: {
            textRelevance: score,
            recency: 0,
            popularity: 0,
            userPreference: 0,
            semanticSimilarity: 0
          }
        });
      }
    }

    return results.sort((a, b) => b.relevanceScore - a.relevanceScore);
  }
}

/**
 * PageRank-style Algorithm for Content Authority
 * Ranks documents based on citation and reference patterns
 */
export class ContentAuthorityAlgorithm {
  calculatePageRank(
    documents: SearchableDocument[],
    links: Map<string, string[]>, // documentId -> referenced documentIds
    dampingFactor: number = 0.85,
    iterations: number = 20
  ): Map<string, number> {
    const documentIds = documents.map(doc => doc.id);
    const numDocuments = documentIds.length;

    // Initialize PageRank values
    let pageRanks = new Map<string, number>();
    for (const id of documentIds) {
      pageRanks.set(id, 1 / numDocuments);
    }

    for (let iteration = 0; iteration < iterations; iteration++) {
      const newPageRanks = new Map<string, number>();

      for (const documentId of documentIds) {
        let rankSum = 0;

        // Find documents that link to this one (simplified - reverse links)
        for (const [sourceId, targets] of links) {
          if (targets.includes(documentId)) {
            const sourceRank = pageRanks.get(sourceId) || 0;
            const sourceOutlinks = targets.length;
            rankSum += sourceRank / sourceOutlinks;
          }
        }

        const newRank = (1 - dampingFactor) / numDocuments + dampingFactor * rankSum;
        newPageRanks.set(documentId, newRank);
      }

      pageRanks = newPageRanks;
    }

    return pageRanks;
  }
}

/**
 * Learning to Rank Algorithm
 * Combines multiple ranking signals using learned weights
 */
export class LearningToRankAlgorithm {
  constructor(private featureWeights: Map<string, number>) {}

  scoreDocument(
    document: SearchableDocument,
    query: SearchQuery,
    additionalFeatures: Map<string, number>
  ): number {
    let score = 0;

    // Text relevance features
    const textRelevance = this.calculateTextRelevance(document, query);
    score += (this.featureWeights.get('text_relevance') || 1) * textRelevance;

    // User preference features
    if (query.userContext) {
      const userPreference = this.calculateUserPreference(document, query.userContext);
      score += (this.featureWeights.get('user_preference') || 1) * userPreference;
    }

    // Recency features
    const recency = this.calculateRecencyScore(document);
    score += (this.featureWeights.get('recency') || 1) * recency;

    // Popularity features
    const popularity = document.metadata.get('popularity') as number || 0;
    score += (this.featureWeights.get('popularity') || 1) * popularity;

    // Additional features
    for (const [feature, value] of additionalFeatures) {
      const weight = this.featureWeights.get(feature) || 0;
      score += weight * value;
    }

    return score;
  }

  rankDocuments(
    documents: SearchableDocument[],
    query: SearchQuery,
    additionalFeatures: Map<string, Map<string, number>> = new Map()
  ): SearchResult[] {
    const results: SearchResult[] = [];

    for (const document of documents) {
      const docFeatures = additionalFeatures.get(document.id) || new Map();
      const relevanceScore = this.scoreDocument(document, query, docFeatures);

      results.push({
        documentId: document.id,
        relevanceScore,
        matchDetails: {
          titleMatches: [],
          contentMatches: [],
          exactPhrases: [],
          fuzzyMatches: []
        },
        rankingFactors: {
          textRelevance: this.calculateTextRelevance(document, query),
          recency: this.calculateRecencyScore(document),
          popularity: document.metadata.get('popularity') as number || 0,
          userPreference: query.userContext ? this.calculateUserPreference(document, query.userContext) : 0,
          semanticSimilarity: docFeatures.get('semantic_similarity') || 0
        }
      });
    }

    return results.sort((a, b) => b.relevanceScore - a.relevanceScore);
  }

  private calculateTextRelevance(document: SearchableDocument, query: SearchQuery): number {
    const queryTerms = query.text.toLowerCase().split(/\s+/);
    const title = document.title.toLowerCase();
    const content = document.content.toLowerCase();

    let score = 0;

    for (const term of queryTerms) {
      // Exact matches in title
      if (title.includes(term)) {
        score += 10;
      }
      // Exact matches in content
      else if (content.includes(term)) {
        score += 5;
      }
      // Partial matches
      else {
        const titleWords = title.split(/\s+/);
        const contentWords = content.split(/\s+/);

        const titleMatches = titleWords.filter(word => word.includes(term)).length;
        const contentMatches = contentWords.filter(word => word.includes(term)).length;

        score += titleMatches * 2 + contentMatches;
      }
    }

    return score;
  }

  private calculateUserPreference(document: SearchableDocument, userContext: any): number {
    let preference = 0;

    // Category preferences
    const category = document.metadata.get('category') as string;
    if (category && userContext.preferences.has(category)) {
      preference += userContext.preferences.get(category) * 5;
    }

    // Search history relevance
    for (const searchTerm of userContext.searchHistory) {
      if (document.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          document.content.toLowerCase().includes(searchTerm.toLowerCase())) {
        preference += 2;
      }
    }

    return preference;
  }

  private calculateRecencyScore(document: SearchableDocument): number {
    const createdAt = document.metadata.get('createdAt') as Date;
    if (!createdAt) return 0;

    const now = new Date();
    const ageInDays = (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60 * 24);

    // Exponential decay: newer documents get higher scores
    return Math.exp(-ageInDays / 365); // Half-life of 1 year
  }
}

/**
 * Query Understanding Algorithm
 * Analyzes and expands search queries for better results
 */
export class QueryUnderstandingAlgorithm {
  expandQuery(
    originalQuery: string,
    synonymMap: Map<string, string[]>,
    relatedTerms: Map<string, string[]>
  ): string[] {
    const terms = originalQuery.toLowerCase().split(/\s+/);
    const expandedTerms = new Set<string>(terms);

    for (const term of terms) {
      // Add synonyms
      const synonyms = synonymMap.get(term) || [];
      synonyms.forEach(synonym => expandedTerms.add(synonym));

      // Add related terms
      const related = relatedTerms.get(term) || [];
      related.forEach(rel => expandedTerms.add(rel));
    }

    return Array.from(expandedTerms);
  }

  identifyQueryIntent(query: string): {
    intent: 'informational' | 'navigational' | 'transactional' | 'commercial';
    confidence: number;
    entities: string[];
  } {
    const lowerQuery = query.toLowerCase();

    // Simple intent classification
    if (lowerQuery.includes('buy') || lowerQuery.includes('purchase') || lowerQuery.includes('price')) {
      return {
        intent: 'transactional',
        confidence: 0.8,
        entities: this.extractEntities(query, ['price', 'buy', 'purchase', 'order'])
      };
    }

    if (lowerQuery.includes('how') || lowerQuery.includes('what') || lowerQuery.includes('why')) {
      return {
        intent: 'informational',
        confidence: 0.7,
        entities: this.extractEntities(query, ['how', 'what', 'why', 'when', 'where'])
      };
    }

    if (lowerQuery.includes('website') || lowerQuery.includes('site') || lowerQuery.includes('page')) {
      return {
        intent: 'navigational',
        confidence: 0.6,
        entities: this.extractEntities(query, ['website', 'site', 'page', 'login', 'contact'])
      };
    }

    return {
      intent: 'commercial',
      confidence: 0.5,
      entities: []
    };
  }

  private extractEntities(query: string, keywords: string[]): string[] {
    const words = query.toLowerCase().split(/\s+/);
    return words.filter(word => keywords.some(keyword => word.includes(keyword)));
  }
}

/**
 * Diversity Ranking Algorithm
 * Ensures search results include diverse content categories
 */
export class DiversityRankingAlgorithm {
  rerankForDiversity(
    results: SearchResult[],
    documents: SearchableDocument[],
    diversityFactor: number = 0.3
  ): SearchResult[] {
    if (results.length === 0) return results;

    const documentMap = new Map(documents.map(doc => [doc.id, doc]));
    const categoryCounts = new Map<string, number>();
    const rerankedResults: SearchResult[] = [];

    for (const result of results) {
      const document = documentMap.get(result.documentId);
      if (!document) continue;

      const category = document.metadata.get('category') as string || 'uncategorized';
      const categoryCount = categoryCounts.get(category) || 0;

      // Apply diversity penalty for over-represented categories
      const diversityPenalty = Math.min(categoryCount * diversityFactor, result.relevanceScore * 0.5);
      const adjustedScore = result.relevanceScore - diversityPenalty;

      rerankedResults.push({
        ...result,
        relevanceScore: Math.max(adjustedScore, 0.1) // Minimum score to avoid zero
      });

      categoryCounts.set(category, categoryCount + 1);
    }

    return rerankedResults.sort((a, b) => b.relevanceScore - a.relevanceScore);
  }

  calculateDiversityScore(results: SearchResult[], documents: SearchableDocument[]): number {
    if (results.length === 0) return 0;

    const documentMap = new Map(documents.map(doc => [doc.id, doc]));
    const categories = new Set<string>();

    for (const result of results) {
      const document = documentMap.get(result.documentId);
      if (document) {
        const category = document.metadata.get('category') as string || 'uncategorized';
        categories.add(category);
      }
    }

    // Diversity score based on unique categories vs total results
    return categories.size / Math.min(results.length, 10); // Cap at 10 for normalization
  }
}

export class TopKHeap<T> {
  private heap: Array<{ item: T; score: number }> = [];
  private readonly maxSize: number;

  constructor(maxSize: number) {
    this.maxSize = maxSize;
  }

  push(item: T, score: number): void {
    if (this.heap.length < this.maxSize) {
      this.heap.push({ item, score });
      this.bubbleUp(this.heap.length - 1);
    } else if (score > this.heap[0].score) {
      this.heap[0] = { item, score };
      this.siftDown(0);
    }
  }

  drain(): T[] {
    const sorted = this.heap.sort((a, b) => b.score - a.score);
    return sorted.map(h => h.item);
  }

  size(): number {
    return this.heap.length;
  }

  private bubbleUp(index: number): void {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (this.heap[index].score >= this.heap[parentIndex].score) break;
      
      [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
      index = parentIndex;
    }
  }

  private siftDown(index: number): void {
    const length = this.heap.length;
    
    while (true) {
      let smallest = index;
      const leftChild = 2 * index + 1;
      const rightChild = 2 * index + 2;

      if (leftChild < length && this.heap[leftChild].score < this.heap[smallest].score) {
        smallest = leftChild;
      }

      if (rightChild < length && this.heap[rightChild].score < this.heap[smallest].score) {
        smallest = rightChild;
      }

      if (smallest === index) break;

      [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
      index = smallest;
    }
  }
}

/**
 * Catalog Matching Engine
 * 
 * Performance Envelope:
 * - Expected QPS: 10-20 (CPU intensive).
 * - Memory Limit: 256MB.
 * - Indexing Strategy: UNIQUE indexes on gtin/mpn/isbn/fingerprint.
 */

import { Product } from '../entities/product.entity';
import { MatchResult, MatchLevel } from '../value-objects/match-result.value-object';
import { ProductIdentifiers } from '../value-objects/product-identifiers.value-object';
import { ProductFingerprint } from '../value-objects/product-fingerprint.value-object';
import { MatchCriteriaBuilder } from './match-criteria.builder';
import { SimilarityAlgorithm } from '../algorithms/similarity.algorithm';
import { NormalizationAlgorithm } from '../algorithms/normalization.algorithm';

export interface ProductCandidate {
    identifiers?: ProductIdentifiers;
    fingerprint?: ProductFingerprint;
    brand: string;
    model: string;
    categoryId: string;
    attributes?: Record<string, any>;
}

export class CatalogMatchingEngine {
    /**
     * Evaluates a candidate product against a list of existing products to find a match.
     * 
     * Phased Cascade Semantics:
     * 1. Exact Match: Direct identifier equality (SKU/UPC). Threshold: 1.0.
     * 2. Strong Match: Fingerprint hash matching. Threshold: 0.95.
     * 3. Possible Match: Normalized similarity scoring. Threshold: >= 0.85.
     * 4. No Match: Fallback results.
     * 
     * @param candidate - The product data to be matched.
     * @param existingProducts - The catalog of products to compare against.
     * @returns A MatchResult with the level, score, and matched product ID.
     */
    static matchProduct(candidate: ProductCandidate, existingProducts: Product[]): MatchResult {
        // 1. Exact Match Check (Identifiers)
        if (candidate.identifiers && candidate.identifiers.hasAnyIdentifier()) {
            for (const existing of existingProducts) {
                const existingIds = existing.getIdentifiers();
                if (existingIds && candidate.identifiers.equals(existingIds)) {
                    const criteria = MatchCriteriaBuilder.buildCriteria(candidate, existing);
                    return new MatchResult({
                        level: MatchLevel.EXACT,
                        score: 100,
                        matchedProductId: existing.getId().toString(), // Assuming ProductId has toString()
                        criteria,
                        requiresConfirmation: false,
                    });
                }
            }
        }

        // 2. Strong Match Check (Fingerprint)
        if (candidate.fingerprint) {
            for (const existing of existingProducts) {
                const existingFingerprint = existing.getFingerprint();
                if (existingFingerprint && candidate.fingerprint.matches(existingFingerprint)) {
                    const criteria = MatchCriteriaBuilder.buildCriteria(candidate, existing);
                    return new MatchResult({
                        level: MatchLevel.STRONG,
                        score: 95,
                        matchedProductId: existing.getId().toString(),
                        criteria,
                        requiresConfirmation: false, // Strong matches are usually safe to auto-merge
                    });
                }
            }
        }

        // 3. Possible Match Check (Similarity)
        let bestPossibleMatch: MatchResult | null = null;
        let maxScore = 0;

        for (const existing of existingProducts) {
            // Filter by category first (should be done by query, but double check)
            if (existing.getCategoryId()?.toString() !== candidate.categoryId) continue;

            const existingBrand = existing.getBrand();
            const existingModel = existing.getModel();

            if (!existingBrand || !existingModel) continue;

            const normCandidateBrand = NormalizationAlgorithm.normalizeBrand(candidate.brand);
            const normExistingBrand = NormalizationAlgorithm.normalizeBrand(existingBrand);

            // Brand mismatch overrides similarity (unless very close typo?)
            // For now, strict on brand normalization
            if (normCandidateBrand !== normExistingBrand) continue;

            const normCandidateModel = NormalizationAlgorithm.normalizeModel(candidate.model);
            const normExistingModel = NormalizationAlgorithm.normalizeModel(existingModel);

            const similarity = SimilarityAlgorithm.calculateStringSimilarity(normCandidateModel, normExistingModel);

            if (similarity >= 0.85) {
                const score = similarity * 100;
                if (score > maxScore) {
                    maxScore = score;
                    const criteria = MatchCriteriaBuilder.buildCriteria(candidate, existing);
                    criteria.similarityScore = similarity;
                    criteria.brandMatch = true;
                    criteria.modelMatch = true; // High similarity implies model match

                    bestPossibleMatch = new MatchResult({
                        level: MatchLevel.POSSIBLE,
                        score: parseFloat(score.toFixed(2)),
                        matchedProductId: existing.getId().toString(),
                        criteria,
                        requiresConfirmation: true
                    });
                }
            }
        }

        if (bestPossibleMatch) {
            return bestPossibleMatch;
        }

        // 4. No Match
        return MatchResult.noMatch();
    }
}

/**
 * Recommendation Engine
 * Domain engine for product recommendation and personalization
 * Pure business logic - no side effects or external dependencies
 */

import { ProductId, SellerId } from '../value-objects/ids.value-object';
import { Price } from '../value-objects/monetary.value-object';
import { ProductType } from '../value-objects/product-types.value-object';

export interface UserProfile {
  userId: string;
  preferences: {
    categories: string[];
    priceRange: { min: number; max: number };
    brands: string[];
    productTypes: ProductType[];
  };
  behaviorHistory: {
    viewedProducts: ProductId[];
    purchasedProducts: ProductId[];
    cartAdditions: ProductId[];
    searchQueries: string[];
    categoriesBrowsed: string[];
  };
  demographics?: {
    ageGroup?: string;
    location?: string;
    deviceType?: 'mobile' | 'desktop' | 'tablet';
  };
}

export interface ProductFeatures {
  productId: ProductId;
  sellerId: SellerId;
  category: string;
  price: Price;
  type: ProductType;
  tags: string[];
  averageRating: number;
  reviewCount: number;
  popularityScore: number;
  seasonalityFactor: number;
  complementaryProducts: ProductId[];
  substituteProducts: ProductId[];
}

export interface RecommendationContext {
  userProfile?: UserProfile;
  currentProduct?: ProductId;
  category?: string;
  searchQuery?: string;
  occasion?: 'birthday' | 'anniversary' | 'holiday' | 'regular';
  maxRecommendations: number;
  includeViewedProducts: boolean;
}

export interface RecommendationResult {
  productId: ProductId;
  score: number;
  reason: string;
  confidence: number;
  strategy: string;
}

export class CollaborativeFilteringStrategy {
  recommend(context: RecommendationContext, availableProducts: ProductFeatures[]): RecommendationResult[] {
    if (!context.userProfile) {
      return [];
    }

    const userProfile = context.userProfile;
    const recommendations: RecommendationResult[] = [];

    for (const product of availableProducts) {
      let score = 0;
      const reasons: string[] = [];

      // Purchase history similarity
      if (userProfile.behaviorHistory.purchasedProducts.length > 0) {
        const similarPurchases = this.findSimilarProducts(
          product.productId,
          userProfile.behaviorHistory.purchasedProducts,
          availableProducts
        );

        if (similarPurchases.length > 0) {
          score += 0.4;
          reasons.push('Similar to previously purchased items');
        }
      }

      // View history analysis
      if (userProfile.behaviorHistory.viewedProducts.length > 0) {
        const viewedSimilar = this.findSimilarProducts(
          product.productId,
          userProfile.behaviorHistory.viewedProducts,
          availableProducts
        );

        if (viewedSimilar.length > 0) {
          score += 0.3;
          reasons.push('Similar to items you viewed');
        }
      }

      // Category preferences
      if (userProfile.preferences.categories.includes(product.category)) {
        score += 0.2;
        reasons.push('Matches your preferred categories');
      }

      // Price range compatibility
      const productPrice = product.price.toNumber();
      if (productPrice >= userProfile.preferences.priceRange.min &&
          productPrice <= userProfile.preferences.priceRange.max) {
        score += 0.1;
        reasons.push('Within your preferred price range');
      }

      if (score > 0) {
        recommendations.push({
          productId: product.productId,
          score,
          reason: reasons.join(', '),
          confidence: Math.min(score + 0.2, 1.0),
          strategy: 'collaborative_filtering'
        });
      }
    }

    return recommendations.sort((a, b) => b.score - a.score);
  }

  private findSimilarProducts(
    targetProduct: ProductId,
    userHistory: ProductId[],
    allProducts: ProductFeatures[]
  ): ProductFeatures[] {
    const targetProductData = allProducts.find(p => p.productId.toString() === targetProduct.toString());
    if (!targetProductData) return [];

    return allProducts.filter(product => {
      // Simple similarity based on category and price range
      const categoryMatch = product.category === targetProductData.category;
      const priceDiff = Math.abs(product.price.toNumber() - targetProductData.price.toNumber());
      const priceSimilarity = priceDiff / Math.max(product.price.toNumber(), targetProductData.price.toNumber());

      return categoryMatch && priceSimilarity < 0.3; // Within 30% price difference
    });
  }
}

export class ContentBasedStrategy {
  recommend(context: RecommendationContext, availableProducts: ProductFeatures[]): RecommendationResult[] {
    if (!context.currentProduct) {
      return [];
    }

    const currentProductData = availableProducts.find(p => p.productId.toString() === context.currentProduct!.toString());
    if (!currentProductData) return [];

    const recommendations: RecommendationResult[] = [];

    for (const product of availableProducts) {
      if (product.productId.toString() === context.currentProduct!.toString()) continue;

      let score = 0;
      const reasons: string[] = [];

      // Category similarity
      if (product.category === currentProductData.category) {
        score += 0.3;
        reasons.push('Same category');
      }

      // Price similarity
      const priceDiff = Math.abs(product.price.toNumber() - currentProductData.price.toNumber());
      const priceSimilarity = 1 - (priceDiff / Math.max(product.price.toNumber(), currentProductData.price.toNumber()));

      if (priceSimilarity > 0.7) {
        score += 0.25 * priceSimilarity;
        reasons.push('Similar price range');
      }

      // Tag similarity
      const commonTags = product.tags.filter(tag => currentProductData.tags.includes(tag));
      if (commonTags.length > 0) {
        score += 0.2 * (commonTags.length / Math.max(product.tags.length, currentProductData.tags.length));
        reasons.push(`Shares ${commonTags.length} common tags`);
      }

      // Complementary products
      if (currentProductData.complementaryProducts.some(id => id.toString() === product.productId.toString())) {
        score += 0.4;
        reasons.push('Frequently bought together');
      }

      if (score > 0.2) { // Minimum threshold
        recommendations.push({
          productId: product.productId,
          score,
          reason: reasons.join(', '),
          confidence: Math.min(score + 0.1, 0.95),
          strategy: 'content_based'
        });
      }
    }

    return recommendations.sort((a, b) => b.score - a.score);
  }
}

export class PopularityBasedStrategy {
  recommend(context: RecommendationContext, availableProducts: ProductFeatures[]): RecommendationResult[] {
    const recommendations: RecommendationResult[] = [];

    // Sort by popularity score and recency factors
    const sortedProducts = availableProducts
      .filter(product => {
        // Filter out viewed products if requested
        if (!context.includeViewedProducts && context.userProfile) {
          return !context.userProfile.behaviorHistory.viewedProducts
            .some(viewedId => viewedId.toString() === product.productId.toString());
        }
        return true;
      })
      .sort((a, b) => {
        // Composite score: popularity + rating + review count
        const scoreA = a.popularityScore + (a.averageRating * 0.2) + (Math.log(a.reviewCount + 1) * 0.1);
        const scoreB = b.popularityScore + (b.averageRating * 0.2) + (Math.log(b.reviewCount + 1) * 0.1);
        return scoreB - scoreA;
      });

    for (const product of sortedProducts.slice(0, context.maxRecommendations)) {
      recommendations.push({
        productId: product.productId,
        score: product.popularityScore,
        reason: `Popular item with ${product.reviewCount} reviews and ${product.averageRating} rating`,
        confidence: 0.8,
        strategy: 'popularity_based'
      });
    }

    return recommendations;
  }
}

export class SeasonalStrategy {
  recommend(context: RecommendationContext, availableProducts: ProductFeatures[]): RecommendationResult[] {
    const recommendations: RecommendationResult[] = [];
    const currentMonth = new Date().getMonth() + 1; // 1-12

    // Seasonal relevance based on month
    const seasonalProducts = availableProducts
      .filter(product => product.seasonalityFactor > 1.0)
      .sort((a, b) => b.seasonalityFactor - a.seasonalityFactor);

    for (const product of seasonalProducts.slice(0, Math.min(5, context.maxRecommendations))) {
      const seasonalBoost = product.seasonalityFactor;
      recommendations.push({
        productId: product.productId,
        score: seasonalBoost,
        reason: `Seasonally relevant for ${this.getSeasonName(currentMonth)}`,
        confidence: Math.min(seasonalBoost * 0.1, 0.9),
        strategy: 'seasonal'
      });
    }

    return recommendations;
  }

  private getSeasonName(month: number): string {
    if (month >= 12 || month <= 2) return 'winter';
    if (month >= 3 && month <= 5) return 'spring';
    if (month >= 6 && month <= 8) return 'summer';
    return 'fall';
  }
}

export class RecommendationEngine {
  constructor(
    private readonly strategies: Array<{
      strategy: any;
      weight: number;
      enabled: boolean;
    }> = [
      { strategy: new CollaborativeFilteringStrategy(), weight: 0.4, enabled: true },
      { strategy: new ContentBasedStrategy(), weight: 0.3, enabled: true },
      { strategy: new PopularityBasedStrategy(), weight: 0.2, enabled: true },
      { strategy: new SeasonalStrategy(), weight: 0.1, enabled: true }
    ]
  ) {}

  generateRecommendations(
    context: RecommendationContext,
    availableProducts: ProductFeatures[]
  ): RecommendationResult[] {
    const allRecommendations: RecommendationResult[] = [];

    // Execute each enabled strategy
    for (const { strategy, weight, enabled } of this.strategies) {
      if (!enabled) continue;

      try {
        const strategyResults = strategy.recommend(context, availableProducts);

        // Apply strategy weight to scores
        const weightedResults = strategyResults.map((result: RecommendationResult) => ({
          ...result,
          score: result.score * weight,
          confidence: result.confidence * weight
        }));

        allRecommendations.push(...weightedResults);
      } catch (error) {
        // Strategy failure shouldn't break recommendations
        console.warn(`Recommendation strategy failed:`, error);
      }
    }

    // Aggregate and deduplicate recommendations
    const aggregatedResults = this.aggregateRecommendations(allRecommendations);

    // Sort by final score and limit results
    return aggregatedResults
      .sort((a, b) => b.score - a.score)
      .slice(0, context.maxRecommendations);
  }

  generateComplementaryProducts(
    productId: ProductId,
    availableProducts: ProductFeatures[],
    maxRecommendations: number = 5
  ): RecommendationResult[] {
    const productData = availableProducts.find(p => p.productId.toString() === productId.toString());
    if (!productData) return [];

    const recommendations: RecommendationResult[] = [];

    // Find complementary products
    for (const complementaryId of productData.complementaryProducts) {
      const complementaryProduct = availableProducts.find(p => p.productId.toString() === complementaryId.toString());
      if (complementaryProduct) {
        recommendations.push({
          productId: complementaryProduct.productId,
          score: 0.9,
          reason: 'Frequently bought together',
          confidence: 0.85,
          strategy: 'complementary'
        });
      }
    }

    return recommendations.slice(0, maxRecommendations);
  }

  generateSubstituteProducts(
    productId: ProductId,
    availableProducts: ProductFeatures[],
    maxRecommendations: number = 3
  ): RecommendationResult[] {
    const productData = availableProducts.find(p => p.productId.toString() === productId.toString());
    if (!productData) return [];

    const recommendations: RecommendationResult[] = [];

    // Find substitute products
    for (const substituteId of productData.substituteProducts) {
      const substituteProduct = availableProducts.find(p => p.productId.toString() === substituteId.toString());
      if (substituteProduct) {
        recommendations.push({
          productId: substituteProduct.productId,
          score: 0.7,
          reason: 'Similar alternative product',
          confidence: 0.75,
          strategy: 'substitute'
        });
      }
    }

    return recommendations.slice(0, maxRecommendations);
  }

  analyzeRecommendationDiversity(recommendations: RecommendationResult[]): {
    categoryDiversity: number;
    priceDiversity: number;
    typeDiversity: number;
    overallDiversity: number;
  } {
    if (recommendations.length === 0) {
      return { categoryDiversity: 0, priceDiversity: 0, typeDiversity: 0, overallDiversity: 0 };
    }

    // This would require product metadata - simplified implementation
    const categories = new Set(recommendations.map(r => 'category_' + Math.floor(Math.random() * 5)));
    const priceRanges = new Set(recommendations.map(r => Math.floor(r.score * 10)));
    const types = new Set(recommendations.map(r => 'type_' + Math.floor(Math.random() * 3)));

    const categoryDiversity = categories.size / recommendations.length;
    const priceDiversity = priceRanges.size / recommendations.length;
    const typeDiversity = types.size / recommendations.length;
    const overallDiversity = (categoryDiversity + priceDiversity + typeDiversity) / 3;

    return {
      categoryDiversity,
      priceDiversity,
      typeDiversity,
      overallDiversity
    };
  }

  private aggregateRecommendations(recommendations: RecommendationResult[]): RecommendationResult[] {
    const productMap = new Map<string, RecommendationResult>();

    for (const rec of recommendations) {
      const key = rec.productId.toString();
      const existing = productMap.get(key);

      if (existing) {
        // Combine scores and reasons
        existing.score = Math.max(existing.score, rec.score);
        existing.confidence = Math.max(existing.confidence, rec.confidence);
        existing.reason = existing.reason.includes(rec.reason)
          ? existing.reason
          : `${existing.reason}, ${rec.reason}`;
      } else {
        productMap.set(key, { ...rec });
      }
    }

    return Array.from(productMap.values());
  }
}

/**
 * Search Engine
 * Domain engine for product search and filtering logic.
 * 
 * Performance Envelope:
 * - Expected QPS: 200-500 depending on query complexity.
 * - Memory Limit: 512MB (cached product metadata).
 * - Indexing Strategy: GIN indexes on tags, B-Tree on category/brand/price.
 * 
 * Strategy Responsibilities:
 * - TextSearchStrategy: Handles tokenization and relevance scoring.
 * - FilterStrategy: Handles Boolean filtering and range checks.
 */

import { ProductId, SellerId } from '../value-objects/ids.value-object';
import { Price } from '../value-objects/monetary.value-object';
import { ProductType, ProductStatus, ProductVisibility } from '../value-objects/product-types.value-object';

export interface SearchableProduct {
  productId: ProductId;
  sellerId: SellerId;
  name: string;
  description: string;
  type: ProductType;
  status: ProductStatus;
  visibility: ProductVisibility;
  price: Price;
  originalPrice?: Price;
  tags: string[];
  category: string;
  subcategory?: string;
  brand?: string;
  sku?: string;
  averageRating: number;
  reviewCount: number;
  inStock: boolean;
  isOnSale: boolean;
  popularityScore: number;
  createdAt: Date;
  updatedAt: Date;
}

export interface SearchQuery {
  text?: string;
  category?: string;
  subcategory?: string;
  brand?: string;
  minPrice?: number;
  maxPrice?: number;
  productType?: ProductType;
  inStockOnly?: boolean;
  onSaleOnly?: boolean;
  minRating?: number;
  tags?: string[];
  sortBy?: 'relevance' | 'price_asc' | 'price_desc' | 'rating' | 'popularity' | 'newest';
  limit?: number;
  offset?: number;
}

export interface SearchResult {
  productId: ProductId;
  relevanceScore: number;
  matchReasons: string[];
  highlights?: Record<string, string[]>;
}

export interface FacetResult {
  name: string;
  value: string;
  count: number;
  selected: boolean;
}

export interface SearchResponse {
  results: SearchResult[];
  totalCount: number;
  facets: {
    categories: FacetResult[];
    brands: FacetResult[];
    priceRanges: FacetResult[];
    ratings: FacetResult[];
    productTypes: FacetResult[];
  };
  query: SearchQuery;
  executionTime: number;
}

export class TextSearchStrategy {
  /**
   * Executes a text-based search across a list of products.
   * 
   * @param query - The search query containing the text to look for.
   * @param products - The collection of searchable products.
   * @returns A sorted array of search results with relevance scores.
   */
  search(query: SearchQuery, products: SearchableProduct[]): SearchResult[] {
    if (!query.text) return [];

    const searchTerms = this.tokenizeQuery(query.text.toLowerCase());
    const results: SearchResult[] = [];

    for (const product of products) {
      const score = this.calculateTextRelevance(product, searchTerms);
      if (score > 0) {
        const matchReasons = this.getMatchReasons(product, searchTerms);
        const highlights = this.generateHighlights(product, searchTerms);

        results.push({
          productId: product.productId,
          relevanceScore: score,
          matchReasons,
          highlights
        });
      }
    }

    return results.sort((a, b) => b.relevanceScore - a.relevanceScore);
  }

  private tokenizeQuery(query: string): string[] {
    const stopWords = ['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by'];
    return query
      .split(/\s+/)
      .filter(word => word.length > 2 && !stopWords.includes(word))
      .map(word => word.toLowerCase());
  }

  /**
   * Calculates a relevance score for a product based on weighted text matches.
   * 
   * Weights:
   * - Name match: 10 pts
   * - Description match: 5 pts
   * - Tags/Category match: 2 pts
   * - Fuzzy match: 0.5 pts per word
   * - Exact phrase in name: 1.5x multiplier
   */
  private calculateTextRelevance(product: SearchableProduct, searchTerms: string[]): number {
    let totalScore = 0;
    const searchableText = [
      product.name,
      product.description,
      product.category,
      product.subcategory,
      product.brand,
      ...product.tags
    ].join(' ').toLowerCase();

    for (const term of searchTerms) {
      if (product.name.toLowerCase().includes(term)) {
        totalScore += 10;
      }
      else if (product.description.toLowerCase().includes(term)) {
        totalScore += 5;
      }
      else if (searchableText.includes(term)) {
        totalScore += 2;
      }
      else {
        const fuzzyMatches = searchableText.split(/\s+/).filter(word =>
          word.includes(term) || term.includes(word) || this.levenshteinDistance(word, term) <= 2
        );
        totalScore += fuzzyMatches.length * 0.5;
      }
    }

    const queryPhrase = searchTerms.join(' ');
    if (product.name.toLowerCase().includes(queryPhrase)) {
      totalScore *= 1.5;
    }

    return totalScore;
  }

  private levenshteinDistance(a: string, b: string): number {
    if (a === b) return 0;
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;

    const [short, long] = a.length < b.length ? [a, b] : [b, a];
    let prevRow = Array.from({ length: short.length + 1 }, (_, i) => i);
    let currRow = new Array(short.length + 1);

    for (let i = 1; i <= long.length; i++) {
      currRow[0] = i;
      for (let j = 1; j <= short.length; j++) {
        const cost = long[i - 1] === short[j - 1] ? 0 : 1;
        currRow[j] = Math.min(
          prevRow[j] + 1,
          currRow[j - 1] + 1,
          prevRow[j - 1] + cost
        );
      }
      [prevRow, currRow] = [currRow, prevRow];
    }

    return prevRow[short.length];
  }

  private getMatchReasons(product: SearchableProduct, searchTerms: string[]): string[] {
    const reasons: string[] = [];

    for (const term of searchTerms) {
      if (product.name.toLowerCase().includes(term)) {
        reasons.push(`Name contains "${term}"`);
      }
      if (product.description.toLowerCase().includes(term)) {
        reasons.push(`Description contains "${term}"`);
      }
      if (product.tags.some(tag => tag.toLowerCase().includes(term))) {
        reasons.push(`Tag contains "${term}"`);
      }
      if (product.category.toLowerCase().includes(term)) {
        reasons.push(`Category contains "${term}"`);
      }
    }

    return Array.from(new Set(reasons)); // Remove duplicates
  }

  private generateHighlights(product: SearchableProduct, searchTerms: string[]): Record<string, string[]> {
    const highlights: Record<string, string[]> = {};

    for (const term of searchTerms) {
      const nameHighlights = this.findHighlights(product.name, term);
      if (nameHighlights.length > 0) {
        highlights.name = highlights.name || [];
        highlights.name.push(...nameHighlights);
      }

      const descHighlights = this.findHighlights(product.description, term);
      if (descHighlights.length > 0) {
        highlights.description = highlights.description || [];
        highlights.description.push(...descHighlights);
      }
    }

    return highlights;
  }

  private findHighlights(text: string, term: string): string[] {
    const highlights: string[] = [];
    const words = text.split(/\s+/);
    const termLower = term.toLowerCase();

    for (let i = 0; i < words.length; i++) {
      if (words[i].toLowerCase().includes(termLower)) {
        const start = Math.max(0, i - 2);
        const end = Math.min(words.length, i + 3);
        const snippet = words.slice(start, end).join(' ');
        highlights.push(snippet);
      }
    }

    return highlights.slice(0, 3); // Limit to 3 highlights
  }
}

export class FilterStrategy {
  /**
   * Filters a list of products based on category, price, stock, ratings, and tags.
   */
  applyFilters(query: SearchQuery, products: SearchableProduct[]): SearchableProduct[] {
    return products.filter(product => {
      // Category filter
      if (query.category && product.category !== query.category) {
        return false;
      }

      // Subcategory filter
      if (query.subcategory && product.subcategory !== query.subcategory) {
        return false;
      }

      // Brand filter
      if (query.brand && product.brand !== query.brand) {
        return false;
      }

      // Price range filter
      if (query.minPrice !== undefined && product.price.toNumber() < query.minPrice) {
        return false;
      }
      if (query.maxPrice !== undefined && product.price.toNumber() > query.maxPrice) {
        return false;
      }

      // Product type filter
      if (query.productType && product.type !== query.productType) {
        return false;
      }

      // Stock status filter
      if (query.inStockOnly && !product.inStock) {
        return false;
      }

      // Sale status filter
      if (query.onSaleOnly && !product.isOnSale) {
        return false;
      }

      // Rating filter
      if (query.minRating !== undefined && product.averageRating < query.minRating) {
        return false;
      }

      // Tags filter
      if (query.tags && query.tags.length > 0) {
        const hasAllTags = query.tags.every(tag =>
          product.tags.some(productTag =>
            productTag.toLowerCase().includes(tag.toLowerCase())
          )
        );
        if (!hasAllTags) {
          return false;
        }
      }

      // Visibility filter (only show public products by default)
      if (product.visibility !== ProductVisibility.PUBLIC && product.visibility !== ProductVisibility.B2B_ONLY) {
        return false;
      }

      // Status filter (only show published products)
      if (product.status !== ProductStatus.PUBLISHED) {
        return false;
      }

      return true;
    });
  }
}

export class SortStrategy {
  /**
   * Sorts search results by relevance, price, rating, or popularity.
   */
  sort(results: SearchResult[], query: SearchQuery, products: SearchableProduct[]): SearchResult[] {
    const sortBy = query.sortBy || 'relevance';

    const productMap = new Map(products.map(p => [p.productId.toString(), p]));

    return results.sort((a, b) => {
      switch (sortBy) {
        case 'price_asc':
          const priceA = productMap.get(a.productId.toString())?.price.toNumber() || 0;
          const priceB = productMap.get(b.productId.toString())?.price.toNumber() || 0;
          return priceA - priceB;

        case 'price_desc':
          const priceDescA = productMap.get(a.productId.toString())?.price.toNumber() || 0;
          const priceDescB = productMap.get(b.productId.toString())?.price.toNumber() || 0;
          return priceDescB - priceDescA;

        case 'rating':
          const ratingA = productMap.get(a.productId.toString())?.averageRating || 0;
          const ratingB = productMap.get(b.productId.toString())?.averageRating || 0;
          if (ratingB !== ratingA) return ratingB - ratingA;
          // Secondary sort by review count
          const reviewsA = productMap.get(a.productId.toString())?.reviewCount || 0;
          const reviewsB = productMap.get(b.productId.toString())?.reviewCount || 0;
          return reviewsB - reviewsA;

        case 'popularity':
          const popA = productMap.get(a.productId.toString())?.popularityScore || 0;
          const popB = productMap.get(b.productId.toString())?.popularityScore || 0;
          return popB - popA;

        case 'newest':
          const dateA = productMap.get(a.productId.toString())?.createdAt || new Date(0);
          const dateB = productMap.get(b.productId.toString())?.createdAt || new Date(0);
          return dateB.getTime() - dateA.getTime();

        case 'relevance':
        default:
          return b.relevanceScore - a.relevanceScore;
      }
    });
  }
}

export class FacetStrategy {
  /**
   * Aggregates facet counts for categories, brands, price ranges, and ratings.
   */
  generateFacets(products: SearchableProduct[], query: SearchQuery): SearchResponse['facets'] {
    const facets = {
      categories: [] as FacetResult[],
      brands: [] as FacetResult[],
      priceRanges: [] as FacetResult[],
      ratings: [] as FacetResult[],
      productTypes: [] as FacetResult[]
    };

    // Category facets
    const categoryCounts = new Map<string, number>();
    products.forEach(product => {
      const count = categoryCounts.get(product.category) || 0;
      categoryCounts.set(product.category, count + 1);
    });
    facets.categories = Array.from(categoryCounts.entries()).map(([value, count]) => ({
      name: 'category',
      value,
      count,
      selected: query.category === value
    }));

    // Brand facets
    const brandCounts = new Map<string, number>();
    products.forEach(product => {
      if (product.brand) {
        const count = brandCounts.get(product.brand) || 0;
        brandCounts.set(product.brand, count + 1);
      }
    });
    facets.brands = Array.from(brandCounts.entries()).map(([value, count]) => ({
      name: 'brand',
      value,
      count,
      selected: query.brand === value
    }));

    // Price range facets
    const priceRanges = [
      { label: 'Under $25', min: 0, max: 25 },
      { label: '$25 - $50', min: 25, max: 50 },
      { label: '$50 - $100', min: 50, max: 100 },
      { label: '$100 - $200', min: 100, max: 200 },
      { label: 'Over $200', min: 200, max: Infinity }
    ];

    facets.priceRanges = priceRanges.map(range => {
      const count = products.filter(p => {
        const price = p.price.toNumber();
        return price >= range.min && price < range.max;
      }).length;

      return {
        name: 'price_range',
        value: range.label,
        count,
        selected: false // Would need more complex logic for range selection
      };
    });

    // Rating facets
    const ratingRanges = [
      { label: '4+ stars', min: 4.0 },
      { label: '3+ stars', min: 3.0 },
      { label: '2+ stars', min: 2.0 },
      { label: '1+ star', min: 1.0 }
    ];

    facets.ratings = ratingRanges.map(range => {
      const count = products.filter(p => p.averageRating >= range.min).length;
      return {
        name: 'rating',
        value: range.label,
        count,
        selected: query.minRating === range.min
      };
    });

    // Product type facets
    const typeCounts = new Map<ProductType, number>();
    products.forEach(product => {
      const count = typeCounts.get(product.type) || 0;
      typeCounts.set(product.type, count + 1);
    });
    facets.productTypes = Array.from(typeCounts.entries()).map(([value, count]) => ({
      name: 'product_type',
      value,
      count,
      selected: query.productType === value
    }));

    return facets;
  }
}

export class ProductSearchEngine {
  constructor(
    private readonly textSearchStrategy: TextSearchStrategy = new TextSearchStrategy(),
    private readonly filterStrategy: FilterStrategy = new FilterStrategy(),
    private readonly sortStrategy: SortStrategy = new SortStrategy(),
    private readonly facetStrategy: FacetStrategy = new FacetStrategy()
  ) { }

  /**
   * Orchestrates the full search lifecycle: filtering, text search, sorting, and facet generation.
   * 
   * @param query - The search query and filters.
   * @param products - The full catalog of products.
   * @returns A search response with results, metadata, and facets.
   */
  search(query: SearchQuery, products: SearchableProduct[]): SearchResponse {
    const startTime = Date.now();

    // Apply filters first
    let filteredProducts = this.filterStrategy.applyFilters(query, products);

    // Perform text search if query text is provided
    let searchResults: SearchResult[] = [];
    if (query.text) {
      searchResults = this.textSearchStrategy.search(query, filteredProducts);
      // Convert search results back to products for further processing
      const searchProductIds = new Set(searchResults.map(r => r.productId.toString()));
      filteredProducts = filteredProducts.filter(p => searchProductIds.has(p.productId.toString()));
    } else {
      // If no text search, create results for all filtered products
      searchResults = filteredProducts.map(product => ({
        productId: product.productId,
        relevanceScore: 1.0,
        matchReasons: ['Filtered result']
      }));
    }

    // Apply sorting
    const sortedResults = this.sortStrategy.sort(searchResults, query, filteredProducts);

    // Apply pagination
    const offset = query.offset || 0;
    const limit = query.limit || 50;
    const paginatedResults = sortedResults.slice(offset, offset + limit);

    // Generate facets
    const facets = this.facetStrategy.generateFacets(filteredProducts, query);

    const executionTime = Date.now() - startTime;

    return {
      results: paginatedResults,
      totalCount: sortedResults.length,
      facets,
      query,
      executionTime
    };
  }

  /**
   * Generates query suggestions based on partial input and popular query history.
   * Uses prefix matching and fuzzy matching as a fallback.
   */
  suggestQueries(partialQuery: string, popularQueries: string[], maxSuggestions: number = 5): string[] {
    if (!partialQuery.trim()) {
      return popularQueries.slice(0, maxSuggestions);
    }

    const suggestions: string[] = [];
    const queryLower = partialQuery.toLowerCase();

    // Exact prefix matches
    const prefixMatches = popularQueries
      .filter(query => query.toLowerCase().startsWith(queryLower))
      .sort((a, b) => a.length - b.length); // Shorter matches first

    suggestions.push(...prefixMatches.slice(0, maxSuggestions));

    // Fuzzy matches if we don't have enough suggestions
    if (suggestions.length < maxSuggestions) {
      const fuzzyMatches = popularQueries
        .filter(query =>
          !suggestions.includes(query) &&
          (query.toLowerCase().includes(queryLower) ||
            this.levenshteinDistance(query.toLowerCase(), queryLower) <= 2)
        )
        .sort((a, b) => this.levenshteinDistance(a.toLowerCase(), queryLower) -
          this.levenshteinDistance(b.toLowerCase(), queryLower));

      suggestions.push(...fuzzyMatches.slice(0, maxSuggestions - suggestions.length));
    }

    return suggestions.slice(0, maxSuggestions);
  }

  /**
   * Analyzes search result metrics to provide quality insights.
   * 
   * @returns Scores for effectiveness, diversity, and relevance with actionable recommendations.
   */
  analyzeSearchPerformance(searchResponse: SearchResponse): {
    effectiveness: number;
    diversity: number;
    relevance: number;
    recommendations: string[];
  } {
    const { results, facets, executionTime } = searchResponse;

    // Effectiveness: Ratio of results to total available
    const effectiveness = results.length > 0 ? Math.min(results.length / 50, 1) : 0; // Assume max 50 results

    // Diversity: Based on category and price distribution
    const categories = new Set(facets.categories.map(c => c.value));
    const categoryDiversity = categories.size / Math.max(facets.categories.length, 1);

    const priceRanges = facets.priceRanges.filter(r => r.count > 0);
    const priceDiversity = priceRanges.length / facets.priceRanges.length;

    const diversity = (categoryDiversity + priceDiversity) / 2;

    // Relevance: Average relevance score
    const avgRelevance = results.length > 0
      ? results.reduce((sum, r) => sum + r.relevanceScore, 0) / results.length
      : 0;

    const relevance = Math.min(avgRelevance, 1);

    // Generate recommendations
    const recommendations: string[] = [];

    if (effectiveness < 0.5) {
      recommendations.push('Consider broadening search criteria or reducing filters');
    }
    if (diversity < 0.3) {
      recommendations.push('Search results lack diversity - consider adjusting ranking algorithm');
    }
    if (relevance < 0.7) {
      recommendations.push('Low relevance scores - review search algorithm weighting');
    }
    if (executionTime > 100) {
      recommendations.push('Search performance is slow - consider optimization');
    }

    return {
      effectiveness,
      diversity,
      relevance,
      recommendations
    };
  }

  private levenshteinDistance(a: string, b: string): number {
    if (a === b) return 0;
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;

    const [short, long] = a.length < b.length ? [a, b] : [b, a];
    let prevRow = Array.from({ length: short.length + 1 }, (_, i) => i);
    let currRow = new Array(short.length + 1);

    for (let i = 1; i <= long.length; i++) {
      currRow[0] = i;
      for (let j = 1; j <= short.length; j++) {
        const cost = long[i - 1] === short[j - 1] ? 0 : 1;
        currRow[j] = Math.min(
          prevRow[j] + 1,
          currRow[j - 1] + 1,
          prevRow[j - 1] + cost
        );
      }
      [prevRow, currRow] = [currRow, prevRow];
    }

    return prevRow[short.length];
  }
}

