/**
 * Product Entity
 * Domain entity representing a catalog product
 */

import { ProductId, SellerId, CategoryId } from '../value-objects/ids.value-object';
import { Price, CostPrice, WholesalePricing } from '../value-objects/monetary.value-object';
import {
  ProductStatus,
  ProductStatusValue,
  ProductVisibility,
  ProductType,
  Dimensions,
  Weight,
  SEOData,
  ShippingInfo,
  ProductCondition
} from '../value-objects/product-types.value-object';
import { ProductIdentifiers } from '../value-objects/product-identifiers.value-object';
import { ProductFingerprint } from '../value-objects/product-fingerprint.value-object';

export interface ProductVariantLike {
  getId(): string;
  getSku(): string;
  getName(): string;
  getPrice(): Price;
  getCompareAtPrice(): Price | undefined;
  getCostPrice(): CostPrice | undefined;
  getInventoryQuantity(): number;
  getAttributes(): Record<string, string>;
  isInStock(): boolean;
  isOnSale(): boolean;
  calculateMargin(): number | null;
}

export class ProductVariant implements ProductVariantLike {
  constructor(
    private readonly id: string,
    private readonly sku: string,
    private readonly name: string,
    private readonly price: Price,
    private readonly compareAtPrice?: Price,
    private readonly costPrice?: CostPrice,
    private readonly inventoryQuantity: number = 0,
    private readonly attributes: Record<string, string> = {}
  ) { }

  getId(): string {
    return this.id;
  }

  getSku(): string {
    return this.sku;
  }

  getName(): string {
    return this.name;
  }

  getPrice(): Price {
    return this.price;
  }

  getCompareAtPrice(): Price | undefined {
    return this.compareAtPrice;
  }

  getCostPrice(): CostPrice | undefined {
    return this.costPrice;
  }

  getInventoryQuantity(): number {
    return this.inventoryQuantity;
  }

  getAttributes(): Record<string, string> {
    return { ...this.attributes };
  }

  isInStock(): boolean {
    return this.inventoryQuantity > 0;
  }

  isOnSale(): boolean {
    return this.compareAtPrice !== undefined && this.price.isLessThan(this.compareAtPrice);
  }

  calculateMargin(): number | null {
    if (!this.costPrice) return null;
    return this.costPrice.calculateMargin(this.price);
  }
}

export class Product {
  constructor(
    id: string,
    name: string,
    description: string,
    categoryId: string,
    sku: string,
    price: { amount: number; currency: string; originalPrice?: number; discountPercentage?: number },
    inventory: { quantity?: number; status?: string; reserved?: number; available?: number; lowStockThreshold?: number },
    media?: { images?: string[]; videos?: string[]; documents?: string[] },
    attributes?: Record<string, unknown>,
    tags?: string[],
    status?: string,
    visibility?: string,
    createdAt?: Date,
    updatedAt?: Date,
    publishedAt?: Date,
    shipping?: unknown
  );
  constructor(
    id: ProductId,
    sellerId: SellerId,
    name: string,
    description: string,
    status: ProductStatusValue,
    type: ProductType,
    visibility?: ProductVisibility,
    categoryId?: CategoryId,
    variants?: ProductVariantLike[],
    images?: string[],
    tags?: string[],
    seoData?: SEOData,
    shippingInfo?: ShippingInfo,
    condition?: ProductCondition,
    identifiers?: ProductIdentifiers,
    fingerprint?: ProductFingerprint,
    createdAt?: Date,
    updatedAt?: Date
  );
  constructor(
    private readonly id: ProductId,
    private readonly sellerId: SellerId,
    private readonly name: string,
    private readonly description: string,
    private readonly status: ProductStatusValue,
    private readonly type: ProductType,
    private readonly visibility: ProductVisibility = ProductVisibility.PUBLIC,
    private readonly categoryId?: CategoryId,
    private readonly brand?: string,
    private readonly model?: string,
    private readonly variants: ProductVariantLike[] = [],
    private readonly images: string[] = [],
    private readonly tags: string[] = [],
    private readonly seoData?: SEOData,
    private readonly shippingInfo?: ShippingInfo,
    private readonly condition: ProductCondition = ProductCondition.NEW,
    private readonly identifiers?: ProductIdentifiers,
    private readonly fingerprint?: ProductFingerprint,
    private readonly createdAt: Date = new Date(),
    private readonly updatedAt: Date = new Date(),
    private readonly enablerEnabled: boolean = false,
    private readonly enablerCommissionRate?: number
  ) {
    // Backward-compatible argument normalization for legacy constructor ordering.
    if (Array.isArray(this.brand)) {
      const legacyVariants = this.brand;
      const legacyImages = Array.isArray(this.model) ? this.model : [];
      const legacyTags = Array.isArray(this.variants) ? this.variants : [];
      (this as any).variants = legacyVariants;
      (this as any).images = legacyImages;
      (this as any).tags = legacyTags;
      (this as any).brand = undefined;
      (this as any).model = undefined;
    }

    if (!name.trim()) {
      throw new Error('Product name cannot be empty');
    }
    if (!description.trim()) {
      throw new Error('Product description cannot be empty');
    }
    if (this.variants.length === 0) {
      throw new Error('Product must have at least one variant');
    }
  }

  getId(): ProductId {
    return this.id;
  }

  getSellerId(): SellerId {
    return this.sellerId;
  }

  getName(): string {
    return this.name;
  }

  getDescription(): string {
    return this.description;
  }

  getStatus(): ProductStatusValue {
    return this.status;
  }

  getType(): ProductType {
    return this.type;
  }

  getVisibility(): ProductVisibility {
    return this.visibility;
  }

  getCategoryId(): CategoryId | undefined {
    return this.categoryId;
  }

  getBrand(): string | undefined {
    return this.brand;
  }

  getModel(): string | undefined {
    return this.model;
  }

  getVariants(): ProductVariantLike[] {
    return [...this.variants];
  }

  getDefaultVariant(): ProductVariantLike {
    return this.variants[0];
  }

  getImages(): string[] {
    return [...this.images];
  }

  getTags(): string[] {
    return [...this.tags];
  }

  getSeoData(): SEOData | undefined {
    return this.seoData;
  }

  getShippingInfo(): ShippingInfo | undefined {
    return this.shippingInfo;
  }

  getCondition(): ProductCondition {
    return this.condition;
  }

  getCreatedAt(): Date {
    return this.createdAt;
  }

  getEnablerEnabled(): boolean {
    return this.enablerEnabled;
  }

  getEnablerCommissionRate(): number | undefined {
    return this.enablerCommissionRate;
  }

  getUpdatedAt(): Date {
    return this.updatedAt;
  }

  getIdentifiers(): ProductIdentifiers | undefined {
    return this.identifiers;
  }

  getFingerprint(): ProductFingerprint | undefined {
    return this.fingerprint;
  }

  // Business logic methods
  isPublished(): boolean {
    return this.status.isPublished();
  }

  isActive(): boolean {
    return this.status.isActive();
  }

  isVisibleToPublic(): boolean {
    return this.visibility === ProductVisibility.PUBLIC;
  }

  hasVariants(): boolean {
    return this.variants.length > 1;
  }

  getTotalInventory(): number {
    return this.variants.reduce((total, variant) => total + variant.getInventoryQuantity(), 0);
  }

  isInStock(): boolean {
    return this.getTotalInventory() > 0;
  }

  getPriceRange(): { min: Price; max: Price } {
    const prices = this.variants.map(v => v.getPrice());
    const minPrice = prices.reduce((min, price) => price.isLessThan(min) ? price : min);
    const maxPrice = prices.reduce((max, price) => price.isGreaterThan(max) ? price : max);

    return { min: minPrice, max: maxPrice };
  }

  canTransitionToStatus(newStatus: string): boolean {
    return this.status.canTransitionTo(newStatus as ProductStatus);
  }

  static create(
    sellerId: SellerId,
    name: string,
    description: string,
    type: ProductType,
    variants: ProductVariantLike[],
      options?: {
        categoryId?: CategoryId;
        brand?: string;
        model?: string;
        visibility?: ProductVisibility;
        images?: string[];
        tags?: string[];
        seoData?: SEOData;
        shippingInfo?: ShippingInfo;
        condition?: ProductCondition;
        identifiers?: ProductIdentifiers;
        fingerprint?: ProductFingerprint;
        enablerEnabled?: boolean;
        enablerCommissionRate?: number;
      }
  ): Product {
    const id = ProductId.create();
    const status = new ProductStatusValue(ProductStatus.DRAFT);

    return new Product(
      id,
      sellerId,
      name,
      description,
      status,
      type,
      options?.visibility,
      options?.categoryId,
      options?.brand,
      options?.model,
      variants,
      options?.images,
      options?.tags,
      options?.seoData,
      options?.shippingInfo,
      options?.condition,
      options?.identifiers,
      options?.fingerprint,
      new Date(),
      new Date(),
      options?.enablerEnabled ?? false,
      options?.enablerCommissionRate
    );
  }
}

