export class InventoryPolicies {
  static validateMinimumStockLevel(inventoryLevel: InventoryLevel): boolean {
    if (inventoryLevel.current < 0) {
      throw new Error('Stock level cannot be negative');
    }
    return inventoryLevel.current >= inventoryLevel.minimum;
  }

  static validateMaximumStockLevel(inventoryLevel: InventoryLevel): boolean {
    if (inventoryLevel.maximum && inventoryLevel.current > inventoryLevel.maximum) {
      throw new Error('Stock level exceeds maximum allowed threshold');
    }
    return inventoryLevel.maximum ? inventoryLevel.current <= inventoryLevel.maximum : true;
  }

  static validateZeroStockLevel(inventoryLevel: InventoryLevel): boolean {
    return inventoryLevel.current > 0;
  }

  static calculateReorderPoint(averageDailyDemand: number, leadTimeDays: number, safetyStock: number): number {
    return (averageDailyDemand * leadTimeDays) + safetyStock;
  }

  static checkReorderThreshold(currentInventory: number, reorderPoint: number): boolean {
    return currentInventory <= reorderPoint;
  }

  static validateReorderQuantity(reorderPoint: number, orderQuantity: number): boolean {
    if (orderQuantity > reorderPoint * 20) {
      throw new Error('Reorder quantity exceeds maximum allowed threshold');
    }
    return true;
  }

  static calculateSafetyStock(maxDailyDemand: number, averageDailyDemand: number, maxLeadTimeDays: number, averageLeadTimeDays: number): number {
    return (maxDailyDemand * maxLeadTimeDays) - (averageDailyDemand * averageLeadTimeDays);
  }

  static validateSafetyStockLevel(safetyStock: SafetyStock): boolean {
    if (safetyStock.current < safetyStock.minimum) {
      throw new Error('Safety stock below minimum threshold');
    }
    return safetyStock.current >= safetyStock.minimum;
  }

  static calculateInventoryTurnoverRatio(costOfGoodsSold: number, averageInventory: number): number {
    return costOfGoodsSold / averageInventory;
  }

  static validateInventoryTurnoverRate(turnoverRate: number, targetTurnoverRate: number): boolean {
    if (turnoverRate < targetTurnoverRate) {
      throw new Error('Inventory turnover rate below minimum threshold');
    }
    return true;
  }

  static calculateDaysInventoryOutstanding(turnoverRatio: number): number {
    return 365 / turnoverRatio;
  }

  static validateDaysInventoryOutstanding(daysOutstanding: number, maxDaysOutstanding: number): boolean {
    if (daysOutstanding > maxDaysOutstanding) {
      throw new Error('Days inventory outstanding exceeds maximum threshold');
    }
    return true;
  }

  static predictStockoutRisk(currentInventory: number, dailyDemand: number, leadTimeDays: number): 'low' | 'medium' | 'high' | 'critical' {
    const daysOfStock = currentInventory / dailyDemand;
    
    if (daysOfStock < leadTimeDays * 0.5) return 'high';
    if (daysOfStock < leadTimeDays) return 'medium';
    return 'low';
  }

  static checkEmergencyReorder(currentInventory: number, dailyDemand: number, leadTimeDays: number): boolean {
    const daysOfStock = currentInventory / dailyDemand;
    return daysOfStock < leadTimeDays * 0.5;
  }
}

/**
 * Pricing Policies - Configuration-Driven Business Rules
 * Volatile pricing rules with versioning and DSL support
 * Pure domain logic - no external dependencies
 */

export interface PricingRule {
  id: string;
  name: string;
  version: string;
  priority: number;
  condition: PricingCondition;
  action: PricingAction;
  enabled: boolean;
  metadata: {
    description: string;
    createdAt: Date;
    updatedAt: Date;
    author: string;
  };
}

export interface PricingCondition {
  type: 'product_type' | 'price_range' | 'category' | 'seller_rating' | 'market_data' | 'demand_level';
  operator: 'equals' | 'not_equals' | 'greater_than' | 'less_than' | 'between' | 'in' | 'not_in' | 'contains';
  value: any;
  and?: PricingCondition[];
  or?: PricingCondition[];
}

export interface PricingAction {
  type: 'set_price' | 'adjust_price' | 'set_margin' | 'flag_for_review' | 'reject' | 'apply_discount';
  value: number;
  unit: 'absolute' | 'percentage' | 'multiplier';
  reason: string;
}

export interface PricingContext {
  productId: string;
  sellerId: string;
  category: string;
  productType: string;
  currentPrice: number;
  costPrice?: number;
  marketPrice?: number;
  competitorPrices?: number[];
  sellerRating: number;
  demandLevel: 'low' | 'medium' | 'high';
  seasonalFactor: number;
  region: string;
}

export interface PricingRuleResult {
  appliedRules: string[];
  finalPrice: number;
  adjustments: Array<{
    ruleId: string;
    adjustment: number;
    reason: string;
  }>;
  flags: string[];
  confidence: number;
}

export class PricingRuleEngine {
  constructor(private rules: PricingRule[] = []) {}

  addRule(rule: PricingRule): void {
    // Remove existing rule with same ID
    this.rules = this.rules.filter(r => r.id !== rule.id);
    this.rules.push(rule);

    // Sort by priority (higher priority first)
    this.rules.sort((a, b) => b.priority - a.priority);
  }

  removeRule(ruleId: string): void {
    this.rules = this.rules.filter(r => r.id !== ruleId);
  }

  getRule(ruleId: string): PricingRule | undefined {
    return this.rules.find(r => r.id === ruleId);
  }

  getAllRules(): PricingRule[] {
    return [...this.rules];
  }

  evaluateRules(context: PricingContext): PricingRuleResult {
    const appliedRules: string[] = [];
    const adjustments: Array<{ ruleId: string; adjustment: number; reason: string }> = [];
    const flags: string[] = [];

    let currentPrice = context.currentPrice;
    const basePrice = context.currentPrice;
    let totalConfidence = 0;
    let ruleCount = 0;

    for (const rule of this.rules) {
      if (!rule.enabled) continue;

      if (this.evaluateCondition(rule.condition, context)) {
        appliedRules.push(rule.id);

        const adjustment = this.executeAction(rule.action, currentPrice, basePrice, context);
        if (adjustment !== 0) {
          adjustments.push({
            ruleId: rule.id,
            adjustment,
            reason: rule.action.reason
          });
          currentPrice = this.roundPrice(currentPrice + adjustment);
        }

        if (rule.action.type === 'flag_for_review') {
          flags.push(rule.action.reason);
        }

        totalConfidence += rule.priority;
        ruleCount++;
      }
    }

    const averageConfidence = ruleCount > 0 ? totalConfidence / ruleCount / 10 : 0.5;

    return {
      appliedRules,
      finalPrice: this.roundPrice(Math.max(0, currentPrice)), // Ensure non-negative price
      adjustments,
      flags,
      confidence: Math.min(averageConfidence, 1.0)
    };
  }

  private evaluateCondition(condition: PricingCondition, context: PricingContext): boolean {
    const fieldValue = this.getFieldValue(condition.type, context);
    let baseMatch = false;

    switch (condition.operator) {
      case 'equals':
        baseMatch = fieldValue === condition.value;
        break;
      case 'not_equals':
        baseMatch = fieldValue !== condition.value;
        break;
      case 'greater_than':
        baseMatch = fieldValue > condition.value;
        break;
      case 'less_than':
        baseMatch = fieldValue < condition.value;
        break;
      case 'between':
        baseMatch = fieldValue >= condition.value[0] && fieldValue <= condition.value[1];
        break;
      case 'in':
        baseMatch = Array.isArray(condition.value) && condition.value.includes(fieldValue);
        break;
      case 'not_in':
        baseMatch = Array.isArray(condition.value) && !condition.value.includes(fieldValue);
        break;
      case 'contains':
        baseMatch = String(fieldValue).toLowerCase().includes(String(condition.value).toLowerCase());
        break;
      default:
        baseMatch = false;
        break;
    }

    const andMatch = condition.and ? condition.and.every(andCondition => this.evaluateCondition(andCondition, context)) : true;
    const orMatch = condition.or ? condition.or.some(orCondition => this.evaluateCondition(orCondition, context)) : false;

    if (condition.and && condition.or) {
      return (baseMatch && andMatch) || orMatch;
    }

    if (condition.and) {
      return baseMatch && andMatch;
    }

    if (condition.or) {
      return baseMatch || orMatch;
    }

    return baseMatch;
  }

  private getFieldValue(field: string, context: PricingContext): any {
    switch (field) {
      case 'product_type':
        return context.productType;
      case 'price_range':
        return context.currentPrice;
      case 'category':
        return context.category;
      case 'seller_rating':
        return context.sellerRating;
      case 'market_data':
        return context.marketPrice || 0;
      case 'demand_level':
        return context.demandLevel;
      default:
        return null;
    }
  }

  private executeAction(
    action: PricingAction,
    currentPrice: number,
    referencePrice: number,
    context: PricingContext
  ): number {
    switch (action.type) {
      case 'set_price':
        return action.unit === 'absolute' ? action.value - currentPrice : 0; // Absolute set would be handled differently

      case 'adjust_price':
        if (action.unit === 'percentage') {
          return this.roundPrice(referencePrice * (action.value / 100));
        } else if (action.unit === 'absolute') {
          return action.value;
        } else if (action.unit === 'multiplier') {
          return this.roundPrice(referencePrice * (action.value - 1));
        }
        return 0;

      case 'set_margin':
        if (context.costPrice) {
          const targetPrice = context.costPrice * (1 + action.value / 100);
          return this.roundPrice(targetPrice - currentPrice);
        }
        return 0;

      default:
        return 0;
    }
  }

  private roundPrice(value: number): number {
    return Math.round(value * 100) / 100;
  }
}

