import { CommissionType, CommissionStatus } from '../value-objects/commission-types.value-object';
import { CommissionId, OrderId, SellerId } from '../value-objects/ids.value-object';
import { CommissionAmount, CommissionRate } from '../value-objects/monetary.value-object';

export class Commission {
  constructor(
    public readonly id: CommissionId,
    public readonly orderId: OrderId,
    public readonly sellerId: SellerId,
    public readonly amount: CommissionAmount,
    public readonly rate: CommissionRate,
    public readonly type: CommissionType,
    public status: CommissionStatus,
    public readonly createdAt: Date,
    public paidAt?: Date,
    public payoutId?: string,
    public metadata?: Record<string, any>
  ) {}

  /**
   * Mark commission as paid
   */
  markAsPaid(payoutId: string): void {
    if (this.status !== CommissionStatus.APPROVED) {
      throw new Error('Only approved commissions can be marked as paid');
    }
    this.status = CommissionStatus.PAID;
    this.paidAt = new Date();
    this.payoutId = payoutId;
  }

  /**
   * Approve commission for payment
   */
  approve(): void {
    if (this.status !== CommissionStatus.PENDING) {
      throw new Error('Only pending commissions can be approved');
    }
    this.status = CommissionStatus.APPROVED;
  }

  /**
   * Reject commission
   */
  reject(): void {
    if (this.status !== CommissionStatus.PENDING) {
      throw new Error('Only pending commissions can be rejected');
    }
    this.status = CommissionStatus.REJECTED;
  }

  /**
   * Check if commission is payable
   */
  isPayable(): boolean {
    return this.status === CommissionStatus.APPROVED;
  }

  /**
   * Check if commission is pending
   */
  isPending(): boolean {
    return this.status === CommissionStatus.PENDING;
  }

  /**
   * Get commission age in days
   */
  getAgeInDays(): number {
    return Math.floor((Date.now() - this.createdAt.getTime()) / (1000 * 60 * 60 * 24));
  }
}

import { PayoutId, RecipientId } from '../value-objects/ids.value-object';
import { PayoutAmount } from '../value-objects/monetary.value-object';
import { RecipientType } from '../value-objects/recipient-types.value-object';
import { PayoutStatus } from '../value-objects/payout-types.value-object';

export class Payout {
  constructor(
    public readonly id: PayoutId,
    public readonly recipientId: RecipientId,
    public readonly recipientType: RecipientType,
    public readonly amount: PayoutAmount,
    public status: PayoutStatus,
    public readonly createdAt: Date,
    public scheduledDate?: Date,
    public processedDate?: Date,
    public reference?: string,
    public metadata?: Record<string, any>
  ) {}

  /**
   * Schedule payout for processing
   */
  schedule(scheduledDate: Date): void {
    if (this.status !== PayoutStatus.PENDING) {
      throw new Error('Only pending payouts can be scheduled');
    }
    this.status = PayoutStatus.SCHEDULED;
    this.scheduledDate = scheduledDate;
  }

  /**
   * Mark payout as processed
   */
  process(): void {
    if (this.status !== PayoutStatus.SCHEDULED) {
      throw new Error('Only scheduled payouts can be processed');
    }
    this.status = PayoutStatus.PROCESSED;
    this.processedDate = new Date();
  }

  /**
   * Cancel payout
   */
  cancel(): void {
    if (this.status === PayoutStatus.PROCESSED) {
      throw new Error('Processed payouts cannot be cancelled');
    }
    this.status = PayoutStatus.CANCELLED;
  }

  /**
   * Check if payout is scheduled
   */
  isScheduled(): boolean {
    return this.status === PayoutStatus.SCHEDULED;
  }

  /**
   * Check if payout is pending
   */
  isPending(): boolean {
    return this.status === PayoutStatus.PENDING;
  }

  /**
   * Check if payout is processed
   */
  isProcessed(): boolean {
    return this.status === PayoutStatus.PROCESSED;
  }

  /**
   * Get payout age in days
   */
  getAgeInDays(): number {
    return Math.floor((Date.now() - this.createdAt.getTime()) / (1000 * 60 * 60 * 24));
  }

  /**
   * Check if payout is overdue
   */
  isOverdue(): boolean {
    if (!this.scheduledDate) return false;
    return this.scheduledDate < new Date() && this.status === PayoutStatus.SCHEDULED;
  }
}

/**
 * Commission Policies
 * Business rules and constraints for commission operations
 */

import { Commission } from '../entities/commission.entity';
import { Payout } from '../entities/payout.entity';
import { CommissionAmount, CommissionRate } from '../value-objects/monetary.value-object';
import { CommissionType, CommissionStatus } from '../value-objects/commission-types.value-object';
import { RecipientType } from '../value-objects/recipient-types.value-object';

export class CommissionPolicies {
  /**
   * Business rules for commission creation
   */
  static canCreateCommission(
    amount: CommissionAmount,
    type: CommissionType,
    recipientType: RecipientType
  ): { allowed: boolean; reason?: string } {
    // Minimum commission amounts
    const minAmounts: Record<RecipientType, Record<CommissionType, number>> = {
      [RecipientType.SELLER]: {
        [CommissionType.SALE]: 1.00,
        [CommissionType.REFERRAL]: 0.50,
        [CommissionType.BONUS]: 0.10,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      },
      [RecipientType.COURIER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 0.00,
        [CommissionType.BONUS]: 0.00,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      },
      [RecipientType.ENABLER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 0.00,
        [CommissionType.BONUS]: 0.00,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 5.00,
        [CommissionType.TASK_COMPLETION]: 10.00,
        [CommissionType.COLLABORATION_SETUP]: 2.00
      },
      [RecipientType.CUSTOMER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 0.25,
        [CommissionType.BONUS]: 0.05,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      }
    };

    const minAmount = minAmounts[recipientType]?.[type] ?? 0;
    if (amount.toNumber() < minAmount) {
      return {
        allowed: false,
        reason: `Commission amount must be at least $${minAmount} for ${recipientType} ${type}`
      };
    }

    // Maximum commission amounts (anti-fraud)
    const maxAmounts: Record<RecipientType, Record<CommissionType, number>> = {
      [RecipientType.SELLER]: {
        [CommissionType.SALE]: 10000.00,
        [CommissionType.REFERRAL]: 500.00,
        [CommissionType.BONUS]: 1000.00,
        [CommissionType.ADJUSTMENT]: 5000.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      },
      [RecipientType.COURIER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 0.00,
        [CommissionType.BONUS]: 0.00,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      },
      [RecipientType.ENABLER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 0.00,
        [CommissionType.BONUS]: 0.00,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 500.00,
        [CommissionType.TASK_COMPLETION]: 1000.00,
        [CommissionType.COLLABORATION_SETUP]: 100.00
      },
      [RecipientType.CUSTOMER]: {
        [CommissionType.SALE]: 0.00,
        [CommissionType.REFERRAL]: 100.00,
        [CommissionType.BONUS]: 50.00,
        [CommissionType.ADJUSTMENT]: 0.00,
        [CommissionType.TASK_ASSIGNMENT]: 0.00,
        [CommissionType.TASK_COMPLETION]: 0.00,
        [CommissionType.COLLABORATION_SETUP]: 0.00
      }
    };

    const maxAmount = maxAmounts[recipientType]?.[type] ?? 10000.00;
    if (amount.toNumber() > maxAmount) {
      return {
        allowed: false,
        reason: `Commission amount cannot exceed $${maxAmount} for ${recipientType} ${type}`
      };
    }

    return { allowed: true };
  }

  /**
   * Business rules for commission approval
   */
  static canApproveCommission(
    commission: Commission,
    approverRole: string,
    approverId: string
  ): { allowed: boolean; reason?: string } {
    // Only pending commissions can be approved
    if (!commission.isPending()) {
      return { allowed: false, reason: 'Only pending commissions can be approved' };
    }

    // Authorization rules
    const allowedRoles = ['admin', 'finance', 'manager'];
    if (!allowedRoles.includes(approverRole)) {
      return { allowed: false, reason: 'Insufficient permissions to approve commissions' };
    }

    // Large commission approval rules
    if (commission.amount.toNumber() > 1000) {
      if (!['admin', 'finance'].includes(approverRole)) {
        return { allowed: false, reason: 'Large commissions require admin or finance approval' };
      }
    }

    // Cannot approve own commissions (conflict of interest)
    if (commission.sellerId.toString() === approverId) {
      return { allowed: false, reason: 'Cannot approve your own commissions' };
    }

    return { allowed: true };
  }

  /**
   * Business rules for commission rejection
   */
  static canRejectCommission(
    commission: Commission,
    rejectorRole: string,
    rejectorId: string
  ): { allowed: boolean; reason?: string } {
    // Only pending commissions can be rejected
    if (!commission.isPending()) {
      return { allowed: false, reason: 'Only pending commissions can be rejected' };
    }

    // Authorization rules
    const allowedRoles = ['admin', 'finance', 'manager'];
    if (!allowedRoles.includes(rejectorRole)) {
      return { allowed: false, reason: 'Insufficient permissions to reject commissions' };
    }

    return { allowed: true };
  }

  /**
   * Business rules for commission payment
   */
  static canPayCommission(
    commission: Commission,
    paymentMethod: string
  ): { allowed: boolean; reason?: string } {
    // Only approved commissions can be paid
    if (!commission.isPayable()) {
      return { allowed: false, reason: 'Commission must be approved before payment' };
    }

    // Age restrictions (must be at least 24 hours old for fraud prevention)
    if (commission.getAgeInDays() < 1) {
      return { allowed: false, reason: 'Commissions must be at least 24 hours old before payment' };
    }

    // Amount restrictions for certain payment methods
    if (paymentMethod === 'pesapal' && commission.amount.toNumber() > 5000) {
      return { allowed: false, reason: 'Pesapal payments limited to $5000' };
    }

    return { allowed: true };
  }

  /**
   * Business rules for bulk commission operations
   */
  static canPerformBulkOperation(
    operation: 'approve' | 'reject' | 'pay',
    commissionCount: number,
    operatorRole: string
  ): { allowed: boolean; reason?: string } {
    // Authorization
    const allowedRoles = ['admin', 'finance'];
    if (!allowedRoles.includes(operatorRole)) {
      return { allowed: false, reason: 'Bulk operations require admin or finance role' };
    }

    // Size limits
    const maxSizes: Record<string, number> = {
      'approve': 100,
      'reject': 50,
      'pay': 25
    };

    if (commissionCount > maxSizes[operation]) {
      return {
        allowed: false,
        reason: `Bulk ${operation} limited to ${maxSizes[operation]} commissions at once`
      };
    }

    return { allowed: true };
  }

  /**
   * Business rules for commission adjustments
   */
  static canAdjustCommission(
    commission: Commission,
    adjustmentAmount: CommissionAmount,
    reason: string,
    adjustorRole: string
  ): { allowed: boolean; reason?: string } {
    // Only certain statuses allow adjustments
    if (![CommissionStatus.PENDING, CommissionStatus.APPROVED].includes(commission.status)) {
      return { allowed: false, reason: 'Commission status does not allow adjustments' };
    }

    // Authorization
    if (!['admin', 'finance'].includes(adjustorRole)) {
      return { allowed: false, reason: 'Only admin or finance can adjust commissions' };
    }

    // Adjustment limits
    const maxAdjustment = commission.amount.multiply(0.5); // Max 50% adjustment
    if (adjustmentAmount.toNumber() > maxAdjustment.toNumber()) {
      return { allowed: false, reason: 'Adjustment amount exceeds 50% of commission' };
    }

    // Must provide reason
    if (!reason || reason.trim().length < 10) {
      return { allowed: false, reason: 'Adjustment requires a detailed reason (min 10 characters)' };
    }

    return { allowed: true };
  }

  /**
   * Business rules for commission reporting
   */
  static canViewCommissionReport(
    reportType: 'individual' | 'summary' | 'detailed',
    viewerRole: string,
    targetRecipientId?: string,
    viewerId?: string
  ): { allowed: boolean; reason?: string } {
    // Individual reports - users can view their own
    if (reportType === 'individual') {
      if (targetRecipientId === viewerId) {
        return { allowed: true };
      }
      if (['admin', 'finance', 'manager'].includes(viewerRole)) {
        return { allowed: true };
      }
      return { allowed: false, reason: 'Can only view your own commission reports' };
    }

    // Summary and detailed reports require elevated permissions
    if (!['admin', 'finance', 'manager'].includes(viewerRole)) {
      return { allowed: false, reason: 'Insufficient permissions for commission reports' };
    }

    return { allowed: true };
  }
}

import { User } from '../entities/user.entity';
import { Post, PostType, PostVisibility } from '../entities/post.entity';

/**
 * Feed item with ranking score
 */
export interface FeedItem {
  post: Post;
  score: number;
  reasons: string[];
}

/**
 * Feed generation and content ranking engine
 * Implements algorithmic logic for personalized content feeds
 */
export class FeedEngine {
  // Scoring weights for different factors
  private static readonly SCORING_WEIGHTS = {
    recency: 0.3,
    engagement: 0.25,
    authorTrust: 0.2,
    relevance: 0.15,
    contentQuality: 0.1
  };

  // Time decay factors (hours)
  private static readonly TIME_DECAY_HOURS = {
    [PostType.TEXT]: 24,
    [PostType.IMAGE]: 48,
    [PostType.VIDEO]: 72,
    [PostType.LINK]: 24,
    [PostType.POLL]: 48,
    [PostType.EVENT]: 168, // 1 week
    [PostType.PRODUCT_ANNOUNCEMENT]: 72,
    [PostType.PROMOTION]: 48,
    [PostType.QUESTION]: 12,
    [PostType.DELIVERY_UPDATE]: 6,
    [PostType.DISPUTE_CLARIFICATION]: 24,
    [PostType.SYSTEM_NOTICE]: 168 // 1 week
  };

  /**
   * Generates a personalized feed for a user
   */
  static generateFeed(
    user: User,
    availablePosts: Post[],
    options: {
      limit?: number;
      includeFollowed?: boolean;
      preferredTypes?: PostType[];
      excludeTypes?: PostType[];
    } = {}
  ): FeedItem[] {
    const { limit = 50, includeFollowed = true, preferredTypes, excludeTypes } = options;

    // Filter posts based on visibility and user permissions
    let filteredPosts = availablePosts.filter(post =>
      this.isPostVisibleToUser(post, user)
    );

    // Apply type filters
    if (preferredTypes && preferredTypes.length > 0) {
      filteredPosts = filteredPosts.filter(post =>
        preferredTypes.includes(post.type)
      );
    }

    if (excludeTypes && excludeTypes.length > 0) {
      filteredPosts = filteredPosts.filter(post =>
        !excludeTypes.includes(post.type)
      );
    }

    // Score and rank posts
    const scoredItems = filteredPosts.map(post => ({
      post,
      score: this.calculatePostScore(post, user),
      reasons: this.getScoringReasons(post, user)
    }));

    // Sort by score (descending)
    scoredItems.sort((a, b) => b.score - a.score);

    // Return top items
    return scoredItems.slice(0, limit);
  }

  /**
   * Calculates comprehensive score for a post
   */
  static calculatePostScore(post: Post, user: User): number {
    const recencyScore = this.calculateRecencyScore(post);
    const engagementScore = this.calculateEngagementScore(post);
    const authorTrustScore = this.calculateAuthorTrustScore(post);
    const relevanceScore = this.calculateRelevanceScore(post, user);
    const contentQualityScore = this.calculateContentQualityScore(post);

    const weights = this.SCORING_WEIGHTS;

    return (
      recencyScore * weights.recency +
      engagementScore * weights.engagement +
      authorTrustScore * weights.authorTrust +
      relevanceScore * weights.relevance +
      contentQualityScore * weights.contentQuality
    );
  }

  /**
   * Calculates recency score based on post age and type
   */
  private static calculateRecencyScore(post: Post): number {
    const publishedAt = post.publishedAt || post.createdAt;
    const hoursSincePublished = (Date.now() - publishedAt.getTime()) / (1000 * 60 * 60);
    const decayHours = this.TIME_DECAY_HOURS[post.type];

    if (hoursSincePublished <= 0) {
      return 1.0; // Just published
    }

    if (hoursSincePublished >= decayHours) {
      return 0.1; // Fully decayed
    }

    // Exponential decay
    const decayFactor = Math.exp(-hoursSincePublished / (decayHours / 3));
    return Math.max(0.1, decayFactor);
  }

  /**
   * Calculates engagement score based on likes, comments, shares
   */
  private static calculateEngagementScore(post: Post): number {
    // This would typically come from actual engagement data
    // For now, using placeholder calculations
    const likesWeight = 0.4;
    const commentsWeight = 0.4;
    const sharesWeight = 0.2;

    // Normalize engagement metrics (assuming max values for scaling)
    const normalizedLikes = Math.min(post.likesCount / 100, 1);
    const normalizedComments = Math.min(post.commentsCount / 50, 1);
    const normalizedShares = Math.min(post.sharesCount / 20, 1);

    return (
      normalizedLikes * likesWeight +
      normalizedComments * commentsWeight +
      normalizedShares * sharesWeight
    );
  }

  /**
   * Calculates author trust score based on reputation and verification
   */
  private static calculateAuthorTrustScore(post: Post): number {
    // This would need author data - placeholder for now
    // In real implementation, this would access author trust metadata
    const baseScore = post.isFeatured ? 0.9 : 0.5;
    const verificationBonus = 0.2; // If author is verified
    const reputationBonus = 0.3; // Based on author reputation

    return Math.min(1.0, baseScore + verificationBonus + reputationBonus);
  }

  /**
   * Calculates relevance score based on user preferences and behavior
   */
  private static calculateRelevanceScore(post: Post, user: User): number {
    let relevanceScore = 0.5; // Base relevance

    // Boost score for posts from user's region (if location data available)
    if (post.metadata?.location && user.location) {
      // Simple distance-based relevance (placeholder)
      relevanceScore += 0.1;
    }

    // Boost score for posts with user's preferred tags
    if (post.getTags().length > 0) {
      // In real implementation, check against user's interests
      relevanceScore += 0.1;
    }

    // Boost score for commercial content if user is buyer/seller
    if (post.isCommercialPost()) {
      if (user.role === 'buyer' || user.role === 'seller') {
        relevanceScore += 0.2;
      }
    }

    // Boost score for delivery updates if user is courier
    if (post.type === PostType.DELIVERY_UPDATE && user.role === 'courier') {
      relevanceScore += 0.3;
    }

    return Math.min(1.0, relevanceScore);
  }

  /**
   * Calculates content quality score based on various factors
   */
  private static calculateContentQualityScore(post: Post): number {
    let qualityScore = 0.5; // Base quality

    // Content length appropriateness
    const contentLength = post.content.length;
    if (this.isAppropriateLength(post.type, contentLength)) {
      qualityScore += 0.1;
    }

    // Has media attachments for visual posts
    if ([PostType.IMAGE, PostType.VIDEO].includes(post.type)) {
      // In real implementation, check if media is attached
      qualityScore += 0.1;
    }

    // Has structured metadata for special post types
    if (post.type === PostType.EVENT && post.metadata?.eventDetails) {
      qualityScore += 0.1;
    }

    if (post.type === PostType.POLL && post.metadata?.pollOptions) {
      qualityScore += 0.1;
    }

    // Pinned or featured posts get quality boost
    if (post.isPinned || post.isFeatured) {
      qualityScore += 0.2;
    }

    return Math.min(1.0, qualityScore);
  }

  /**
   * Determines if a post is visible to a specific user
   */
  private static isPostVisibleToUser(post: Post, user: User): boolean {
    return post.isVisibleTo(user.id, post.authorId, false); // Placeholder for follower check
  }

  /**
   * Gets human-readable reasons for the post's score
   */
  private static getScoringReasons(post: Post, user: User): string[] {
    const reasons: string[] = [];

    const publishedAt = post.publishedAt || post.createdAt;
    const hoursSincePublished = (Date.now() - publishedAt.getTime()) / (1000 * 60 * 60);

    if (hoursSincePublished < 1) {
      reasons.push('Very recent post');
    } else if (hoursSincePublished < 24) {
      reasons.push('Posted today');
    }

    if (post.likesCount > 10) {
      reasons.push('Highly liked');
    }

    if (post.commentsCount > 5) {
      reasons.push('Active discussion');
    }

    if (post.isFeatured) {
      reasons.push('Featured content');
    }

    if (post.isPinned) {
      reasons.push('Pinned post');
    }

    if (post.isCommercialPost()) {
      reasons.push('Commercial content');
    }

    if (post.type === PostType.QUESTION) {
      reasons.push('Helpful question');
    }

    return reasons;
  }

  /**
   * Checks if content length is appropriate for the post type
   */
  private static isAppropriateLength(postType: PostType, length: number): boolean {
    const lengthRanges = {
      [PostType.TEXT]: { min: 10, max: 5000 },
      [PostType.IMAGE]: { min: 0, max: 1000 },
      [PostType.VIDEO]: { min: 0, max: 500 },
      [PostType.LINK]: { min: 10, max: 1000 },
      [PostType.POLL]: { min: 10, max: 1000 },
      [PostType.EVENT]: { min: 50, max: 2000 },
      [PostType.PRODUCT_ANNOUNCEMENT]: { min: 50, max: 3000 },
      [PostType.PROMOTION]: { min: 50, max: 2000 },
      [PostType.QUESTION]: { min: 10, max: 1000 },
      [PostType.DELIVERY_UPDATE]: { min: 10, max: 500 },
      [PostType.DISPUTE_CLARIFICATION]: { min: 50, max: 2000 },
      [PostType.SYSTEM_NOTICE]: { min: 10, max: 1000 }
    };

    const range = lengthRanges[postType];
    return length >= range.min && length <= range.max;
  }

  /**
   * Generates trending topics based on recent post activity
   */
  static generateTrendingTopics(posts: Post[], timeWindowHours: number = 24): Array<{ tag: string; score: number; postCount: number }> {
    const cutoffTime = new Date(Date.now() - (timeWindowHours * 60 * 60 * 1000));

    const tagStats = new Map<string, { count: number; totalEngagement: number }>();

    posts
      .filter(post => (post.publishedAt || post.createdAt) > cutoffTime)
      .forEach(post => {
        const tags = post.getTags();
        const engagement = post.likesCount + post.commentsCount * 2 + post.sharesCount * 3;

        tags.forEach(tag => {
          const current = tagStats.get(tag) || { count: 0, totalEngagement: 0 };
          tagStats.set(tag, {
            count: current.count + 1,
            totalEngagement: current.totalEngagement + engagement
          });
        });
      });

    return Array.from(tagStats.entries())
      .map(([tag, stats]) => ({
        tag,
        score: stats.count * 0.6 + stats.totalEngagement * 0.4,
        postCount: stats.count
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, 20); // Top 20 trending topics
  }

  /**
   * Finds similar posts based on tags, type, and content
   */
  static findSimilarPosts(targetPost: Post, candidatePosts: Post[], limit: number = 5): Array<{ post: Post; similarity: number }> {
    return candidatePosts
      .filter(post => post.id !== targetPost.id)
      .map(post => ({
        post,
        similarity: this.calculateSimilarity(targetPost, post)
      }))
      .sort((a, b) => b.similarity - a.similarity)
      .slice(0, limit);
  }

  /**
   * Calculates similarity between two posts
   */
  private static calculateSimilarity(post1: Post, post2: Post): number {
    let similarity = 0;

    // Same post type
    if (post1.type === post2.type) {
      similarity += 0.3;
    }

    // Common tags
    const tags1 = new Set(post1.getTags());
    const tags2 = new Set(post2.getTags());
    const commonTags = new Set([...tags1].filter(tag => tags2.has(tag)));
    const tagSimilarity = commonTags.size / Math.max(tags1.size, tags2.size, 1);
    similarity += tagSimilarity * 0.4;

    // Same author (slight boost for consistency)
    if (post1.authorId === post2.authorId) {
      similarity += 0.1;
    }

    // Same visibility
    if (post1.visibility === post2.visibility) {
      similarity += 0.1;
    }

    // Commercial content similarity
    if (post1.isCommercialPost() === post2.isCommercialPost()) {
      similarity += 0.1;
    }

    return Math.min(1.0, similarity);
  }
}

import { ContributionScore } from '../value-objects/contribution-score.value-object';
import { ReputationTier } from '../entities/business-profile.entity';
import { ExpertiseBadge } from '../value-objects/expertise-badge.value-object';

export interface ReputationMetrics {
    contributionScore: number;
    expertiseBadges: number;
    peerEndorsements: number;
    helpfulAnswers: number;
    knowledgeShared: number;
    mentorshipHours: number;
    articlesPublished: number;
    challengesSolved: number;
}

export interface ReputationTrend {
    current: ReputationTier;
    previous: ReputationTier;
    direction: 'IMPROVING' | 'STABLE' | 'DECLINING';
    scoreChange: number;
    daysInCurrentTier: number;
}

export interface UnlockableFeature {
    feature: string;
    description: string;
    requiredTier: ReputationTier;
    requiredScore: number;
    unlocked: boolean;
}

export class ReputationEngine {
    private static readonly TIER_THRESHOLDS: Record<ReputationTier, number> = {
        [ReputationTier.NEWCOMER]: 0,
        [ReputationTier.CONTRIBUTOR]: 500,
        [ReputationTier.EXPERT]: 2000,
        [ReputationTier.MENTOR]: 5000,
        [ReputationTier.THOUGHT_LEADER]: 10000,
    };

    private static readonly FEATURES: UnlockableFeature[] = [
        {
            feature: 'create_knowledge_articles',
            description: 'Publish knowledge articles',
            requiredTier: ReputationTier.CONTRIBUTOR,
            requiredScore: 500,
            unlocked: false,
        },
        {
            feature: 'mentor_others',
            description: 'Become a mentor',
            requiredTier: ReputationTier.EXPERT,
            requiredScore: 2000,
            unlocked: false,
        },
        {
            feature: 'validate_expertise',
            description: 'Validate other users\' expertise',
            requiredTier: ReputationTier.EXPERT,
            requiredScore: 2000,
            unlocked: false,
        },
        {
            feature: 'propose_challenges',
            description: 'Propose business challenges',
            requiredTier: ReputationTier.CONTRIBUTOR,
            requiredScore: 500,
            unlocked: false,
        },
        {
            feature: 'priority_matching',
            description: 'Priority expert matching on questions',
            requiredTier: ReputationTier.MENTOR,
            requiredScore: 5000,
            unlocked: false,
        },
        {
            feature: 'host_sessions',
            description: 'Host learning sessions',
            requiredTier: ReputationTier.MENTOR,
            requiredScore: 5000,
            unlocked: false,
        },
        {
            feature: 'influence_algorithms',
            description: 'Influence content ranking algorithms',
            requiredTier: ReputationTier.THOUGHT_LEADER,
            requiredScore: 10000,
            unlocked: false,
        },
    ];

    static calculateReputation(metrics: ReputationMetrics): {
        tier: ReputationTier;
        score: number;
        nextTier?: ReputationTier;
        progressToNext: number;
    } {
        const tier = this.determineTier(metrics.contributionScore);
        const nextTier = this.getNextTier(tier);

        let progressToNext = 0;
        if (nextTier) {
            const currentThreshold = this.TIER_THRESHOLDS[tier];
            const nextThreshold = this.TIER_THRESHOLDS[nextTier];
            const range = nextThreshold - currentThreshold;
            const progress = metrics.contributionScore - currentThreshold;
            progressToNext = Math.min(100, Math.floor((progress / range) * 100));
        }

        return {
            tier,
            score: metrics.contributionScore,
            nextTier,
            progressToNext,
        };
    }

    static determineTier(contributionScore: number): ReputationTier {
        const tiers: ReputationTier[] = [
            ReputationTier.THOUGHT_LEADER,
            ReputationTier.MENTOR,
            ReputationTier.EXPERT,
            ReputationTier.CONTRIBUTOR,
            ReputationTier.NEWCOMER,
        ];

        for (const tier of tiers) {
            if (contributionScore >= this.TIER_THRESHOLDS[tier]) {
                return tier;
            }
        }

        return ReputationTier.NEWCOMER;
    }

    static analyzeReputationTrend(params: {
        currentScore: number;
        previousScore: number;
        currentTier: ReputationTier;
        tierChangeDate?: Date;
    }): ReputationTrend {
        const scoreDelta = params.currentScore - params.previousScore;
        const previousTier = this.determineTier(params.previousScore);

        let direction: 'IMPROVING' | 'STABLE' | 'DECLINING';
        if (scoreDelta > 100) {
            direction = 'IMPROVING';
        } else if (scoreDelta < -100) {
            direction = 'DECLINING';
        } else {
            direction = 'STABLE';
        }

        const daysInCurrentTier = params.tierChangeDate
            ? Math.floor((new Date().getTime() - params.tierChangeDate.getTime()) / (1000 * 60 * 60 * 24))
            : 0;

        return {
            current: params.currentTier,
            previous: previousTier,
            direction,
            scoreChange: scoreDelta,
            daysInCurrentTier,
        };
    }

    static getUnlockableFeatures(
        currentTier: ReputationTier,
        currentScore: number
    ): UnlockableFeature[] {
        return this.FEATURES.map(feature => ({
            ...feature,
            unlocked: this.isFeatureUnlocked(currentTier, currentScore, feature),
        }));
    }

    private static isFeatureUnlocked(
        currentTier: ReputationTier,
        currentScore: number,
        feature: UnlockableFeature
    ): boolean {
        const tierMet = this.compareTiers(currentTier, feature.requiredTier) >= 0;
        const scoreMet = currentScore >= feature.requiredScore;
        return tierMet && scoreMet;
    }

    private static compareTiers(tier1: ReputationTier, tier2: ReputationTier): number {
        const levels: ReputationTier[] = [
            ReputationTier.NEWCOMER,
            ReputationTier.CONTRIBUTOR,
            ReputationTier.EXPERT,
            ReputationTier.MENTOR,
            ReputationTier.THOUGHT_LEADER,
        ];

        return levels.indexOf(tier1) - levels.indexOf(tier2);
    }

    private static getNextTier(currentTier: ReputationTier): ReputationTier | undefined {
        const tiers: ReputationTier[] = [
            ReputationTier.NEWCOMER,
            ReputationTier.CONTRIBUTOR,
            ReputationTier.EXPERT,
            ReputationTier.MENTOR,
            ReputationTier.THOUGHT_LEADER,
        ];

        const currentIndex = tiers.indexOf(currentTier);
        return currentIndex < tiers.length - 1 ? tiers[currentIndex + 1] : undefined;
    }

    static calculateImpact(metrics: ReputationMetrics): {
        overallImpact: number;
        breakdown: {
            knowledge: number;
            mentorship: number;
            problemSolving: number;
            community: number;
        };
    } {
        // Knowledge impact (0-100)
        const knowledgeImpact = Math.min(100,
            metrics.knowledgeShared * 5 +
            metrics.articlesPublished * 10
        );

        // Mentorship impact (0-100)
        const mentorshipImpact = Math.min(100,
            metrics.mentorshipHours * 3 +
            metrics.helpfulAnswers * 2
        );

        // Problem-solving impact (0-100)
        const problemSolvingImpact = Math.min(100,
            metrics.challengesSolved * 15 +
            metrics.helpfulAnswers * 2
        );

        // Community impact (0-100)
        const communityImpact = Math.min(100,
            metrics.peerEndorsements * 5 +
            metrics.expertiseBadges * 15
        );

        const overallImpact = Math.floor(
            (knowledgeImpact + mentorshipImpact + problemSolvingImpact + communityImpact) / 4
        );

        return {
            overallImpact,
            breakdown: {
                knowledge: knowledgeImpact,
                mentorship: mentorshipImpact,
                problemSolving: problemSolvingImpact,
                community: communityImpact,
            },
        };
    }

    static getReputationBenefits(tier: ReputationTier): string[] {
        const benefits: Record<ReputationTier, string[]> = {
            [ReputationTier.NEWCOMER]: [
                'Participate in discussions',
                'Ask questions',
                'Comment on posts',
            ],
            [ReputationTier.CONTRIBUTOR]: [
                'All NEWCOMER benefits',
                'Create knowledge articles',
                'Propose business challenges',
                'Higher daily quotas',
            ],
            [ReputationTier.EXPERT]: [
                'All CONTRIBUTOR benefits',
                'Become a mentor',
                'Validate expertise of others',
                'Priority support',
                'Featured expert badge',
            ],
            [ReputationTier.MENTOR]: [
                'All EXPERT benefits',
                'Host learning sessions',
                'Priority expert matching',
                'Influence ranking algorithms',
                'Exclusive mentor community',
            ],
            [ReputationTier.THOUGHT_LEADER]: [
                'All MENTOR benefits',
                'Shape platform direction',
                'Unlimited quotas',
                'Represent platform publicly',
                'Early access to new features',
            ],
        };

        return benefits[tier];
    }

    static shouldBePromoted(
        currentTier: ReputationTier,
        metrics: ReputationMetrics
    ): { shouldPromote: boolean; nextTier?: ReputationTier; reason?: string } {
        const nextTier = this.getNextTier(currentTier);

        if (!nextTier) {
            return { shouldPromote: false, reason: 'Already at highest tier' };
        }

        const requiredScore = this.TIER_THRESHOLDS[nextTier];

        if (metrics.contributionScore >= requiredScore) {
            return {
                shouldPromote: true,
                nextTier,
                reason: `Contribution score of ${metrics.contributionScore} meets ${nextTier} threshold`,
            };
        }

        return {
            shouldPromote: false,
            reason: `Need ${requiredScore - metrics.contributionScore} more points for ${nextTier}`,
        };
    }

    static shouldBeDemoted(
        currentTier: ReputationTier,
        metrics: ReputationMetrics,
        inactivityDays: number
    ): { shouldDemote: boolean; reason?: string } {
        // Don't demote newcomers
        if (currentTier === ReputationTier.NEWCOMER) {
            return { shouldDemote: false };
        }

        // Check if score has fallen below current tier minimum
        const currentThreshold = this.TIER_THRESHOLDS[currentTier];
        if (metrics.contributionScore < currentThreshold * 0.7) {
            return {
                shouldDemote: true,
                reason: `Score dropped below 70% of ${currentTier} threshold`,
            };
        }

        // Check for extended inactivity
        const maxInactivityDays: Record<ReputationTier, number> = {
            [ReputationTier.NEWCOMER]: 365,
            [ReputationTier.CONTRIBUTOR]: 180,
            [ReputationTier.EXPERT]: 120,
            [ReputationTier.MENTOR]: 90,
            [ReputationTier.THOUGHT_LEADER]: 60,
        };

        if (inactivityDays > maxInactivityDays[currentTier]) {
            return {
                shouldDemote: true,
                reason: `Inactive for ${inactivityDays} days (max ${maxInactivityDays[currentTier]})`,
            };
        }

        return { shouldDemote: false };
    }
}

import { User } from './user.entity';

/**
 * Post types in the marketplace community
 */
export enum PostType {
  TEXT = 'text',
  IMAGE = 'image',
  VIDEO = 'video',
  LINK = 'link',
  POLL = 'poll',
  EVENT = 'event',
  PRODUCT_ANNOUNCEMENT = 'product_announcement',
  PROMOTION = 'promotion',
  QUESTION = 'question',
  DELIVERY_UPDATE = 'delivery_update',
  DISPUTE_CLARIFICATION = 'dispute_clarification',
  SYSTEM_NOTICE = 'system_notice'
}

/**
 * Post visibility levels
 */
export enum PostVisibility {
  PUBLIC = 'public',
  FOLLOWERS = 'followers',
  PRIVATE = 'private'
}

/**
 * Post status
 */
export enum PostStatus {
  DRAFT = 'draft',
  PUBLISHED = 'published',
  HIDDEN = 'hidden',
  DELETED = 'deleted'
}

/**
 * Post metadata for commerce integration
 */
export interface PostMetadata {
  relatedProductId?: string;
  relatedOrderId?: string;
  relatedShipmentId?: string;
  tags?: string[];
  location?: {
    latitude: number;
    longitude: number;
    address?: string;
  };
  pollOptions?: string[];
  eventDetails?: {
    startDate: Date;
    endDate?: Date;
    location?: string;
    capacity?: number;
  };
}

/**
 * Post entity representing content in the marketplace community
 */
export class Post {
  private constructor(
    private readonly _id: string,
    private readonly _authorId: string,
    private _content: string,
    private readonly _type: PostType,
    private _visibility: PostVisibility,
    private readonly _createdAt: Date,
    private _updatedAt: Date,
    private _status: PostStatus,
    private _isPinned: boolean,
    private _isFeatured: boolean,
    private _publishedAt?: Date,
    private _title?: string,
    private _metadata?: PostMetadata,
    private _moderatedBy?: string,
    private _moderatedAt?: Date,
    private _moderationReason?: string
  ) {}

  // Factory methods
  static create(params: {
    id: string;
    authorId: string;
    content: string;
    type: PostType;
    title?: string;
    visibility?: PostVisibility;
    metadata?: PostMetadata;
  }): Post {
    const now = new Date();
    return new Post(
      params.id,
      params.authorId,
      params.content,
      params.type,
      params.visibility || PostVisibility.PUBLIC,
      now,
      now,
      PostStatus.DRAFT,
      false,
      false,
      undefined,
      params.title,
      params.metadata
    );
  }

  static createPublished(params: {
    id: string;
    authorId: string;
    content: string;
    type: PostType;
    title?: string;
    visibility?: PostVisibility;
    metadata?: PostMetadata;
  }): Post {
    const now = new Date();
    return new Post(
      params.id,
      params.authorId,
      params.content,
      params.type,
      params.visibility || PostVisibility.PUBLIC,
      now,
      now,
      PostStatus.PUBLISHED,
      false,
      false,
      now,
      params.title,
      params.metadata
    );
  }

  // Getters
  get id(): string {
    return this._id;
  }

  get authorId(): string {
    return this._authorId;
  }

  get title(): string | undefined {
    return this._title;
  }

  get content(): string {
    return this._content;
  }

  get type(): PostType {
    return this._type;
  }

  get visibility(): PostVisibility {
    return this._visibility;
  }

  get metadata(): PostMetadata | undefined {
    return this._metadata;
  }

  get createdAt(): Date {
    return this._createdAt;
  }

  get updatedAt(): Date {
    return this._updatedAt;
  }

  get publishedAt(): Date | undefined {
    return this._publishedAt;
  }

  get status(): PostStatus {
    return this._status;
  }

  get isPinned(): boolean {
    return this._isPinned;
  }

  get isFeatured(): boolean {
    return this._isFeatured;
  }

  get moderatedBy(): string | undefined {
    return this._moderatedBy;
  }

  get moderatedAt(): Date | undefined {
    return this._moderatedAt;
  }

  get moderationReason(): string | undefined {
    return this._moderationReason;
  }

  // Engagement metrics (would typically come from separate engagement tracking)
  get likesCount(): number {
    // This would be fetched from engagement data
    return 0;
  }

  get commentsCount(): number {
    // This would be fetched from engagement data
    return 0;
  }

  get sharesCount(): number {
    // This would be fetched from engagement data
    return 0;
  }

  // Business methods
  publish(): void {
    if (this._status !== PostStatus.DRAFT) {
      throw new Error('Only draft posts can be published');
    }
    this._status = PostStatus.PUBLISHED;
    this._publishedAt = new Date();
    this._updatedAt = new Date();
  }

  updateContent(content: string, title?: string): void {
    if (this._status === PostStatus.DELETED) {
      throw new Error('Cannot update deleted posts');
    }
    this._content = content;
    if (title !== undefined) {
      this._title = title;
    }
    this._updatedAt = new Date();
  }

  changeVisibility(visibility: PostVisibility): void {
    this._visibility = visibility;
    this._updatedAt = new Date();
  }

  pin(): void {
    this._isPinned = true;
    this._updatedAt = new Date();
  }

  unpin(): void {
    this._isPinned = false;
    this._updatedAt = new Date();
  }

  feature(): void {
    this._isFeatured = true;
    this._updatedAt = new Date();
  }

  unfeature(): void {
    this._isFeatured = false;
    this._updatedAt = new Date();
  }

  hide(): void {
    this._status = PostStatus.HIDDEN;
    this._updatedAt = new Date();
  }

  unhide(): void {
    if (this._status === PostStatus.HIDDEN) {
      this._status = this._publishedAt ? PostStatus.PUBLISHED : PostStatus.DRAFT;
      this._updatedAt = new Date();
    }
  }

  delete(): void {
    this._status = PostStatus.DELETED;
    this._updatedAt = new Date();
  }

  moderate(moderatorId: string, reason?: string): void {
    this._moderatedBy = moderatorId;
    this._moderatedAt = new Date();
    this._moderationReason = reason;
    this._updatedAt = new Date();
  }

  // Business rules and queries
  isPublished(): boolean {
    return this._status === PostStatus.PUBLISHED && !!this._publishedAt;
  }

  isVisibleTo(userId: string, authorId: string, isFollower: boolean): boolean {
    if (this._status !== PostStatus.PUBLISHED) {
      return false;
    }

    switch (this._visibility) {
      case PostVisibility.PUBLIC:
        return true;
      case PostVisibility.FOLLOWERS:
        return isFollower || userId === authorId;
      case PostVisibility.PRIVATE:
        return userId === authorId;
      default:
        return false;
    }
  }

  isCommercialPost(): boolean {
    return [
      PostType.PRODUCT_ANNOUNCEMENT,
      PostType.PROMOTION
    ].includes(this._type);
  }

  isSystemPost(): boolean {
    return [
      PostType.SYSTEM_NOTICE,
      PostType.DELIVERY_UPDATE,
      PostType.DISPUTE_CLARIFICATION
    ].includes(this._type);
  }

  requiresModeration(): boolean {
    return this.isCommercialPost() || this._type === PostType.EVENT;
  }

  hasExpired(): boolean {
    if (!this._metadata?.eventDetails?.endDate) {
      return false;
    }
    return new Date() > this._metadata.eventDetails.endDate;
  }

  // Commerce integration helpers
  getRelatedProductId(): string | undefined {
    return this._metadata?.relatedProductId;
  }

  getRelatedOrderId(): string | undefined {
    return this._metadata?.relatedOrderId;
  }

  getRelatedShipmentId(): string | undefined {
    return this._metadata?.relatedShipmentId;
  }

  getTags(): string[] {
    return this._metadata?.tags || [];
  }

  getLocation(): { latitude: number; longitude: number; address?: string } | undefined {
    return this._metadata?.location;
  }

  // Event-specific methods
  getEventDetails() {
    if (this._type !== PostType.EVENT) {
      return null;
    }
    return this._metadata?.eventDetails;
  }

  // Poll-specific methods
  getPollOptions(): string[] {
    if (this._type !== PostType.POLL) {
      return [];
    }
    return this._metadata?.pollOptions || [];
  }

  // Serialization
  toJSON() {
    return {
      id: this._id,
      authorId: this._authorId,
      title: this._title,
      content: this._content,
      type: this._type,
      visibility: this._visibility,
      metadata: this._metadata,
      createdAt: this._createdAt.toISOString(),
      updatedAt: this._updatedAt.toISOString(),
      publishedAt: this._publishedAt?.toISOString(),
      status: this._status,
      isPinned: this._isPinned,
      isFeatured: this._isFeatured,
      moderatedBy: this._moderatedBy,
      moderatedAt: this._moderatedAt?.toISOString(),
      moderationReason: this._moderationReason
    };
  }
}

import { User, UserRole } from '../entities/user.entity';
import { Post, PostType, PostStatus } from '../entities/post.entity';

/**
 * Content moderation policy
 * Defines rules for content approval, flagging, and moderation
 */
export class ContentModerationPolicy {
  // Content that requires pre-moderation
  private static readonly REQUIRES_PRE_MODERATION: PostType[] = [
    PostType.PRODUCT_ANNOUNCEMENT,
    PostType.PROMOTION,
    PostType.EVENT,
    PostType.SYSTEM_NOTICE
  ];

  // Content that is auto-approved for verified users
  private static readonly AUTO_APPROVED_FOR_VERIFIED: PostType[] = [
    PostType.TEXT,
    PostType.IMAGE,
    PostType.VIDEO,
    PostType.LINK,
    PostType.QUESTION
  ];

  // Keywords that trigger content review
  private static readonly SUSPICIOUS_KEYWORDS = [
    'scam', 'fraud', 'fake', 'counterfeit', 'stolen',
    'hack', 'crack', 'exploit', 'malware', 'virus',
    'drugs', 'weapons', 'illegal', 'prohibited'
  ];

  // Commercial keywords that require verification
  private static readonly COMMERCIAL_KEYWORDS = [
    'buy', 'sell', 'purchase', 'price', 'discount', 'deal',
    'offer', 'sale', 'discount', 'coupon', 'voucher'
  ];

  /**
   * Determines if content requires pre-moderation
   */
  static requiresPreModeration(postType: PostType, author: User, content: string): boolean {
    // System posts are always pre-moderated
    if (postType === PostType.SYSTEM_NOTICE) {
      return true;
    }

    // Commercial posts require moderation
    if (this.REQUIRES_PRE_MODERATION.includes(postType)) {
      return true;
    }

    // Check for suspicious content
    if (this.containsSuspiciousContent(content)) {
      return true;
    }

    // Commercial keywords in non-commercial posts
    if (!this.isCommercialPostType(postType) && this.containsCommercialContent(content)) {
      return true;
    }

    // Unverified users get stricter moderation
    if (!author.isVerified && postType === PostType.PROMOTION) {
      return true;
    }

    return false;
  }

  /**
   * Determines if content can be auto-approved
   */
  static canBeAutoApproved(postType: PostType, author: User, content: string): boolean {
    // Pre-moderated content cannot be auto-approved
    if (this.requiresPreModeration(postType, author, content)) {
      return false;
    }

    // Only verified users can have auto-approval for certain content
    if (!author.isVerified) {
      return this.AUTO_APPROVED_FOR_VERIFIED.includes(postType) && !this.containsSuspiciousContent(content);
    }

    return true;
  }

  /**
   * Checks if content contains suspicious keywords
   */
  static containsSuspiciousContent(content: string): boolean {
    const lowerContent = content.toLowerCase();
    return this.SUSPICIOUS_KEYWORDS.some(keyword =>
      lowerContent.includes(keyword.toLowerCase())
    );
  }

  /**
   * Checks if content appears commercial
   */
  static containsCommercialContent(content: string): boolean {
    const lowerContent = content.toLowerCase();
    return this.COMMERCIAL_KEYWORDS.some(keyword =>
      lowerContent.includes(keyword.toLowerCase())
    );
  }

  /**
   * Determines moderation priority
   */
  static getModerationPriority(postType: PostType, author: User, content: string): 'low' | 'medium' | 'high' | 'critical' {
    // Critical priority for system notices
    if (postType === PostType.SYSTEM_NOTICE) {
      return 'critical';
    }

    // High priority for commercial content or suspicious content
    if (this.isCommercialPostType(postType) || this.containsSuspiciousContent(content)) {
      return 'high';
    }

    // Medium priority for events
    if (postType === PostType.EVENT) {
      return 'medium';
    }

    // Low priority for regular content
    return 'low';
  }

  /**
   * Determines if a user can moderate content
   */
  static canUserModerate(user: User, post: Post): boolean {
    // Only enablers and system users can moderate
    if (user.role !== UserRole.ENABLER && user.role !== UserRole.SYSTEM) {
      return false;
    }

    // Cannot moderate own content
    if (user.id === post.authorId) {
      return false;
    }

    // System users can moderate everything
    if (user.role === UserRole.SYSTEM) {
      return true;
    }

    // Enablers cannot moderate system posts
    if (post.type === PostType.SYSTEM_NOTICE) {
      return false;
    }

    return true;
  }

  /**
   * Gets recommended moderation action
   */
  static getRecommendedAction(postType: PostType, author: User, content: string): 'approve' | 'reject' | 'flag' | 'escalate' {
    // Auto-approve safe content from verified users
    if (this.canBeAutoApproved(postType, author, content)) {
      return 'approve';
    }

    // Escalate suspicious content
    if (this.containsSuspiciousContent(content)) {
      return 'escalate';
    }

    // Flag commercial content from unverified users
    if (this.isCommercialPostType(postType) && !author.isVerified) {
      return 'flag';
    }

    // Reject system notices from non-system users
    if (postType === PostType.SYSTEM_NOTICE && author.role !== UserRole.SYSTEM) {
      return 'reject';
    }

    // Default to flag for manual review
    return 'flag';
  }

  /**
   * Validates content length and format
   */
  static validateContent(content: string, postType: PostType): { isValid: boolean; reason?: string } {
    // Check minimum length
    if (content.trim().length < 10) {
      return { isValid: false, reason: 'Content too short (minimum 10 characters)' };
    }

    // Check maximum length based on post type
    const maxLengths = {
      [PostType.TEXT]: 5000,
      [PostType.IMAGE]: 1000,
      [PostType.VIDEO]: 500,
      [PostType.LINK]: 1000,
      [PostType.POLL]: 1000,
      [PostType.EVENT]: 2000,
      [PostType.PRODUCT_ANNOUNCEMENT]: 3000,
      [PostType.PROMOTION]: 2000,
      [PostType.QUESTION]: 1000,
      [PostType.DELIVERY_UPDATE]: 500,
      [PostType.DISPUTE_CLARIFICATION]: 2000,
      [PostType.SYSTEM_NOTICE]: 1000
    };

    const maxLength = maxLengths[postType] || 1000;
    if (content.length > maxLength) {
      return { isValid: false, reason: `Content too long (maximum ${maxLength} characters)` };
    }

    // Check for excessive caps
    const capsRatio = (content.match(/[A-Z]/g) || []).length / content.length;
    if (capsRatio > 0.3 && content.length > 50) {
      return { isValid: false, reason: 'Too many capital letters' };
    }

    return { isValid: true };
  }

  private static isCommercialPostType(postType: PostType): boolean {
    return [
      PostType.PRODUCT_ANNOUNCEMENT,
      PostType.PROMOTION
    ].includes(postType);
  }

  /**
   * Performs comprehensive content assessment for business-focused community
   */
  static performFullAssessment(params: {
    contentType: string;
    content: any;
    userTier: string;
    userExpertise: Array<{ area: string; level: any }>;
  }): {
    meetsQualityThreshold: boolean;
    qualityScore: number;
    issues: string[];
  } {
    const issues: string[] = [];
    let baseScore = 70;

    // Business value assessment
    const businessValue = this.assessBusinessValue(params.content);
    if (businessValue < 50) {
      issues.push('Content lacks sufficient business value');
      baseScore -= 20;
    }

    // Context validation
    if (params.content.businessContext) {
      const contextValidation = this.validateBusinessContext(params.content.businessContext);
      if (!contextValidation.valid) {
        issues.push(...contextValidation.errors);
        baseScore -= 15;
      }
    }

    // Structure validation
    const structureValidation = this.validateStructuredFormat(params.contentType, params.content);
    if (!structureValidation.valid) {
      issues.push(...structureValidation.errors);
      baseScore -= 15;
    }

    // Minimum threshold based on user tier
    const threshold = params.userTier === 'NEWCOMER' ? 60 : 50;

    return {
      meetsQualityThreshold: baseScore >= threshold && issues.length < 3,
      qualityScore: Math.max(0, baseScore),
      issues,
    };
  }

  /**
   * Assesses business value of content
   */
  private static assessBusinessValue(content: any): number {
    let score = 50; // Base score

    const contentString = JSON.stringify(content).toLowerCase();
    const businessTerms = ['revenue', 'customer', 'market', 'strategy', 'supply chain', 'logistics', 'business', 'operations'];
    const matchCount = businessTerms.filter(term => contentString.includes(term)).length;

    score += matchCount * 10;

    return Math.min(100, score);
  }

  /**
   * Validates business context
   */
  static validateBusinessContext(context: any): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!context.industry || (Array.isArray(context.industry) && context.industry.length === 0)) {
      errors.push('Industry context is required');
    }

    if (!context.tags || (Array.isArray(context.tags) && context.tags.length === 0)) {
      errors.push('Tags are required for discoverability');
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Validates structured format
   */
  static validateStructuredFormat(contentType: string, content: any): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (contentType === 'THREAD' || contentType === 'CHALLENGE') {
      if (!content.topic && !content.title) {
        errors.push('Title or topic is required');
      }
      if (!content.content && !content.description) {
        errors.push('Content or description is required');
      }
      if (!content.category) {
        errors.push('Category is required for organization');
      }
    }

    if (contentType === 'ARTICLE') {
      if (!content.content || content.content.length < 200) {
        errors.push('Article content must be at least 200 characters');
      }
      if (!content.category) {
        errors.push('Category is required');
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }
}

import { ReputationTier } from '../entities/business-profile.entity';
import { EngagementQuota, QuotaType } from '../value-objects/engagement-quota.value-object';

export interface EngagementLimits {
    posts: number;
    comments: number;
    threads: number;
    articles: number;
    challenges: number;
}

export interface CoolingPeriodConfig {
    similarPostsMinutes: number;
    sameTopicMinutes: number;
}

export class EngagementPolicy {
    private static readonly DEFAULT_LIMITS: Record<ReputationTier, EngagementLimits> = {
        [ReputationTier.NEWCOMER]: {
            posts: 3,
            comments: 10,
            threads: 2,
            articles: 0,
            challenges: 1,
        },
        [ReputationTier.CONTRIBUTOR]: {
            posts: 5,
            comments: 20,
            threads: 3,
            articles: 1,
            challenges: 2,
        },
        [ReputationTier.EXPERT]: {
            posts: 8,
            comments: 30,
            threads: 5,
            articles: 2,
            challenges: 3,
        },
        [ReputationTier.MENTOR]: {
            posts: 10,
            comments: 40,
            threads: 7,
            articles: 3,
            challenges: 5,
        },
        [ReputationTier.THOUGHT_LEADER]: {
            posts: 15,
            comments: 50,
            threads: 10,
            articles: 5,
            challenges: 7,
        },
    };

    private static readonly COOLING_PERIODS: CoolingPeriodConfig = {
        similarPostsMinutes: 60,
        sameTopicMinutes: 30,
    };

    private static readonly MIN_CONTENT_QUALITY_SCORE = 40;
    private static readonly MIN_NEWCOMER_QUALITY_SCORE = 60;

    static getDailyLimitForTier(tier: ReputationTier, quotaType: QuotaType): number {
        const limits = this.DEFAULT_LIMITS[tier];

        switch (quotaType) {
            case 'POST':
                return limits.posts;
            case 'COMMENT':
                return limits.comments;
            case 'THREAD':
                return limits.threads;
            case 'ARTICLE':
                return limits.articles;
            case 'CHALLENGE':
                return limits.challenges;
            default:
                return 0;
        }
    }

    static canCreateContent(
        quota: EngagementQuota,
        tier: ReputationTier
    ): { allowed: boolean; reason?: string } {
        if (!quota.canPerformAction()) {
            return {
                allowed: false,
                reason: `Daily quota exceeded. Resets in ${this.formatTimeUntilReset(quota.getTimeUntilReset().daily)}`,
            };
        }

        return { allowed: true };
    }

    static requiresTopicSelection(quotaType: QuotaType): boolean {
        return ['THREAD', 'ARTICLE', 'CHALLENGE'].includes(quotaType);
    }

    static requiresCategorization(quotaType: QuotaType): boolean {
        return ['THREAD', 'ARTICLE', 'CHALLENGE', 'POST'].includes(quotaType);
    }

    static meetsMinimumQualityScore(score: number, tier: ReputationTier): boolean {
        if (tier === ReputationTier.NEWCOMER) {
            return score >= this.MIN_NEWCOMER_QUALITY_SCORE;
        }

        return score >= this.MIN_CONTENT_QUALITY_SCORE;
    }

    static getCoolingPeriodMinutes(tier: ReputationTier, quotaType: QuotaType): number {
        // Higher tiers have shorter cooling periods
        const basePeriod = quotaType === 'POST' ? 30 : 15;

        const tierMultiplier = tier === ReputationTier.THOUGHT_LEADER ? 0.2 :
            tier === ReputationTier.MENTOR ? 0.4 :
                tier === ReputationTier.EXPERT ? 0.6 :
                    tier === ReputationTier.CONTRIBUTOR ? 0.8 : 1.0;

        return Math.ceil(basePeriod * tierMultiplier);
    }

    static isWithinCoolingPeriod(
        lastPostTime: Date,
        isSimilarContent: boolean,
        isSameTopic: boolean
    ): { withinCoolingPeriod: boolean; remainingMinutes?: number } {
        const now = new Date();
        const minutesSinceLastPost = Math.floor(
            (now.getTime() - lastPostTime.getTime()) / (1000 * 60)
        );

        if (isSimilarContent && minutesSinceLastPost < this.COOLING_PERIODS.similarPostsMinutes) {
            return {
                withinCoolingPeriod: true,
                remainingMinutes: this.COOLING_PERIODS.similarPostsMinutes - minutesSinceLastPost,
            };
        }

        if (isSameTopic && minutesSinceLastPost < this.COOLING_PERIODS.sameTopicMinutes) {
            return {
                withinCoolingPeriod: true,
                remainingMinutes: this.COOLING_PERIODS.sameTopicMinutes - minutesSinceLastPost,
            };
        }

        return { withinCoolingPeriod: false };
    }

    static calculateQualityBonus(contentScore: number, tier: ReputationTier): number {
        // High-quality content earns bonus quota
        const baseBonus = contentScore >= 80 ? 2 : contentScore >= 70 ? 1 : 0;

        // Higher tiers get larger bonuses
        const tierMultiplier = tier === ReputationTier.THOUGHT_LEADER ? 1.5 :
            tier === ReputationTier.MENTOR ? 1.3 :
                tier === ReputationTier.EXPERT ? 1.2 : 1.0;

        return Math.floor(baseBonus * tierMultiplier);
    }

    static validateContentStructure(
        quotaType: QuotaType,
        content: { topic?: string; content: string; category?: string }
    ): { valid: boolean; errors: string[] } {
        const errors: string[] = [];

        if (this.requiresTopicSelection(quotaType) && !content.topic) {
            errors.push('Topic is required for this content type');
        }

        if (this.requiresCategorization(quotaType) && !content.category) {
            errors.push('Category is required for this content type');
        }

        if (!content.content || content.content.trim().length === 0) {
            errors.push('Content cannot be empty');
        }

        // Minimum length requirements
        const minLengths: Record<QuotaType, number> = {
            POST: 20,
            COMMENT: 10,
            THREAD: 50,
            ARTICLE: 200,
            CHALLENGE: 100,
        };

        const minLength = minLengths[quotaType];
        if (content.content.length < minLength) {
            errors.push(`Content must be at least ${minLength} characters`);
        }

        return {
            valid: errors.length === 0,
            errors,
        };
    }

    static canUserMentorOthers(tier: ReputationTier, contributionScore: number): boolean {
        return tier >= ReputationTier.EXPERT && contributionScore >= 2000;
    }

    static getWeeklyLimitMultiplier(tier: ReputationTier): number {
        // Weekly limits are typically 4-5x daily limits
        const multipliers: Record<ReputationTier, number> = {
            [ReputationTier.NEWCOMER]: 4,
            [ReputationTier.CONTRIBUTOR]: 4,
            [ReputationTier.EXPERT]: 5,
            [ReputationTier.MENTOR]: 5,
            [ReputationTier.THOUGHT_LEADER]: 5,
        };

        return multipliers[tier];
    }

    private static formatTimeUntilReset(milliseconds: number): string {
        const hours = Math.floor(milliseconds / (1000 * 60 * 60));
        const minutes = Math.floor((milliseconds % (1000 * 60 * 60)) / (1000 * 60));

        if (hours > 0) {
            return `${hours}h ${minutes}m`;
        }
        return `${minutes}m`;
    }
}

import { ExpertiseBadge, ExpertiseLevel } from '../value-objects/expertise-badge.value-object';
import { ReputationTier } from '../entities/business-profile.entity';

export interface ValidationRequirements {
    minPeerEndorsements: number;
    minTrainingCompletions: number;
    requireBusinessVerification: boolean;
    minContributionScore: number;
}

export class ExpertiseValidationPolicy {
    private static readonly LEVEL_REQUIREMENTS: Record<ExpertiseLevel, ValidationRequirements> = {
        BEGINNER: {
            minPeerEndorsements: 0,
            minTrainingCompletions: 0,
            requireBusinessVerification: false,
            minContributionScore: 0,
        },
        INTERMEDIATE: {
            minPeerEndorsements: 2,
            minTrainingCompletions: 1,
            requireBusinessVerification: false,
            minContributionScore: 200,
        },
        EXPERT: {
            minPeerEndorsements: 5,
            minTrainingCompletions: 3,
            requireBusinessVerification: true,
            minContributionScore: 1000,
        },
        MENTOR: {
            minPeerEndorsements: 10,
            minTrainingCompletions: 5,
            requireBusinessVerification: true,
            minContributionScore: 3000,
        },
    };

    private static readonly BADGE_EXPIRATION_DAYS: Record<ExpertiseLevel, number | null> = {
        BEGINNER: null, // Never expires
        INTERMEDIATE: 730, // 2 years
        EXPERT: 730, // 2 years
        MENTOR: 365, // 1 year (requires active mentorship)
    };

    private static readonly MIN_REPUTATION_TIER: Record<ExpertiseLevel, ReputationTier> = {
        BEGINNER: ReputationTier.NEWCOMER,
        INTERMEDIATE: ReputationTier.CONTRIBUTOR,
        EXPERT: ReputationTier.EXPERT,
        MENTOR: ReputationTier.MENTOR,
    };

    static canEarnBadge(
        level: ExpertiseLevel,
        params: {
            peerEndorsements: number;
            trainingCompletions: number;
            businessVerified: boolean;
            contributionScore: number;
            reputationTier: ReputationTier;
        }
    ): { eligible: boolean; missingRequirements: string[] } {
        const requirements = this.LEVEL_REQUIREMENTS[level];
        const missingRequirements: string[] = [];

        if (params.peerEndorsements < requirements.minPeerEndorsements) {
            missingRequirements.push(
                `Need ${requirements.minPeerEndorsements - params.peerEndorsements} more peer endorsements`
            );
        }

        if (params.trainingCompletions < requirements.minTrainingCompletions) {
            missingRequirements.push(
                `Need ${requirements.minTrainingCompletions - params.trainingCompletions} more training completions`
            );
        }

        if (requirements.requireBusinessVerification && !params.businessVerified) {
            missingRequirements.push('Business verification required');
        }

        if (params.contributionScore < requirements.minContributionScore) {
            missingRequirements.push(
                `Need ${requirements.minContributionScore - params.contributionScore} more contribution points`
            );
        }

        const minTier = this.MIN_REPUTATION_TIER[level];
        if (!this.meetsReputationTierRequirement(params.reputationTier, minTier)) {
            missingRequirements.push(`Minimum reputation tier: ${minTier}`);
        }

        return {
            eligible: missingRequirements.length === 0,
            missingRequirements,
        };
    }

    static canUpgradeBadge(
        currentBadge: ExpertiseBadge,
        targetLevel: ExpertiseLevel,
        params: {
            contributionScore: number;
            reputationTier: ReputationTier;
        }
    ): { canUpgrade: boolean; reason?: string } {
        const levels: ExpertiseLevel[] = ['BEGINNER', 'INTERMEDIATE', 'EXPERT', 'MENTOR'];
        const currentIndex = levels.indexOf(currentBadge.level);
        const targetIndex = levels.indexOf(targetLevel);

        if (targetIndex <= currentIndex) {
            return {
                canUpgrade: false,
                reason: 'Can only upgrade to higher levels',
            };
        }

        const requirements = this.LEVEL_REQUIREMENTS[targetLevel];

        const eligibility = this.canEarnBadge(targetLevel, {
            peerEndorsements: currentBadge.peerEndorsements.length,
            trainingCompletions: currentBadge.trainingCompletions.length,
            businessVerified: currentBadge.businessVerified,
            contributionScore: params.contributionScore,
            reputationTier: params.reputationTier,
        });

        if (!eligibility.eligible) {
            return {
                canUpgrade: false,
                reason: `Missing requirements: ${eligibility.missingRequirements.join(', ')}`,
            };
        }

        return { canUpgrade: true };
    }

    static requiresRenewal(badge: ExpertiseBadge): boolean {
        const expirationDays = this.BADGE_EXPIRATION_DAYS[badge.level];

        if (expirationDays === null) {
            return false;
        }

        if (!badge.verifiedAt) {
            return false;
        }

        const daysSinceVerification = Math.floor(
            (new Date().getTime() - badge.verifiedAt.getTime()) / (1000 * 60 * 60 * 24)
        );

        return daysSinceVerification >= expirationDays;
    }

    static canEndorseBadge(
        endorserLevel: ExpertiseLevel,
        targetLevel: ExpertiseLevel
    ): boolean {
        const levels: ExpertiseLevel[] = ['BEGINNER', 'INTERMEDIATE', 'EXPERT', 'MENTOR'];
        const endorserIndex = levels.indexOf(endorserLevel);
        const targetIndex = levels.indexOf(targetLevel);

        // Can only endorse equal or lower levels
        return endorserIndex >= targetIndex;
    }

    static getExpirationDate(level: ExpertiseLevel, verificationDate: Date): Date | null {
        const expirationDays = this.BADGE_EXPIRATION_DAYS[level];

        if (expirationDays === null) {
            return null;
        }

        const expirationDate = new Date(verificationDate);
        expirationDate.setDate(expirationDate.getDate() + expirationDays);
        return expirationDate;
    }

    static shouldRevokeBadge(
        badge: ExpertiseBadge,
        params: {
            inactivityDays: number;
            contributionScore: number;
            recentViolations: number;
        }
    ): { shouldRevoke: boolean; reason?: string } {
        // Revoke if expired and not renewed
        if (badge.isExpired()) {
            return {
                shouldRevoke: true,
                reason: 'Badge has expired',
            };
        }

        // Revoke if inactive for extended period
        const maxInactivityDays: Record<ExpertiseLevel, number> = {
            BEGINNER: 365,
            INTERMEDIATE: 180,
            EXPERT: 120,
            MENTOR: 90,
        };

        if (params.inactivityDays > maxInactivityDays[badge.level]) {
            return {
                shouldRevoke: true,
                reason: `Inactive for ${params.inactivityDays} days`,
            };
        }

        // Revoke if contribution score drops below threshold
        const requirements = this.LEVEL_REQUIREMENTS[badge.level];
        if (params.contributionScore < requirements.minContributionScore * 0.5) {
            return {
                shouldRevoke: true,
                reason: 'Contribution score dropped below minimum threshold',
            };
        }

        // Revoke if multiple community guideline violations
        if (params.recentViolations >= 3) {
            return {
                shouldRevoke: true,
                reason: 'Multiple community guideline violations',
            };
        }

        return { shouldRevoke: false };
    }

    static validatePeerEndorsement(
        endorser: {
            expertiseLevel: ExpertiseLevel;
            area: string;
        },
        target: {
            area: string;
            level: ExpertiseLevel;
        }
    ): { valid: boolean; reason?: string } {
        // Must have expertise in the same area
        if (endorser.area !== target.area) {
            return {
                valid: false,
                reason: 'Endorser must have expertise in the same area',
            };
        }

        // Must have sufficient level to endorse
        if (!this.canEndorseBadge(endorser.expertiseLevel, target.level)) {
            return {
                valid: false,
                reason: 'Endorser level must be equal or higher than target level',
            };
        }

        return { valid: true };
    }

    private static meetsReputationTierRequirement(
        currentTier: ReputationTier,
        requiredTier: ReputationTier
    ): boolean {
        const tiers: ReputationTier[] = [
            ReputationTier.NEWCOMER,
            ReputationTier.CONTRIBUTOR,
            ReputationTier.EXPERT,
            ReputationTier.MENTOR,
            ReputationTier.THOUGHT_LEADER,
        ];

        const currentIndex = tiers.indexOf(currentTier);
        const requiredIndex = tiers.indexOf(requiredTier);

        return currentIndex >= requiredIndex;
    }
}

import { User, UserRole, UserStatus } from '../entities/user.entity';
import { Post, PostType, PostVisibility, PostMetadata } from '../entities/post.entity';
import { TrustMetadata } from '../value-objects/trust-metadata.value-object';

/**
 * Posting permissions policy
 * Defines what content different user roles can create and under what conditions
 */
export class PostingPermissionsPolicy {
  // Role-based posting permissions
  private static readonly ROLE_PERMISSIONS: Record<UserRole, PostType[]> = {
    [UserRole.BUYER]: [
      PostType.TEXT,
      PostType.IMAGE,
      PostType.VIDEO,
      PostType.LINK,
      PostType.QUESTION
    ],
    [UserRole.SELLER]: [
      PostType.TEXT,
      PostType.IMAGE,
      PostType.VIDEO,
      PostType.LINK,
      PostType.QUESTION,
      PostType.PRODUCT_ANNOUNCEMENT,
      PostType.PROMOTION,
      PostType.EVENT
    ],
    [UserRole.SUPPLIER]: [
      PostType.TEXT,
      PostType.IMAGE,
      PostType.VIDEO,
      PostType.LINK,
      PostType.QUESTION,
      PostType.PRODUCT_ANNOUNCEMENT,
      PostType.PROMOTION,
      PostType.EVENT
    ],
    [UserRole.COURIER]: [
      PostType.TEXT,
      PostType.IMAGE,
      PostType.DELIVERY_UPDATE,
      PostType.QUESTION
    ],
    [UserRole.ENABLER]: [
      PostType.TEXT,
      PostType.IMAGE,
      PostType.SYSTEM_NOTICE,
      PostType.QUESTION
    ],
    [UserRole.SYSTEM]: [
      PostType.SYSTEM_NOTICE,
      PostType.DELIVERY_UPDATE,
      PostType.DISPUTE_CLARIFICATION
    ]
  };

  // Visibility options by role
  private static readonly VISIBILITY_PERMISSIONS: Record<UserRole, PostVisibility[]> = {
    [UserRole.BUYER]: [PostVisibility.PUBLIC, PostVisibility.PRIVATE],
    [UserRole.SELLER]: [PostVisibility.PUBLIC, PostVisibility.FOLLOWERS, PostVisibility.PRIVATE],
    [UserRole.SUPPLIER]: [PostVisibility.PUBLIC, PostVisibility.FOLLOWERS, PostVisibility.PRIVATE],
    [UserRole.COURIER]: [PostVisibility.PUBLIC, PostVisibility.PRIVATE],
    [UserRole.ENABLER]: [PostVisibility.PUBLIC],
    [UserRole.SYSTEM]: [PostVisibility.PUBLIC]
  };

  // Daily posting limits by trust level
  private static readonly DAILY_POSTING_LIMITS = {
    low: 3,
    medium: 10,
    high: 25,
    elite: 50
  };

  // Commercial posting limits (products/promotions per day)
  private static readonly COMMERCIAL_POSTING_LIMITS = {
    low: 1,
    medium: 3,
    high: 10,
    elite: 25
  };

  /**
   * Determines if a user can create a specific type of post
   */
  static canCreatePostType(user: User, postType: PostType): boolean {
    // User must be active
    if (user.status !== UserStatus.ACTIVE) {
      return false;
    }

    // Check role permissions
    const allowedTypes = this.ROLE_PERMISSIONS[user.role] || [];
    if (!allowedTypes.includes(postType)) {
      return false;
    }

    // Special restrictions for commercial content
    if (this.isCommercialPostType(postType)) {
      return this.canCreateCommercialContent(user);
    }

    // Special restrictions for system content
    if (postType === PostType.SYSTEM_NOTICE) {
      return user.role === UserRole.ENABLER || user.role === UserRole.SYSTEM;
    }

    return true;
  }

  /**
   * Determines if a user can use a specific visibility setting
   */
  static canUseVisibility(user: User, visibility: PostVisibility): boolean {
    const allowedVisibilities = this.VISIBILITY_PERMISSIONS[user.role] || [];
    return allowedVisibilities.includes(visibility);
  }

  /**
   * Checks if user has reached daily posting limit
   */
  static hasReachedDailyLimit(user: User, postsToday: number): boolean {
    const trustLevel = user.trustMetadata.getTrustLevel();
    const limit = this.DAILY_POSTING_LIMITS[trustLevel];
    return postsToday >= limit;
  }

  /**
   * Checks if user has reached commercial posting limit
   */
  static hasReachedCommercialLimit(user: User, commercialPostsToday: number): boolean {
    const trustLevel = user.trustMetadata.getTrustLevel();
    const limit = this.COMMERCIAL_POSTING_LIMITS[trustLevel];
    return commercialPostsToday >= limit;
  }

  /**
   * Determines if user can create commercial content
   */
  static canCreateCommercialContent(user: User): boolean {
    // Must be verified for commercial content
    if (!user.isVerified) {
      return false;
    }

    // Must have minimum trust score
    if (user.trustMetadata.ratingScore < 4.0) {
      return false;
    }

    // Must have minimum completed orders
    if (user.trustMetadata.completedOrders < 5) {
      return false;
    }

    // Must have low dispute rate
    if (user.trustMetadata.disputeRate > 0.1) {
      return false;
    }

    return true;
  }

  /**
   * Determines if user can attach commerce metadata to posts
   */
  static canAttachCommerceMetadata(user: User, metadata: PostMetadata): boolean {
    // Only sellers and suppliers can attach product/order metadata
    if (metadata.relatedProductId || metadata.relatedOrderId) {
      return [UserRole.SELLER, UserRole.SUPPLIER].includes(user.role);
    }

    // Only couriers can attach shipment metadata
    if (metadata.relatedShipmentId) {
      return user.role === UserRole.COURIER;
    }

    return true;
  }

  /**
   * Validates post metadata based on post type and user permissions
   */
  static validatePostMetadata(user: User, postType: PostType, metadata?: PostMetadata): { isValid: boolean; reason?: string } {
    if (!metadata) {
      return { isValid: true };
    }

    // Validate commerce metadata permissions
    if (!this.canAttachCommerceMetadata(user, metadata)) {
      return { isValid: false, reason: 'User not authorized to attach commerce metadata' };
    }

    // Validate event metadata
    if (postType === PostType.EVENT) {
      if (!metadata.eventDetails) {
        return { isValid: false, reason: 'Event posts must include event details' };
      }

      const eventDetails = metadata.eventDetails;
      if (eventDetails.startDate <= new Date()) {
        return { isValid: false, reason: 'Event start date must be in the future' };
      }

      if (eventDetails.endDate && eventDetails.endDate <= eventDetails.startDate) {
        return { isValid: false, reason: 'Event end date must be after start date' };
      }

      if (eventDetails.capacity && eventDetails.capacity < 1) {
        return { isValid: false, reason: 'Event capacity must be at least 1' };
      }
    }

    // Validate poll metadata
    if (postType === PostType.POLL) {
      if (!metadata.pollOptions || metadata.pollOptions.length < 2) {
        return { isValid: false, reason: 'Polls must have at least 2 options' };
      }

      if (metadata.pollOptions.length > 10) {
        return { isValid: false, reason: 'Polls can have at most 10 options' };
      }

      if (metadata.pollOptions.some(option => option.trim().length === 0)) {
        return { isValid: false, reason: 'Poll options cannot be empty' };
      }

      if (metadata.pollOptions.some(option => option.length > 100)) {
        return { isValid: false, reason: 'Poll options cannot exceed 100 characters' };
      }
    }

    // Validate tags
    if (metadata.tags && metadata.tags.length > 10) {
      return { isValid: false, reason: 'Posts can have at most 10 tags' };
    }

    // Validate location data
    if (metadata.location) {
      const { latitude, longitude } = metadata.location;
      if (latitude < -90 || latitude > 90) {
        return { isValid: false, reason: 'Invalid latitude' };
      }
      if (longitude < -180 || longitude > 180) {
        return { isValid: false, reason: 'Invalid longitude' };
      }
    }

    return { isValid: true };
  }

  /**
   * Gets posting limits for a user
   */
  static getPostingLimits(user: User): {
    dailyLimit: number;
    commercialLimit: number;
    canCreateCommercial: boolean;
  } {
    const trustLevel = user.trustMetadata.getTrustLevel();

    return {
      dailyLimit: this.DAILY_POSTING_LIMITS[trustLevel],
      commercialLimit: this.COMMERCIAL_POSTING_LIMITS[trustLevel],
      canCreateCommercial: this.canCreateCommercialContent(user)
    };
  }

  /**
   * Determines if a user can edit a post
   */
  static canEditPost(user: User, post: Post): boolean {
    // Must be the author
    if (user.id !== post.authorId) {
      return false;
    }

    // Cannot edit deleted posts
    if (post.status === 'deleted') {
      return false;
    }

    // Enablers can edit any post
    if (user.role === UserRole.ENABLER) {
      return true;
    }

    // System users can edit system posts
    if (user.role === UserRole.SYSTEM && post.type === PostType.SYSTEM_NOTICE) {
      return true;
    }

    // Authors can edit their own posts within time limits
    const timeSinceCreation = Date.now() - post.createdAt.getTime();
    const hoursSinceCreation = timeSinceCreation / (1000 * 60 * 60);

    // Can edit within 24 hours for regular posts
    if (hoursSinceCreation <= 24) {
      return true;
    }

    // Can edit within 1 hour for questions
    if (post.type === PostType.QUESTION && hoursSinceCreation <= 1) {
      return true;
    }

    return false;
  }

  /**
   * Determines if a user can delete a post
   */
  static canDeletePost(user: User, post: Post): boolean {
    // Authors can delete their own posts
    if (user.id === post.authorId) {
      return true;
    }

    // Enablers can delete any post
    if (user.role === UserRole.ENABLER) {
      return true;
    }

    // System users can delete system posts
    if (user.role === UserRole.SYSTEM && post.type === PostType.SYSTEM_NOTICE) {
      return true;
    }

    return false;
  }

  /**
   * Gets allowed post types for a user
   */
  static getAllowedPostTypes(user: User): PostType[] {
    return this.ROLE_PERMISSIONS[user.role] || [];
  }

  /**
   * Gets allowed visibility options for a user
   */
  static getAllowedVisibilities(user: User): PostVisibility[] {
    return this.VISIBILITY_PERMISSIONS[user.role] || [];
  }

  static isCommercialPostType(postType: PostType): boolean {
    return [
      PostType.PRODUCT_ANNOUNCEMENT,
      PostType.PROMOTION
    ].includes(postType);
  }
}

export interface EnablerCommissionProps {
    id: string;
    enablerId: string;
    enablerOrderId: string;
    commissionId?: string | null;
    baseCommission: number;
    tierBonus: number;
    performanceBonus: number;
    totalCommission: number;
    status: string;
    approvedBy?: string | null;
    approvedAt?: Date | null;
    holdUntil?: Date | null;
    protectionStatus: string;
    fraudCheckStatus: string;
    payoutId?: string | null;
    paidAt?: Date | null;
    paymentMethod?: string | null;
    calculationDetails?: Record<string, any> | null;
    metadata?: Record<string, any> | null;
    createdAt: Date;
    updatedAt: Date;
}

/**
 * EnablerCommission entity - Tracks commission records
 */
export class EnablerCommissionEntity {
    private constructor(private readonly props: EnablerCommissionProps) { }

    static create(props: EnablerCommissionProps): EnablerCommissionEntity {
        return new EnablerCommissionEntity(props);
    }

    // Getters
    get id(): string {
        return this.props.id;
    }

    get enablerId(): string {
        return this.props.enablerId;
    }

    get totalCommission(): number {
        return this.props.totalCommission;
    }

    get status(): string {
        return this.props.status;
    }

    get holdUntil(): Date | null | undefined {
        return this.props.holdUntil;
    }

    get isPaid(): boolean {
        return this.props.status === 'paid' && this.props.paidAt !== null;
    }

    get isApproved(): boolean {
        return this.props.status === 'approved' || this.props.status === 'paid';
    }

    get isOnHold(): boolean {
        if (!this.props.holdUntil) return false;
        return new Date() < this.props.holdUntil;
    }

    // Business methods
    canBeApproved(): boolean {
        return this.props.status === 'pending' &&
            this.props.fraudCheckStatus === 'cleared' &&
            !this.isOnHold;
    }

    canBePaid(): boolean {
        return this.props.status === 'approved' &&
            !this.isOnHold &&
            this.props.fraudCheckStatus === 'cleared';
    }

    calculateHoldPeriod(): Date {
        // Default 7-day hold period
        const holdDays = 7;
        const holdDate = new Date();
        holdDate.setDate(holdDate.getDate() + holdDays);
        return holdDate;
    }

    // State transitions
    approve(approvedBy: string): void {
        if (!this.canBeApproved()) {
            throw new Error('Commission cannot be approved in current state');
        }
        this.props.status = 'approved';
        this.props.approvedBy = approvedBy;
        this.props.approvedAt = new Date();
        this.props.updatedAt = new Date();
    }

    putOnHold(reason: string, holdDays: number = 7): void {
        const holdDate = new Date();
        holdDate.setDate(holdDate.getDate() + holdDays);

        this.props.status = 'on_hold';
        this.props.holdUntil = holdDate;
        this.props.metadata = { ...this.props.metadata, holdReason: reason };
        this.props.updatedAt = new Date();
    }

    releaseHold(): void {
        if (this.props.status !== 'on_hold') {
            throw new Error('Commission is not on hold');
        }
        this.props.status = 'approved';
        this.props.holdUntil = null;
        this.props.updatedAt = new Date();
    }

    clearFraudCheck(): void {
        this.props.fraudCheckStatus = 'cleared';
        this.props.updatedAt = new Date();
    }

    flagForFraud(reason: string): void {
        this.props.fraudCheckStatus = 'flagged';
        this.props.status = 'on_hold';
        this.props.metadata = { ...this.props.metadata, fraudReason: reason };
        this.props.updatedAt = new Date();
    }

    markAsPaid(payoutId: string, paymentMethod: string): void {
        if (!this.canBePaid()) {
            throw new Error('Commission cannot be paid in current state');
        }
        this.props.status = 'paid';
        this.props.payoutId = payoutId;
        this.props.paidAt = new Date();
        this.props.paymentMethod = paymentMethod;
        this.props.updatedAt = new Date();
    }

    raiseDispute(reason: string): void {
        if (this.props.status === 'paid') {
            throw new Error('Cannot dispute a paid commission');
        }
        this.props.status = 'disputed';
        this.props.metadata = { ...this.props.metadata, disputeReason: reason };
        this.props.updatedAt = new Date();
    }

    forfeit(reason: string): void {
        this.props.status = 'forfeited';
        this.props.protectionStatus = 'forfeited';
        this.props.metadata = { ...this.props.metadata, forfeitureReason: reason };
        this.props.updatedAt = new Date();
    }

    getBreakdown(): {
        baseCommission: number;
        tierBonus: number;
        performanceBonus: number;
        totalCommission: number;
    } {
        return {
            baseCommission: this.props.baseCommission,
            tierBonus: this.props.tierBonus,
            performanceBonus: this.props.performanceBonus,
            totalCommission: this.props.totalCommission,
        };
    }

    toPlainObject(): EnablerCommissionProps {
        return { ...this.props };
    }
}

