/**
 * Value Object for Listing Terms
 */
export interface ListingTermsData {
    minOrderQuantity?: number;
    maxOrderQuantity?: number;
    deliveryTimeframe?: string;
    returnPolicy?: string;
    warrantyPeriod?: number;
    specialInstructions?: string;
    promotionalText?: string;
    restrictedRegions?: string[];
    [key: string]: any;
}

export class ListingTerms {
    private constructor(private readonly terms: ListingTermsData) {
        this.validate(terms);
    }

    static create(terms: ListingTermsData): ListingTerms {
        return new ListingTerms(terms);
    }

    static createDefault(): ListingTerms {
        return new ListingTerms({
            minOrderQuantity: 1,
            deliveryTimeframe: 'Standard',
            restrictedRegions: [],
        });
    }

    private validate(terms: ListingTermsData): void {
        if (terms.minOrderQuantity && terms.maxOrderQuantity) {
            if (terms.minOrderQuantity > terms.maxOrderQuantity) {
                throw new Error('Minimum order quantity cannot exceed maximum');
            }
        }

        if (terms.minOrderQuantity && terms.minOrderQuantity < 1) {
            throw new Error('Minimum order quantity must be at least 1');
        }

        if (terms.warrantyPeriod && terms.warrantyPeriod < 0) {
            throw new Error('Warranty period cannot be negative');
        }
    }

    getTerms(): ListingTermsData {
        return { ...this.terms };
    }

    getMinOrderQuantity(): number | undefined {
        return this.terms.minOrderQuantity;
    }

    getMaxOrderQuantity(): number | undefined {
        return this.terms.maxOrderQuantity;
    }

    getDeliveryTimeframe(): string | undefined {
        return this.terms.deliveryTimeframe;
    }

    hasReturnPolicy(): boolean {
        return !!this.terms.returnPolicy;
    }

    hasWarranty(): boolean {
        return !!this.terms.warrantyPeriod && this.terms.warrantyPeriod > 0;
    }

    isRegionRestricted(region: string): boolean {
        return this.terms.restrictedRegions?.includes(region) || false;
    }

    withMinOrderQuantity(quantity: number): ListingTerms {
        return new ListingTerms({ ...this.terms, minOrderQuantity: quantity });
    }

    withMaxOrderQuantity(quantity: number): ListingTerms {
        return new ListingTerms({ ...this.terms, maxOrderQuantity: quantity });
    }

    withDeliveryTimeframe(timeframe: string): ListingTerms {
        return new ListingTerms({ ...this.terms, deliveryTimeframe: timeframe });
    }

    withReturnPolicy(policy: string): ListingTerms {
        return new ListingTerms({ ...this.terms, returnPolicy: policy });
    }

    withWarranty(days: number): ListingTerms {
        return new ListingTerms({ ...this.terms, warrantyPeriod: days });
    }

    addRestrictedRegion(region: string): ListingTerms {
        const regions = [...(this.terms.restrictedRegions || []), region];
        return new ListingTerms({ ...this.terms, restrictedRegions: regions });
    }

    toJSON(): ListingTermsData {
        return this.getTerms();
    }

    equals(other: ListingTerms): boolean {
        return JSON.stringify(this.terms) === JSON.stringify(other.terms);
    }
}

export interface StockReservation {
  reservationId: string;
  productVariantId: string;
  quantity: number;
  reservedFor: string; // orderId
  expiresAt: Date;
  status: 'active' | 'expired' | 'fulfilled' | 'cancelled';
}

export interface StockAvailability {
  productVariantId: string;
  totalStock: number;
  availableStock: number;
  reservedStock: number;
  reorderLevel: number;
  needsReorder: boolean;
  confidence: number;
}

interface StockRedisPipeline {
  hgetall(key: string): this;
  get(key: string): this;
  exec(): Promise<Array<[Error | null, unknown]> | null>;
}

interface StockRedisClient {
  setex(key: string, seconds: number, value: string): Promise<unknown>;
  zadd(key: string, score: number, member: string): Promise<unknown>;
  incrby(key: string, increment: number): Promise<unknown>;
  decrby(key: string, decrement: number): Promise<unknown>;
  del(key: string): Promise<unknown>;
  zrem(key: string, member: string): Promise<unknown>;
  hgetall(key: string): Promise<Record<string, string>>;
  get(key: string): Promise<string | null>;
  pipeline(): StockRedisPipeline;
  keys(pattern: string): Promise<string[]>;
  zrangebyscore(key: string, min: number, max: number): Promise<string[]>;
  zremrangebyscore(key: string, min: number, max: number): Promise<unknown>;
  hincrby(key: string, field: string, increment: number): Promise<unknown>;
  lrange(key: string, start: number, stop: number): Promise<string[]>;
  lpush(key: string, value: string): Promise<unknown>;
  ltrim(key: string, start: number, stop: number): Promise<unknown>;
}

interface StockLock {
  withLock<T>(key: string, fn: () => Promise<T>): Promise<T>;
}

export class StockEngine {
  private readonly RESERVATION_TTL = 900; // 15 minutes
  private readonly ACCURACY_TARGET = 99.9;

  constructor(
    private readonly redis: StockRedisClient,
    private readonly redisLock: StockLock
  ) {}

  async checkAvailability(productVariantId: string, quantity: number): Promise<StockAvailability> {
    const stockData = await this.getStockData(productVariantId);
    const reservedQuantity = await this.getReservedQuantity(productVariantId);
    
    const availableStock = stockData.totalStock - reservedQuantity;
    const needsReorder = availableStock <= stockData.reorderLevel;
    
    return {
      productVariantId,
      totalStock: stockData.totalStock,
      availableStock,
      reservedStock: reservedQuantity,
      reorderLevel: stockData.reorderLevel,
      needsReorder,
      confidence: 99.95
    };
  }

  async reserveStock(productVariantId: string, quantity: number, orderId: string): Promise<StockReservation> {
    return this.redisLock.withLock(`inventory:reserve:${productVariantId}`, async () => {
      const availability = await this.checkAvailability(productVariantId, quantity);
      
      if (availability.availableStock < quantity) {
        throw new Error(`Insufficient stock. Available: ${availability.availableStock}, Requested: ${quantity}`);
      }
      
      const reservationId = this.generateReservationId();
      const expiresAt = new Date(Date.now() + this.RESERVATION_TTL * 1000);
      
      const reservation: StockReservation = {
        reservationId,
        productVariantId,
        quantity,
        reservedFor: orderId,
        expiresAt,
        status: 'active'
      };
      
      // Store reservation with TTL
      await this.redis.setex(
        `reservation:${reservationId}`, 
        this.RESERVATION_TTL, 
        JSON.stringify(reservation)
      );
      
      // Add to product reservations set
      await this.redis.zadd(
        `reservations:${productVariantId}`, 
        expiresAt.getTime(), 
        reservationId
      );
      
      // Update reserved quantity
      await this.redis.incrby(`reserved:${productVariantId}`, quantity);
      
      return reservation;
    });
  }

  async confirmReservation(reservationId: string): Promise<boolean> {
    const reservation = await this.getReservation(reservationId);
    if (!reservation || reservation.status !== 'active') {
      return false;
    }
    
    // Update stock levels
    await this.updateStock(reservation.productVariantId, -reservation.quantity);
    
    // Remove from reserved
    await this.redis.decrby(`reserved:${reservation.productVariantId}`, reservation.quantity);
    
    // Mark reservation as fulfilled
    reservation.status = 'fulfilled';
    await this.redis.setex(
      `reservation:${reservationId}`, 
      86400, // Keep for 24 hours for audit
      JSON.stringify(reservation)
    );
    
    return true;
  }

  async releaseReservation(reservationId: string): Promise<boolean> {
    const reservation = await this.getReservation(reservationId);
    if (!reservation || reservation.status !== 'active') {
      return false;
    }
    
    // Remove from reserved
    await this.redis.decrby(`reserved:${reservation.productVariantId}`, reservation.quantity);
    
    // Remove reservation
    await this.redis.del(`reservation:${reservationId}`);
    await this.redis.zrem(`reservations:${reservation.productVariantId}`, reservationId);
    
    return true;
  }

  async bulkCheckAvailability(requests: { productVariantId: string; quantity: number }[]): Promise<StockAvailability[]> {
    const pipeline = this.redis.pipeline();
    
    // Batch fetch stock data
    requests.forEach(req => {
      pipeline.hgetall(`stock:${req.productVariantId}`);
      pipeline.get(`reserved:${req.productVariantId}`);
    });
    
    const results = await pipeline.exec();
    if (!results) {
      return [];
    }
    const availabilities: StockAvailability[] = [];
    
    for (let i = 0; i < requests.length; i++) {
      const stockData = results[i * 2][1] as any;
      const reservedQuantity = parseInt(results[i * 2 + 1][1] as string) || 0;
      
      const totalStock = parseInt(stockData.totalStock) || 0;
      const availableStock = totalStock - reservedQuantity;
      const reorderLevel = parseInt(stockData.reorderLevel) || 0;
      
      availabilities.push({
        productVariantId: requests[i].productVariantId,
        totalStock,
        availableStock,
        reservedStock: reservedQuantity,
        reorderLevel,
        needsReorder: availableStock <= reorderLevel,
        confidence: 99.95
      });
    }
    
    return availabilities;
  }

  async cleanupExpiredReservations(): Promise<number> {
    const now = Date.now();
    let cleanedCount = 0;
    
    // Get all product variants with reservations
    const productKeys = await this.redis.keys('reservations:*');
    
    for (const key of productKeys) {
      const productVariantId = key.replace('reservations:', '');
      
      // Get expired reservations
      const expiredReservations = await this.redis.zrangebyscore(key, 0, now);
      
      for (const reservationId of expiredReservations) {
        const reservation = await this.getReservation(reservationId);
        if (reservation && reservation.status === 'active') {
          await this.releaseReservation(reservationId);
          cleanedCount++;
        }
      }
      
      // Remove expired entries from sorted set
      await this.redis.zremrangebyscore(key, 0, now);
    }
    
    return cleanedCount;
  }

  async updateStock(productVariantId: string, quantityChange: number): Promise<void> {
    await this.redis.hincrby(`stock:${productVariantId}`, 'totalStock', quantityChange);
    
    // Log stock movement
    await this.logStockMovement(productVariantId, quantityChange, 'stock_update');
  }

  async getStockMovementHistory(productVariantId: string, limit: number = 100): Promise<any[]> {
    const movements = await this.redis.lrange(`movements:${productVariantId}`, 0, limit - 1);
    return movements.map(movement => JSON.parse(movement));
  }

  private async getStockData(productVariantId: string): Promise<any> {
    const stockData = await this.redis.hgetall(`stock:${productVariantId}`);
    return {
      totalStock: parseInt(stockData.totalStock) || 0,
      reorderLevel: parseInt(stockData.reorderLevel) || 0
    };
  }

  private async getReservedQuantity(productVariantId: string): Promise<number> {
    const reserved = await this.redis.get(`reserved:${productVariantId}`);
    return parseInt(reserved || '0');
  }

  private async getReservation(reservationId: string): Promise<StockReservation | null> {
    const data = await this.redis.get(`reservation:${reservationId}`);
    return data ? JSON.parse(data) : null;
  }

  private async logStockMovement(productVariantId: string, quantity: number, type: string): Promise<void> {
    const movement = {
      productVariantId,
      quantity,
      type,
      timestamp: new Date(),
      balance: await this.getStockData(productVariantId).then(data => data.totalStock)
    };
    
    await this.redis.lpush(`movements:${productVariantId}`, JSON.stringify(movement));
    await this.redis.ltrim(`movements:${productVariantId}`, 0, 999); // Keep last 1000 movements
  }

  private generateReservationId(): string {
    return `res_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

import { execSync } from 'child_process';
import path from 'path';

type MigrationMode = 'deploy' | 'dev';

const resolveSchemaPath = (): string => {
  if (process.env.PRISMA_SCHEMA_PATH) {
    return process.env.PRISMA_SCHEMA_PATH;
  }

  const repoRoot = path.resolve(__dirname, '..', '..', '..');
  return path.join(repoRoot, 'prisma', 'schema.prisma');
};

const resolveMigrationMode = (): MigrationMode => {
  const mode = process.env.MIGRATION_MODE?.toLowerCase();
  if (mode === 'dev' || mode === 'deploy') {
    return mode;
  }

  return process.env.NODE_ENV === 'production' ? 'deploy' : 'deploy';
};

const runPrismaMigrations = (): void => {
  const schemaPath = resolveSchemaPath();
  const repoRoot = path.resolve(__dirname, '..', '..', '..');
  const mode = resolveMigrationMode();
  const migrateCommand =
    mode === 'dev'
      ? `npx prisma migrate dev --schema "${schemaPath}"`
      : `npx prisma migrate deploy --schema "${schemaPath}"`;

  execSync(migrateCommand, { stdio: 'inherit', cwd: repoRoot });
  execSync(`npx prisma generate --schema "${schemaPath}"`, { stdio: 'inherit', cwd: repoRoot });
  console.log('Prisma migrations applied for logistics service');
};

try {
  runPrismaMigrations();
} catch (error) {
  console.error(error);
  process.exitCode = 1;
}

