import { DomainPolicy } from '../interfaces';
import { Notification } from '../entities/notification.entity';
import { NotificationPreference } from '../entities/notification-preference.entity';

/**
 * Notification Delivery Policy
 * Implements delivery rules, retry logic, rate limits, and consent
 */
export class NotificationDeliveryPolicy implements DomainPolicy {
  public readonly name = 'NotificationDeliveryPolicy';

  private static readonly RATE_LIMIT_PER_CHANNEL = 100; // per hour per user
  private static readonly RETRYABLE_ERRORS = ['TIMEOUT', 'RATE_LIMIT', 'SERVICE_UNAVAILABLE'];

  canSendNotification(
    _user: { id: string },
    notification: Notification,
    preference: NotificationPreference | null,
    sentCountLastHour: number
  ): { allowed: boolean; reason?: string } {
    if (!preference?.enabled) {
      return { allowed: false, reason: 'User has disabled this channel' };
    }
    if (preference.channel !== notification.channel) {
      return { allowed: false, reason: 'Channel mismatch' };
    }
    if (!preference.canSend(notification)) {
      return { allowed: false, reason: 'User preferences do not allow this notification' };
    }
    if (sentCountLastHour >= NotificationDeliveryPolicy.RATE_LIMIT_PER_CHANNEL) {
      return { allowed: false, reason: 'Rate limit exceeded for this channel' };
    }
    return { allowed: true };
  }

  shouldRetry(notification: Notification): boolean {
    if (notification.status !== 'failed') return false;
    if (notification.retryCount >= notification.maxRetries) return false;
    const lastError = (notification.lastError || '').toUpperCase();
    return NotificationDeliveryPolicy.RETRYABLE_ERRORS.some(e => lastError.includes(e));
  }

  getRetryDelay(retryCount: number): number {
    const baseMs = 1000;
    return baseMs * Math.pow(2, Math.min(retryCount, 5));
  }

  isWithinRateLimit(userId: string, _channel: string, sentCountLastHour: number): boolean {
    return sentCountLastHour < NotificationDeliveryPolicy.RATE_LIMIT_PER_CHANNEL;
  }

  requiresUserConsent(notificationType: string): boolean {
    const marketingTypes = ['promotion', 'newsletter', 'marketing'];
    return marketingTypes.includes(notificationType.toLowerCase());
  }

  evaluate(...args: any[]): boolean {
    if (args.length >= 4) {
      const result = this.canSendNotification(args[0], args[1], args[2], args[3]);
      return result.allowed;
    }
    return false;
  }
}

import { DomainPolicy } from '../interfaces';
import { Notification, NotificationPriority } from '../entities/notification.entity';

/**
 * Notification Priority Policy
 * Priority-based delivery rules and SLA windows
 */
export class NotificationPriorityPolicy implements DomainPolicy {
  public readonly name = 'NotificationPriorityPolicy';

  private static readonly PRIORITY_SCORE: Record<NotificationPriority, number> = {
    low: 1,
    medium: 2,
    high: 3,
    urgent: 4
  };

  private static readonly SLA_MINUTES: Record<NotificationPriority, number> = {
    low: 1440,    // 24h
    medium: 60,   // 1h
    high: 15,     // 15min
    urgent: 5      // 5min
  };

  getPriority(notification: Notification): number {
    return NotificationPriorityPolicy.PRIORITY_SCORE[notification.priority] ?? 0;
  }

  shouldBypassQuietHours(notification: Notification): boolean {
    return notification.priority === 'urgent' || notification.priority === 'high';
  }

  getDeliveryWindow(priority: NotificationPriority): number {
    return NotificationPriorityPolicy.SLA_MINUTES[priority] ?? 60;
  }

  evaluate(...args: any[]): boolean {
    if (args.length >= 1 && typeof args[0]?.priority !== 'undefined') {
      return this.getPriority(args[0]) > 0;
    }
    return false;
  }
}

/**
 * Delivery Address value object
 * Supports email addresses, phone numbers, device tokens
 */

export type DeliveryAddressType = 'email' | 'phone' | 'device_token';

const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
const PHONE_REGEX = /^(\+255|0)(7[0-9]|6[0-9]|2[0-9])\d{7}$/;
const DEVICE_TOKEN_MIN = 64;
const DEVICE_TOKEN_MAX = 256;

export class DeliveryAddress {
  private constructor(
    private readonly _value: string,
    private readonly _type: DeliveryAddressType
  ) {}

  static create(value: string, type: DeliveryAddressType): DeliveryAddress {
    const trimmed = value?.trim();
    if (!trimmed) throw new Error('Delivery address is required');

    switch (type) {
      case 'email':
        if (!EMAIL_REGEX.test(trimmed)) throw new Error('Invalid email format');
        return new DeliveryAddress(trimmed.toLowerCase(), type);
      case 'phone':
        const normalized = trimmed.replace(/\s+/g, '');
        if (!PHONE_REGEX.test(normalized)) throw new Error('Invalid phone number format');
        return new DeliveryAddress(normalized, type);
      case 'device_token':
        if (trimmed.length < DEVICE_TOKEN_MIN || trimmed.length > DEVICE_TOKEN_MAX) {
          throw new Error(`Device token must be between ${DEVICE_TOKEN_MIN} and ${DEVICE_TOKEN_MAX} characters`);
        }
        return new DeliveryAddress(trimmed, type);
      default:
        throw new Error(`Unsupported delivery address type: ${type}`);
    }
  }

  getValue(): string {
    return this._value;
  }

  getType(): DeliveryAddressType {
    return this._type;
  }

  isValid(): boolean {
    try {
      switch (this._type) {
        case 'email':
          return EMAIL_REGEX.test(this._value);
        case 'phone':
          return PHONE_REGEX.test(this._value);
        case 'device_token':
          return this._value.length >= DEVICE_TOKEN_MIN && this._value.length <= DEVICE_TOKEN_MAX;
        default:
          return false;
      }
    } catch {
      return false;
    }
  }

  equals(other: DeliveryAddress): boolean {
    return this._value === other._value && this._type === other._type;
  }

  toString(): string {
    return this._value;
  }
}

import 'reflect-metadata';
import express, { Express } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import compression from 'compression';
import { createSmsRouter } from './api/routes';

export class SmsServiceApplication {
    private app: Express;

    constructor() {
        this.app = express();
        this.setupMiddleware();
        this.setupRoutes();
    }

    private setupMiddleware(): void {
        this.app.use(helmet());
        this.app.use(cors());
        this.app.use(compression());
        this.app.use(express.json());
        this.app.use(express.urlencoded({ extended: true }));
    }

    private setupRoutes(): void {
        // Health check
        this.app.get('/health', (req, res) => {
            res.json({ status: 'OK', service: 'sms-service', timestamp: new Date() });
        });

        // API Routes
        this.app.use('/api/v1/sms', createSmsRouter());

        // Global error handler
        this.app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
            console.error('Unhandled error:', err);
            res.status(500).json({
                success: false,
                error: {
                    code: 'INTERNAL_SERVER_ERROR',
                    message: err.message || 'An unexpected error occurred'
                }
            });
        });
    }

    public getApp(): Express {
        return this.app;
    }

    public async start(port: number): Promise<void> {
        return new Promise((resolve) => {
            this.app.listen(port, () => {
                console.log(`SMS Service running on port ${port}`);
                resolve();
            });
        });
    }
}

export const createServer = (_container?: unknown): Express => {
    return new SmsServiceApplication().getApp();
};

import { PhoneNumber } from '../value-objects/phone-number.value-object';
import { MessageContent } from '../value-objects/message-content.value-object';
import { ProviderResponse } from '../value-objects/provider-response.value-object';
import { InvalidStateTransitionError } from '../errors/sms.errors';
import {
    SmsQueued,
    SmsSending,
    SmsSent,
    SmsDelivered,
    SmsFailed,
    SmsCancelled,
    SmsUndelivered,
    DomainEvent
} from '../events/sms.events';

/**
 * SMS Message Status
 * Represents the lifecycle states of an SMS message
 */
export enum SmsStatus {
    QUEUED = 'QUEUED',
    SENDING = 'SENDING',
    SENT = 'SENT',
    DELIVERED = 'DELIVERED',
    UNDELIVERED = 'UNDELIVERED',
    FAILED = 'FAILED',
    CANCELLED = 'CANCELLED'
}

/**
 * SMS Message Entity
 * Core domain entity representing an SMS message
 */
export class SmsMessage {
    private readonly id: string;
    private readonly phoneNumber: PhoneNumber;
    private readonly content: MessageContent;
    private status: SmsStatus;
    private providerId?: string;
    private providerMessageId?: string;
    private readonly userId?: string;
    private retryCount: number;
    private readonly maxRetries: number;
    private readonly scheduledAt?: Date;
    private sentAt?: Date;
    private deliveredAt?: Date;
    private failedAt?: Date;
    private lastError?: string;
    private readonly metadata?: Record<string, any>;
    private readonly createdAt: Date;
    private updatedAt: Date;
    private domainEvents: DomainEvent[] = [];

    private constructor(props: {
        id: string;
        phoneNumber: PhoneNumber;
        content: MessageContent;
        status: SmsStatus;
        providerId?: string;
        providerMessageId?: string;
        userId?: string;
        retryCount: number;
        maxRetries: number;
        scheduledAt?: Date;
        sentAt?: Date;
        deliveredAt?: Date;
        failedAt?: Date;
        lastError?: string;
        metadata?: Record<string, any>;
        createdAt: Date;
        updatedAt: Date;
    }) {
        this.id = props.id;
        this.phoneNumber = props.phoneNumber;
        this.content = props.content;
        this.status = props.status;
        this.providerId = props.providerId;
        this.providerMessageId = props.providerMessageId;
        this.userId = props.userId;
        this.retryCount = props.retryCount;
        this.maxRetries = props.maxRetries;
        this.scheduledAt = props.scheduledAt;
        this.sentAt = props.sentAt;
        this.deliveredAt = props.deliveredAt;
        this.failedAt = props.failedAt;
        this.lastError = props.lastError;
        this.metadata = props.metadata;
        this.createdAt = props.createdAt;
        this.updatedAt = props.updatedAt;
    }

    /**
     * Factory method to create a new SMS message
     */
    static create(props: {
        id: string;
        phoneNumber: string;
        content: string;
        userId?: string;
        maxRetries?: number;
        scheduledAt?: Date;
        metadata?: Record<string, any>;
    }): SmsMessage {
        const phoneNumber = PhoneNumber.create(props.phoneNumber);
        const content = MessageContent.create(props.content);
        const now = new Date();

        const message = new SmsMessage({
            id: props.id,
            phoneNumber,
            content,
            status: SmsStatus.QUEUED,
            userId: props.userId,
            retryCount: 0,
            maxRetries: props.maxRetries ?? 3,
            scheduledAt: props.scheduledAt,
            metadata: props.metadata,
            createdAt: now,
            updatedAt: now
        });

        // Add domain event
        message.addDomainEvent(
            new SmsQueued(
                props.id,
                phoneNumber.getValue(),
                content.getSegmentCount(),
                props.userId
            )
        );

        return message;
    }

    /**
     * Reconstitute from persistence
     */
    static reconstitute(props: {
        id: string;
        phoneNumber: string;
        content: string;
        status: SmsStatus;
        providerId?: string;
        providerMessageId?: string;
        userId?: string;
        retryCount: number;
        maxRetries: number;
        scheduledAt?: Date;
        sentAt?: Date;
        deliveredAt?: Date;
        failedAt?: Date;
        lastError?: string;
        metadata?: Record<string, any>;
        createdAt: Date;
        updatedAt: Date;
    }): SmsMessage {
        const phoneNumber = PhoneNumber.create(props.phoneNumber);
        const content = MessageContent.create(props.content);

        return new SmsMessage({
            ...props,
            phoneNumber,
            content
        });
    }

    // ==================== State Transitions ====================

    markAsSending(providerId: string): void {
        this.validateTransition(SmsStatus.SENDING);

        this.status = SmsStatus.SENDING;
        this.providerId = providerId;
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsSending(this.id, this.phoneNumber.getValue(), providerId)
        );
    }

    markAsSent(providerResponse: ProviderResponse): void {
        this.validateTransition(SmsStatus.SENT);

        this.status = SmsStatus.SENT;
        this.providerMessageId = providerResponse.getProviderMessageId();
        this.sentAt = new Date();
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsSent(
                this.id,
                this.phoneNumber.getValue(),
                this.providerId!,
                this.providerMessageId
            )
        );
    }

    markAsDelivered(): void {
        this.validateTransition(SmsStatus.DELIVERED);

        this.status = SmsStatus.DELIVERED;
        this.deliveredAt = new Date();
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsDelivered(
                this.id,
                this.phoneNumber.getValue(),
                this.providerId!,
                this.providerMessageId!
            )
        );
    }

    markAsUndelivered(reason?: string): void {
        this.validateTransition(SmsStatus.UNDELIVERED);

        this.status = SmsStatus.UNDELIVERED;
        this.lastError = reason;
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsUndelivered(
                this.id,
                this.phoneNumber.getValue(),
                this.providerId!,
                this.providerMessageId!,
                reason
            )
        );
    }

    markAsFailed(error: string): void {
        this.validateTransition(SmsStatus.FAILED);

        this.status = SmsStatus.FAILED;
        this.lastError = error;
        this.failedAt = new Date();
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsFailed(
                this.id,
                this.phoneNumber.getValue(),
                error,
                this.retryCount,
                this.canRetry(),
                this.providerId
            )
        );
    }

    markAsCancelled(reason: string): void {
        this.validateTransition(SmsStatus.CANCELLED);

        this.status = SmsStatus.CANCELLED;
        this.lastError = reason;
        this.updatedAt = new Date();

        this.addDomainEvent(
            new SmsCancelled(this.id, this.phoneNumber.getValue(), reason, this.retryCount)
        );
    }

    // ==================== Retry Logic ====================

    canRetry(): boolean {
        return this.status === SmsStatus.FAILED && this.retryCount < this.maxRetries;
    }

    incrementRetryCount(): void {
        if (!this.canRetry()) {
            throw new Error('Cannot retry: max retries exceeded or message not in FAILED state');
        }

        this.retryCount++;
        this.status = SmsStatus.QUEUED;
        this.lastError = undefined;
        this.updatedAt = new Date();
    }

    // ==================== Validation ====================

    private validateTransition(newStatus: SmsStatus): void {
        const validTransitions: Record<SmsStatus, SmsStatus[]> = {
            [SmsStatus.QUEUED]: [SmsStatus.SENDING, SmsStatus.CANCELLED],
            [SmsStatus.SENDING]: [SmsStatus.SENT, SmsStatus.FAILED],
            [SmsStatus.SENT]: [SmsStatus.DELIVERED, SmsStatus.UNDELIVERED],
            [SmsStatus.DELIVERED]: [],
            [SmsStatus.UNDELIVERED]: [],
            [SmsStatus.FAILED]: [SmsStatus.QUEUED, SmsStatus.CANCELLED],
            [SmsStatus.CANCELLED]: []
        };

        const allowedTransitions = validTransitions[this.status];
        if (!allowedTransitions.includes(newStatus)) {
            throw new InvalidStateTransitionError(
                this.status,
                newStatus,
                'Invalid state transition for SMS message'
            );
        }
    }

    // ==================== Domain Events ====================

    private addDomainEvent(event: DomainEvent): void {
        this.domainEvents.push(event);
    }

    getDomainEvents(): DomainEvent[] {
        return [...this.domainEvents];
    }

    clearDomainEvents(): void {
        this.domainEvents = [];
    }

    // ==================== Getters ====================

    getId(): string {
        return this.id;
    }

    getPhoneNumber(): PhoneNumber {
        return this.phoneNumber;
    }

    getContent(): MessageContent {
        return this.content;
    }

    getStatus(): SmsStatus {
        return this.status;
    }

    getProviderId(): string | undefined {
        return this.providerId;
    }

    getProviderMessageId(): string | undefined {
        return this.providerMessageId;
    }

    getUserId(): string | undefined {
        return this.userId;
    }

    getRetryCount(): number {
        return this.retryCount;
    }

    getMaxRetries(): number {
        return this.maxRetries;
    }

    getScheduledAt(): Date | undefined {
        return this.scheduledAt;
    }

    getSentAt(): Date | undefined {
        return this.sentAt;
    }

    getDeliveredAt(): Date | undefined {
        return this.deliveredAt;
    }

    getFailedAt(): Date | undefined {
        return this.failedAt;
    }

    getLastError(): string | undefined {
        return this.lastError;
    }

    getMetadata(): Record<string, any> | undefined {
        return this.metadata;
    }

    getCreatedAt(): Date {
        return this.createdAt;
    }

    getUpdatedAt(): Date {
        return this.updatedAt;
    }

    // ==================== Utility Methods ====================

    isQueued(): boolean {
        return this.status === SmsStatus.QUEUED;
    }

    isSending(): boolean {
        return this.status === SmsStatus.SENDING;
    }

    isSent(): boolean {
        return this.status === SmsStatus.SENT;
    }

    isDelivered(): boolean {
        return this.status === SmsStatus.DELIVERED;
    }

    isFailed(): boolean {
        return this.status === SmsStatus.FAILED;
    }

    isCancelled(): boolean {
        return this.status === SmsStatus.CANCELLED;
    }

    isTerminal(): boolean {
        return [
            SmsStatus.DELIVERED,
            SmsStatus.UNDELIVERED,
            SmsStatus.CANCELLED
        ].includes(this.status);
    }
}

