    ) {
        this.eventId = this.generateEventId();
        this.occurredAt = new Date();
        this.aggregateId = messageId;
        this.payload = {
            messageId,
            phoneNumber,
            providerId,
            providerMessageId,
            reason
        };
    }

    private generateEventId(): string {
        return `${this.eventType}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    }
}

