import { IEventPublisher } from './messaging/event-publisher';

// Implementations
import { PrismaSmsRepository } from './repositories/prisma-sms.repository';
import { AfricasTalkingSmsProvider } from './providers/africastalking-sms.provider';
import { EventPublisher } from './messaging/event-publisher';

// Policies
import { RetryPolicy } from '../domain/policies/retry.policy';
import { RateLimitPolicy } from '../domain/policies/rate-limit.policy';

// Use Cases
import { SendSmsUseCase } from '../application/use-cases/send-sms.use-case';
import { TrackDeliveryUseCase } from '../application/use-cases/track-delivery.use-case';
import { HandleDeliveryReportUseCase } from '../application/use-cases/handle-delivery-report.use-case';
import { RetryFailedMessagesUseCase } from '../application/use-cases/retry-failed-messages.use-case';
import { GetStatisticsUseCase } from '../application/use-cases/get-statistics.use-case';

// Controllers
import { SmsController } from '../api/controllers/sms.controller';

export const container = new Container();

// Core dependencies
container.bind<PrismaClient>(TYPES.PrismaClient).toConstantValue(createPrismaClient());

// Infrastructure
container.bind<ISmsRepository>(TYPES.SmsRepository).toDynamicValue((context) => {
    const prisma = context.container.get<PrismaClient>(TYPES.PrismaClient);
    return new PrismaSmsRepository(prisma);
}).inSingletonScope();
container.bind<IEventPublisher>(TYPES.EventPublisher).to(EventPublisher).inSingletonScope();

// Provider selection based on config
const smsProviderName = (process.env.SMS_PROVIDER || process.env.SMS_SERVICE_PROVIDER || 'africastalking').toLowerCase();
const parseOptionalInt = (value?: string): number | undefined => {
    if (!value) {
        return undefined;
    }
    const parsed = parseInt(value, 10);
    return Number.isFinite(parsed) ? parsed : undefined;
};
const isProduction = process.env.NODE_ENV === 'production';
const allowLiveInDev = (process.env.SMS_ALLOW_LIVE_IN_DEV || '').toLowerCase() === 'true';
const africasTalkingEnvRaw = (process.env.AFRICASTALKING_ENV || (isProduction ? 'live' : 'sandbox')).toLowerCase();
const isLiveRequested = africasTalkingEnvRaw === 'live';
const africasTalkingEnv = isLiveRequested && (isProduction || allowLiveInDev) ? 'live' : 'sandbox';
const isSandboxEnv = africasTalkingEnv === 'sandbox';
const perUserLimitPerHour = parseOptionalInt(process.env.SMS_RATE_LIMIT_PER_USER_PER_HOUR);
const perPhoneNumberLimitPerDay = parseOptionalInt(process.env.SMS_RATE_LIMIT_PER_PHONE_NUMBER_PER_DAY);
const resolvedBaseUrl = (process.env.AFRICASTALKING_BASE_URL ||
    (africasTalkingEnv === 'sandbox'
        ? 'https://api.sandbox.africastalking.com/version1'
        : 'https://api.africastalking.com/version1')).replace(/\/+$/, '');
const resolvedUsername = process.env.AFRICASTALKING_USERNAME || process.env.SMS_SERVICE_USERNAME || 'sandbox';
const apiKeyStatus = (process.env.AFRICASTALKING_API_KEY || process.env.SMS_SERVICE_API_KEY) ? 'set' : 'missing';
const hasBaseUrlOverride = Boolean(process.env.AFRICASTALKING_BASE_URL);
// One-time startup log to verify env resolution (no secrets).
if (!(globalThis as any).__smsEnvLogged) {
    (globalThis as any).__smsEnvLogged = true;
    console.info('[sms] provider=%s env=%s baseUrl=%s baseUrlOverride=%s username=%s apiKey=%s allowLiveInDev=%s node_env=%s',
        smsProviderName,
        africasTalkingEnv,
        resolvedBaseUrl,
        hasBaseUrlOverride ? 'yes' : 'no',
        resolvedUsername,
        apiKeyStatus,
        allowLiveInDev ? 'true' : 'false',
        process.env.NODE_ENV || 'development'
    );
}
if (smsProviderName !== 'africastalking') {
    throw new Error(`Unsupported SMS provider "${smsProviderName}". Configure SMS_PROVIDER=africastalking.`);
}

const apiKey = process.env.AFRICASTALKING_API_KEY || process.env.SMS_SERVICE_API_KEY;

const provider = (() => {
    if (!apiKey) {
        throw new Error('Missing AFRICASTALKING_API_KEY (or SMS_SERVICE_API_KEY). SMS provider cannot be initialized.');
    }

    return new AfricasTalkingSmsProvider({
        username: resolvedUsername,
        apiKey,
        senderId: process.env.AFRICASTALKING_SENDER_ID,
        environment: africasTalkingEnv,
        baseUrl: resolvedBaseUrl,
        bulkSMSMode: parseOptionalInt(process.env.AFRICASTALKING_BULK_SMS_MODE),
        enqueue: parseOptionalInt(process.env.AFRICASTALKING_ENQUEUE),
        keyword: process.env.AFRICASTALKING_KEYWORD,
        linkId: process.env.AFRICASTALKING_LINK_ID,
        retryDurationInHours: parseOptionalInt(process.env.AFRICASTALKING_RETRY_DURATION_HOURS)
    });
})();

container.bind<ISmsProvider>(TYPES.SmsProvider).toConstantValue(provider);

// Policies
container.bind<RetryPolicy>(TYPES.RetryPolicy).toConstantValue(new RetryPolicy({
    maxRetries: parseInt(process.env.SMS_MAX_RETRIES || '3', 10),
    baseDelayMs: 1000,
    maxDelayMs: 300000,
    backoffMultiplier: 2
}));

container.bind<RateLimitPolicy>(TYPES.RateLimitPolicy).toConstantValue(new RateLimitPolicy({
    maxMessagesPerMinute: parseInt(process.env.SMS_RATE_LIMIT_PER_MINUTE || '60', 10),
    maxMessagesPerHour: parseInt(process.env.SMS_RATE_LIMIT_PER_HOUR || '1000', 10),
    maxMessagesPerDay: parseInt(process.env.SMS_RATE_LIMIT_PER_DAY || '10000', 10),
    perUserLimitPerHour,
    perPhoneNumberLimitPerDay
}));

// Use Cases
container.bind<SendSmsUseCase>(TYPES.SendSmsUseCase).toDynamicValue((context) => {
    return new SendSmsUseCase(
        context.container.get<ISmsRepository>(TYPES.SmsRepository),
        context.container.get<ISmsProvider>(TYPES.SmsProvider),
        context.container.get<RateLimitPolicy>(TYPES.RateLimitPolicy),
        context.container.get<IEventPublisher>(TYPES.EventPublisher)
    );
});

container.bind<TrackDeliveryUseCase>(TYPES.TrackDeliveryUseCase).toDynamicValue((context) => {
    return new TrackDeliveryUseCase(
        context.container.get<ISmsRepository>(TYPES.SmsRepository)
    );
});

container.bind<HandleDeliveryReportUseCase>(TYPES.HandleDeliveryReportUseCase).toDynamicValue((context) => {
    return new HandleDeliveryReportUseCase(
        context.container.get<ISmsRepository>(TYPES.SmsRepository),
        context.container.get<ISmsProvider>(TYPES.SmsProvider)
    );
});

container.bind<RetryFailedMessagesUseCase>(TYPES.RetryFailedMessagesUseCase).toDynamicValue((context) => {
    return new RetryFailedMessagesUseCase(
        context.container.get<ISmsRepository>(TYPES.SmsRepository),
        context.container.get<ISmsProvider>(TYPES.SmsProvider),
        context.container.get<RetryPolicy>(TYPES.RetryPolicy),
        context.container.get<IEventPublisher>(TYPES.EventPublisher)
    );
});

container.bind<GetStatisticsUseCase>(TYPES.GetStatisticsUseCase).toDynamicValue((context) => {
    return new GetStatisticsUseCase(
        context.container.get<ISmsRepository>(TYPES.SmsRepository)
    );
});

// Controllers
container.bind<SmsController>(TYPES.SmsController).to(SmsController).inSingletonScope();

import { DomainEvent } from '../../domain/events/sms.events';
import { eventBus } from '@shared/events/eventBus';

/**
 * Event Publisher Interface
 */
export interface IEventPublisher {
    publish(eventType: string, payload: any): Promise<void>;
    publishBatch(events: DomainEvent[]): Promise<void>;
}

/**
 * Simple Event Publisher Implementation
 * Publishes events to an in-memory event bus or message queue
 */
export class EventPublisher implements IEventPublisher {
    constructor(private readonly logger?: any) { }

    async publish(eventType: string, payload: any): Promise<void> {
        try {
            await eventBus.publish(eventType, payload);

            if (this.logger && process.env.NODE_ENV !== 'test') {
                this.logger.info('Event published', {
                    eventType,
                    payload,
                    timestamp: new Date().toISOString()
                });
            }
        } catch (error) {
            if (this.logger) {
                this.logger.error('Failed to publish event', {
                    eventType,
                    error: error instanceof Error ? error.message : 'Unknown error'
                });
            }
            // Don't throw - event publishing failures shouldn't break the main flow
        }
    }

    async publishBatch(events: DomainEvent[]): Promise<void> {
        for (const event of events) {
            await this.publish(event.eventType, event.payload);
        }
    }
}

import { ISmsProvider } from './sms-provider.interface';
import { ProviderResponse } from '../../domain/value-objects/provider-response.value-object';

/**
 * Africa's Talking SMS Provider
 * Integration with Africa's Talking SMS API
 * https://developers.africastalking.com/docs/sms
 */
export class AfricasTalkingSmsProvider implements ISmsProvider {
    private readonly name = 'africastalking';
    private readonly username: string;
    private readonly apiKey: string;
    private readonly senderId?: string;
    private readonly baseUrl: string;
    private readonly bulkSMSMode?: number;
    private readonly enqueue?: number;
    private readonly keyword?: string;
    private readonly linkId?: string;
    private readonly retryDurationInHours?: number;
    private readonly isSandbox: boolean;

    private static readonly LIVE_BASE_URL = 'https://api.africastalking.com/version1';
    private static readonly SANDBOX_BASE_URL = 'https://api.sandbox.africastalking.com/version1';

    constructor(config: {
        username: string;
        apiKey: string;
        senderId?: string;
        environment?: 'live' | 'sandbox';
        baseUrl?: string;
        bulkSMSMode?: number;
        enqueue?: number;
        keyword?: string;
        linkId?: string;
        retryDurationInHours?: number;
    }) {
        this.username = config.username;
        this.apiKey = config.apiKey;
        this.senderId = config.senderId;
        this.bulkSMSMode = config.bulkSMSMode;
        this.enqueue = config.enqueue;
        this.keyword = config.keyword;
        this.linkId = config.linkId;
        this.retryDurationInHours = config.retryDurationInHours;
        this.isSandbox = config.environment === 'sandbox';
        const defaultBaseUrl = this.isSandbox
            ? AfricasTalkingSmsProvider.SANDBOX_BASE_URL
            : AfricasTalkingSmsProvider.LIVE_BASE_URL;
        this.baseUrl = (config.baseUrl || defaultBaseUrl).replace(/\/+$/, '');
    }

    async send(phoneNumber: string, message: string): Promise<ProviderResponse> {
        try {
            const urlencoded = new URLSearchParams();
            urlencoded.append('username', this.username);
            urlencoded.append('to', phoneNumber);
            urlencoded.append('message', message);
            if (this.senderId && !this.isSandbox) {
                urlencoded.append('from', this.senderId);
            }
            if (this.bulkSMSMode !== undefined) {
                urlencoded.append('bulkSMSMode', String(this.bulkSMSMode));
            }
            if (this.enqueue !== undefined) {
                urlencoded.append('enqueue', String(this.enqueue));
            }
            if (this.keyword) {
                urlencoded.append('keyword', this.keyword);
            }
            if (this.linkId) {
                urlencoded.append('linkId', this.linkId);
            }
            if (this.retryDurationInHours !== undefined) {
                urlencoded.append('retryDurationInHours', String(this.retryDurationInHours));
            }

            const response = await fetch(`${this.baseUrl}/messaging`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'apiKey': this.apiKey,
                    'Accept': 'application/json'
                },
                body: urlencoded
            });

            const raw = await response.text();
            let data: any = null;
            if (raw) {
                try {
                    data = JSON.parse(raw);
                } catch {
                    // Non-JSON response (XML or plain text)
                    data = this.tryParseXmlResponse(raw);
                }
            }

            if (!response.ok) {
                return ProviderResponse.createFailure(
                    (data && (data.message || data.error)) || raw || 'Africa\'s Talking API error',
                    response.status.toString()
                );
            }

            if (!data) {
                return ProviderResponse.createFailure(
                    raw || 'Africa\'s Talking API error',
                    response.status.toString()
                );
            }

            // Check if message was sent
            const recipients = data.SMSMessageData?.Recipients || [];
            if (recipients.length === 0) {
                const apiMessage = data.SMSMessageData?.Message || data.message || data.error;
                return ProviderResponse.createFailure(
                    apiMessage || 'No recipients processed',
                    '400'
                );
            }

            const recipient = recipients[0];

            const statusCode = Number(recipient.statusCode);
            const isSuccessCode = statusCode === 100 || statusCode === 101 || statusCode === 102;
            if (recipient.status === 'Success' || isSuccessCode) {
                return ProviderResponse.createSuccess(recipient.messageId, {
                    provider: this.name,
                    phoneNumber,
                    cost: recipient.cost,
                    statusCode: recipient.statusCode
                });
            } else {
                return ProviderResponse.createFailure(
                    recipient.status || 'Message rejected',
                    recipient.statusCode?.toString()
                );
            }
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : 'Unknown error';
            return ProviderResponse.createFailure(
                `Africa's Talking error: ${errorMessage}`,
                '500'
            );
        }
    }

    async getStatus(providerMessageId: string): Promise<ProviderResponse> {
        // Africa's Talking doesn't have a direct status query endpoint
        // Status updates come via delivery reports callback
        return ProviderResponse.create({
            providerMessageId,
            status: 'unknown',
            timestamp: new Date(),
            metadata: {
                note: 'Status delivered via callback'
            }
        });
    }

    getName(): string {
        return this.name;
    }

    async isHealthy(): Promise<boolean> {
        try {
            // Simple health check - try to fetch account balance
            const response = await fetch(`${this.baseUrl}/user?username=${this.username}`, {
                method: 'GET',
                headers: {
                    'apiKey': this.apiKey,
                    'Accept': 'application/json'
                }
            });

            return response.ok;
        } catch {
            return false;
        }
    }

    getConfig() {
        return {
            name: this.name,
            maxMessageLength: 1600,
            supportsDeliveryReports: true,
            supportsBatch: true
        };
    }

    private tryParseXmlResponse(xml: string): any | null {
        try {
            if (!xml.includes('<SMSMessageData')) {
                return null;
            }

            const getTagValue = (tag: string): string | undefined => {
                const match = new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`, 'i').exec(xml);
                return match?.[1]?.trim();
            };

            const status = getTagValue('status');
            const statusCodeRaw = getTagValue('statusCode');
            const messageId = getTagValue('messageId');
            const number = getTagValue('number');
            const cost = getTagValue('cost');

            if (!status && !statusCodeRaw) {
                return null;
            }

            const statusCode = statusCodeRaw ? Number(statusCodeRaw) : undefined;

            return {
                SMSMessageData: {
                    Message: getTagValue('Message'),
                    Recipients: [
                        {
                            cost,
                            messageId,
                            number,
                            status: status || 'Unknown',
                            statusCode
                        }
                    ]
                }
            };
        } catch {
            return null;
        }
    }

    /**
     * Handle delivery report callback
     * Should be called from webhook endpoint
     */
    parseDeliveryReport(body: any): {
        providerMessageId: string;
        status: 'delivered' | 'failed';
        phoneNumber: string;
        failureReason?: string;
    } | null {
        try {
            if (!body || typeof body !== 'object') {
                return null;
            }

            const providerMessageId = body.id;
            const providerStatus = body.status;
            const phoneNumber = body.phoneNumber;

            if (
                typeof providerMessageId !== 'string' || providerMessageId.length === 0 ||
                typeof providerStatus !== 'string' || providerStatus.length === 0 ||
                typeof phoneNumber !== 'string' || phoneNumber.length === 0
            ) {
                return null;
            }

            return {
                providerMessageId,
                status: providerStatus === 'Success' ? 'delivered' : 'failed',
                phoneNumber,
                failureReason: body.failureReason
            };
        } catch {
            return null;
        }
    }
}

import { ISmsProvider } from './sms-provider.interface';
import { ProviderResponse } from '../../domain/value-objects/provider-response.value-object';

/**
 * Mock SMS Provider
 * Simulates SMS sending for local/dev without external API calls.
 */
export class MockSmsProvider implements ISmsProvider {
    private readonly name = 'mock';
    private readonly sentMessages: Map<string, any> = new Map();
    private shouldFail: boolean = false;
    private failureRate: number = 0;

    constructor(options?: { shouldFail?: boolean; failureRate?: number }) {
        this.shouldFail = options?.shouldFail ?? false;
        this.failureRate = options?.failureRate ?? 0;
    }

    async send(phoneNumber: string, message: string): Promise<ProviderResponse> {
        await this.delay(100);

        if (this.shouldFail || Math.random() < this.failureRate) {
            return ProviderResponse.createFailure(
                'Mock provider: Simulated failure',
                '500'
            );
        }

        const providerMessageId = `mock-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

        this.sentMessages.set(providerMessageId, {
            phoneNumber,
            message,
            sentAt: new Date(),
            status: 'sent'
        });

        if (process.env.NODE_ENV !== 'test') {
            console.log(`[MockSmsProvider] Sent SMS to ${phoneNumber}: ${message.substring(0, 50)}...`);
        }

        return ProviderResponse.createSuccess(providerMessageId, {
            provider: this.name,
            phoneNumber,
            messageLength: message.length
        });
    }

    async getStatus(providerMessageId: string): Promise<ProviderResponse> {
        await this.delay(50);

        const message = this.sentMessages.get(providerMessageId);

        if (!message) {
            return ProviderResponse.createFailure(`Message not found: ${providerMessageId}`, '404');
        }

        const sentAt = message.sentAt.getTime();
        const now = Date.now();
        const delivered = now - sentAt > 1000;

        return ProviderResponse.create({
            providerMessageId,
            status: delivered ? 'delivered' : 'queued',
            timestamp: new Date(),
            metadata: { message }
        });
    }

    getName(): string {
        return this.name;
    }

    async isHealthy(): Promise<boolean> {
        return true;
    }

    getConfig() {
        return {
            name: this.name,
            maxMessageLength: 1600,
            supportsDeliveryReports: true,
            supportsBatch: true
        };
    }

    getSentMessages(): Map<string, any> {
        return new Map(this.sentMessages);
    }

    clearSentMessages(): void {
        this.sentMessages.clear();
    }

    setShouldFail(shouldFail: boolean): void {
        this.shouldFail = shouldFail;
    }

    setFailureRate(rate: number): void {
        this.failureRate = Math.max(0, Math.min(1, rate));
    }

    simulateDelivery(providerMessageId: string): void {
        const message = this.sentMessages.get(providerMessageId);
        if (message) {
            message.status = 'delivered';
            message.deliveredAt = new Date();
        }
    }

    private delay(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}

import { ISmsRepository } from '../../domain/repositories/sms.repository';
import { SmsMessage, SmsStatus } from '../../domain/entities/sms-message.entity';
import { PrismaClient, Sms_Message, Sms_Status } from '@prisma/client';
import { PhoneNumber } from '../../domain/value-objects/phone-number.value-object';
import { MessageContent } from '../../domain/value-objects/message-content.value-object';

/**
 * Prisma SMS Repository
 * Infrastructure implementation of ISmsRepository
 */
export class PrismaSmsRepository implements ISmsRepository {
    constructor(private readonly prisma: PrismaClient) { }

    private warnedFallback = false;

    private warnFallback(message: string): void {
        if (this.warnedFallback) return;
        this.warnedFallback = true;
        console.warn(message);
    }

    async create(message: SmsMessage): Promise<SmsMessage> {
        const data = this.toPrismaModel(message);

        const created = await this.prisma.sms_Message.create({
            data
        });

        return this.toDomainEntity(created);
    }

    async findById(id: string): Promise<SmsMessage | null> {
        try {
            const message = await this.prisma.sms_Message.findUnique({
                where: { id }
            });

            return message ? this.toDomainEntity(message) : null;
        } catch (error) {
            if (process.env.NODE_ENV !== 'production') {
                this.warnFallback('[sms] Prisma lookup failed; returning not-found fallback.');
                return null;
            }
            throw error;
        }
    }

    async findByStatus(status: SmsStatus, limit: number = 100): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: { status: this.toSmsStatus(status) },
            take: limit,
            orderBy: { createdAt: 'desc' }
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async findByUserId(userId: string, limit: number = 100): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: { userId },
            take: limit,
            orderBy: { createdAt: 'desc' }
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async findByPhoneNumber(phoneNumber: string, limit: number = 100): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: { phoneNumber },
            take: limit,
            orderBy: { createdAt: 'desc' }
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async findFailedMessagesForRetry(maxRetries: number): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: {
                status: Sms_Status.FAILED,
                retryCount: { lt: maxRetries }
            },
            orderBy: { failedAt: 'asc' },
            take: 100
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async update(message: SmsMessage): Promise<SmsMessage> {
        const data = this.toPrismaModel(message);

        const updated = await this.prisma.sms_Message.update({
            where: { id: message.getId() },
            data
        });

        return this.toDomainEntity(updated);
    }

    async delete(id: string): Promise<void> {
        await this.prisma.sms_Message.delete({
            where: { id }
        });
    }

    async getMessageCountInWindow(
        startTime: Date,
        endTime: Date,
        filters?: {
            userId?: string;
            phoneNumber?: string;
            status?: SmsStatus[];
        }
    ): Promise<number> {
        const where: any = {
            createdAt: {
                gte: startTime,
                lte: endTime
            }
        };

        if (filters?.userId) {
            where.userId = filters.userId;
        }

        if (filters?.phoneNumber) {
            where.phoneNumber = filters.phoneNumber;
        }

        if (filters?.status && filters.status.length > 0) {
            where.status = {
                in: filters.status.map(s => this.toSmsStatus(s))
            };
        }

        return await this.prisma.sms_Message.count({ where });
    }

    async getMessagesToPhoneNumberInWindow(
        phoneNumber: string,
        startTime: Date,
        endTime: Date
    ): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: {
                phoneNumber,
                createdAt: {
                    gte: startTime,
                    lte: endTime
                }
            },
            orderBy: { createdAt: 'desc' }
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async getMessagesByUserInWindow(
        userId: string,
        startTime: Date,
        endTime: Date
    ): Promise<SmsMessage[]> {
        const messages = await this.prisma.sms_Message.findMany({
            where: {
                userId,
                createdAt: {
                    gte: startTime,
                    lte: endTime
                }
            },
            orderBy: { createdAt: 'desc' }
        });

        return messages.map(msg => this.toDomainEntity(msg));
    }

    async findByProviderMessageId(
        providerId: string,
        providerMessageId: string
    ): Promise<SmsMessage | null> {
        const message = await this.prisma.sms_Message.findFirst({
            where: {
                providerId,
                providerMessageId
            }
        });

        return message ? this.toDomainEntity(message) : null;
    }

    async getStatistics(
        startTime: Date,
        endTime: Date
    ): Promise<{
        total: number;
        queued: number;
        sending: number;
        sent: number;
        delivered: number;
        failed: number;
        cancelled: number;
        undelivered: number;
    }> {
        const where = {
            createdAt: {
                gte: startTime,
                lte: endTime
            }
        };

        const [
            total,
            queued,
            sending,
            sent,
            delivered,
            failed,
            cancelled,
            undelivered
        ] = await Promise.all([
            this.prisma.sms_Message.count({ where }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.QUEUED } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.SENDING } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.SENT } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.DELIVERED } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.FAILED } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.CANCELLED } }),
            this.prisma.sms_Message.count({ where: { ...where, status: Sms_Status.UNDELIVERED } })
        ]);

        return {
            total,
            queued,
            sending,
            sent,
            delivered,
            failed,
            cancelled,
            undelivered
        };
    }

    async deleteOlderThan(date: Date): Promise<number> {
        const result = await this.prisma.sms_Message.deleteMany({
            where: {
                createdAt: {
                    lt: date
                },
                status: {
                    in: [Sms_Status.DELIVERED, Sms_Status.UNDELIVERED, Sms_Status.CANCELLED]
                }
            }
        });

        return result.count;
    }

    // ==================== Mapping Methods ====================

    private toPrismaModel(message: SmsMessage): any {
        return {
            id: message.getId(),
            phoneNumber: message.getPhoneNumber().getValue(),
            content: message.getContent().getValue(),
            status: this.toSmsStatus(message.getStatus()),
            providerId: message.getProviderId() || null,
            providerMessageId: message.getProviderMessageId() || null,
            userId: message.getUserId() || null,
            retryCount: message.getRetryCount(),
            maxRetries: message.getMaxRetries(),
            scheduledAt: message.getScheduledAt() || null,
            sentAt: message.getSentAt() || null,
            deliveredAt: message.getDeliveredAt() || null,
            failedAt: message.getFailedAt() || null,
            lastError: message.getLastError() || null,
            metadata: message.getMetadata() || null,
            createdAt: message.getCreatedAt(),
            updatedAt: message.getUpdatedAt()
        };
    }

    private toDomainEntity(prismaModel: Sms_Message): SmsMessage {
        return SmsMessage.reconstitute({
            id: prismaModel.id,
            phoneNumber: prismaModel.phoneNumber,
            content: prismaModel.content,
            status: this.toDomainStatus(prismaModel.status),
            providerId: prismaModel.providerId || undefined,
            providerMessageId: prismaModel.providerMessageId || undefined,
            userId: prismaModel.userId || undefined,
            retryCount: prismaModel.retryCount,
            maxRetries: prismaModel.maxRetries,
            scheduledAt: prismaModel.scheduledAt || undefined,
            sentAt: prismaModel.sentAt || undefined,
            deliveredAt: prismaModel.deliveredAt || undefined,
            failedAt: prismaModel.failedAt || undefined,
            lastError: prismaModel.lastError || undefined,
            metadata: (prismaModel.metadata as Record<string, any>) || undefined,
            createdAt: prismaModel.createdAt,
            updatedAt: prismaModel.updatedAt
        });
    }

    private toSmsStatus(status: SmsStatus): Sms_Status {
        return status as unknown as Sms_Status;
    }

    private toDomainStatus(status: Sms_Status): SmsStatus {
        return status as unknown as SmsStatus;
    }
}

/**
 * Cache Engine (order-service domain utility)
 * In-memory cache kept inside the domain boundary to avoid outward dependencies.
 */

export interface CacheGetResult<T = any> {
    hit: boolean;
    value: T | null;
}

interface CacheEntry<T = any> {
    value: T;
    expiresAt: number;
}

export class CacheEngine {
    private readonly store = new Map<string, CacheEntry>();

    /**
     * Retrieves a cached entry.
     * Returns `{ hit: true, value }` on cache hit and `{ hit: false, value: null }` on miss.
     */
    async get<T = any>(key: string): Promise<CacheGetResult<T>> {
        const entry = this.store.get(key);
        if (!entry) {
            return { hit: false, value: null };
        }

        if (entry.expiresAt <= Date.now()) {
            this.store.delete(key);
            return { hit: false, value: null };
        }

        return { hit: true, value: entry.value as T };
    }

    /**
     * Stores a value with an optional TTL in seconds (default: 300 s).
     */
    async set<T = any>(key: string, value: T, ttlSeconds = 300): Promise<boolean> {
        if (ttlSeconds <= 0) {
            this.store.delete(key);
            return true;
        }

        this.store.set(key, {
            value,
            expiresAt: Date.now() + ttlSeconds * 1000,
        });

        return true;
    }

    /**
     * Deletes a single cache entry.
     */
    async delete(key: string): Promise<boolean> {
        return this.store.delete(key);
    }

    /**
     * Clears all cached entries.
     */
    async clear(): Promise<void> {
        this.store.clear();
    }
}

import { Order } from '../entities/order.entity';

export interface EligibilityResult {
    eligible: boolean;
    reason?: string;
}

export interface IAuthServiceClient {
    isUserVerified(userId: string): Promise<boolean>;
}

export interface IUserServiceClient {
    getCODReputation(userId: string): Promise<{
        score: number;
        successfulOrders: number;
        suspendedUntil?: Date;
        permanentlyDisabled?: boolean;
    }>;
}

export interface ILogisticsServiceClient {
    isCODSupportedInArea(address: any): Promise<boolean>;
    isCrossRegionDelivery(address: any, sellerAddress: any): Promise<boolean>;
}

export class CODEligibilityEngine {
    private readonly MIN_REPUTATION_SCORE = 50;
    private readonly MIN_SUCCESSFUL_ORDERS = 3;
    private readonly MIN_COD_AMOUNT = 1000;
    private readonly MAX_COD_AMOUNT = 500000;

    constructor(
        private readonly authService: IAuthServiceClient,
        private readonly userService: IUserServiceClient,
        private readonly logisticsService: ILogisticsServiceClient
    ) { }

    async checkBuyerEligibility(buyerId: string): Promise<EligibilityResult> {
        const [isVerified, reputation] = await Promise.all([
            this.authService.isUserVerified(buyerId),
            this.userService.getCODReputation(buyerId)
        ]);

        if (!isVerified) {
            return { eligible: false, reason: 'Buyer must be identity verified for COD' };
        }

        if (reputation.permanentlyDisabled) {
            return { eligible: false, reason: 'COD has been permanently disabled for this account' };
        }

        if (reputation.suspendedUntil && reputation.suspendedUntil > new Date()) {
            return { eligible: false, reason: `COD access is suspended until ${reputation.suspendedUntil.toISOString()}` };
        }

        if (reputation.score < this.MIN_REPUTATION_SCORE) {
            return { eligible: false, reason: `COD reputation score (${reputation.score}) is below required minimum of ${this.MIN_REPUTATION_SCORE}` };
        }

        if (reputation.successfulOrders < this.MIN_SUCCESSFUL_ORDERS) {
            return { eligible: false, reason: `Buyer must have at least ${this.MIN_SUCCESSFUL_ORDERS} successful orders to unlock COD privilege` };
        }

        return { eligible: true };
    }

    async checkSellerEligibility(sellerId: string): Promise<EligibilityResult> {
        // In a real system, we'd check if the seller is verified and has enabled COD
        // For now, assume all verified sellers support COD
        const isVerified = await this.authService.isUserVerified(sellerId);
        if (!isVerified) {
            return { eligible: false, reason: 'Seller must be verified to accept COD' };
        }
        return { eligible: true };
    }

    async checkOrderEligibility(order: Order, sellerAddress: any): Promise<EligibilityResult> {
        const amount = Number(order.totalAmount);
        if (amount < this.MIN_COD_AMOUNT || amount > this.MAX_COD_AMOUNT) {
            return {
                eligible: false,
                reason: `Order amount must be between ${this.MIN_COD_AMOUNT} and ${this.MAX_COD_AMOUNT} TZS for COD`
            };
        }

        const isSupportedArea = await this.logisticsService.isCODSupportedInArea(order.deliveryAddress);
        if (!isSupportedArea) {
            return { eligible: false, reason: 'COD is not supported in the selected delivery area' };
        }

        const isCrossRegion = await this.logisticsService.isCrossRegionDelivery(order.deliveryAddress, sellerAddress);
        if (isCrossRegion) {
            return { eligible: false, reason: 'COD is not available for cross-region deliveries' };
        }

        // High-risk SKU check (placeholder logic)
        const hasHighRiskSKU = order.items.some(item => this.isHighRiskSKU(item.productId));
        if (hasHighRiskSKU) {
            return { eligible: false, reason: 'Order contains high-risk items ineligible for COD' };
        }

        return { eligible: true };
    }

    calculateCommitmentFee(orderAmount: number): number {
        // 5% of order value, min 5,000 TZS
        const percentageFee = orderAmount * 0.05;
        return Math.max(percentageFee, 5000);
    }

    private isHighRiskSKU(_productId: string): boolean {
        // Placeholder for high-risk item detection logic
        // e.g. certain electronics, high-value jewelry, etc.
        return false;
    }
}

import { InventoryEngine, InventoryInput, InventoryOutput } from './inventory.engine';

export interface InventoryRequest {
  operation: 'check' | 'reserve' | 'allocate' | 'release' | 'transfer' | 'adjust';
  productId: string;
  variantId?: string;
  quantity: number;
  warehouseId: string;
  customerId?: string;
  orderId?: string;
  reason?: string;
  batchId?: string;
  metadata?: Record<string, any>;
}

export interface InventoryResult {
  success: boolean;
  accuracy: number;
  processingTime: number;
  inventory: InventoryOutput | null;
  validation: InventoryValidation;
  optimization: OptimizationResult;
  monitoring: InventoryMonitoring;
  recommendations: string[];
}

export interface InventoryValidation {
  passed: boolean;
  score: number;
  checks: ValidationCheck[];
  criticalIssues: string[];
  warnings: string[];
}

export interface ValidationCheck {
  name: string;
  passed: boolean;
  score: number;
  details: string;
}

export interface OptimizationResult {
  allocationScore: number;
  warehouseOptimization: number;
  reservationEfficiency: number;
  stockUtilization: number;
  suggestions: string[];
}

export interface InventoryMonitoring {
  performanceMetrics: InventoryPerformanceMetrics;
  stockHealth: StockHealthIndicators;
  systemMetrics: SystemMetrics;
  alerts: InventoryAlert[];
}

export interface InventoryPerformanceMetrics {
  responseTime: number;
  throughput: number;
  accuracyRate: number;
  reservationSuccessRate: number;
  stockoutRate: number;
}

export interface StockHealthIndicators {
  stockAccuracy: number;
  turnoverRate: number;
  stockoutFrequency: number;
  overstockPercentage: number;
  demandForecastAccuracy: number;
}

export interface SystemMetrics {
  cacheHitRate: number;
  databaseResponseTime: number;
  concurrentOperations: number;
  errorRate: number;
}

export interface InventoryAlert {
  type: 'stockout' | 'low_stock' | 'overstock' | 'accuracy' | 'system';
  severity: 'low' | 'medium' | 'high' | 'critical';
  message: string;
  productId?: string;
  warehouseId?: string;
  timestamp: Date;
}

export class InventoryOrchestrator {
  private readonly ACCURACY_TARGET = 99.8;
  private readonly MAX_RESPONSE_TIME = 150; // ms
  private readonly VALIDATION_THRESHOLD = 95;
  
  private inventoryEngine: InventoryEngine;
  private performanceMonitor: InventoryPerformanceMonitor;
  private optimizationEngine: InventoryOptimizationEngine;

  constructor() {
    this.inventoryEngine = new InventoryEngine();
    this.performanceMonitor = new InventoryPerformanceMonitor();
    this.optimizationEngine = new InventoryOptimizationEngine();
  }

  async processInventoryRequest(request: InventoryRequest): Promise<InventoryResult> {
    const startTime = Date.now();
    
    try {
      // Pre-processing validation
      const preValidation = await this.validateRequest(request);
      if (!preValidation.passed) {
        throw new Error(`Request validation failed: ${preValidation.criticalIssues.join(', ')}`);
      }

      // Convert request to engine input
      const inventoryInput = this.convertToInventoryInput(request);

      // Process through inventory engine
      const inventoryOutput = await this.inventoryEngine.processInventoryRequest(inventoryInput);

      if (!inventoryOutput.success) {
        throw new Error('Inventory processing failed');
      }

      // Post-processing validation
      const postValidation = await this.validateOutput(inventoryOutput, request);
      
      // Optimization analysis
      const optimization = await this.optimizationEngine.analyzeOptimization(
        inventoryOutput,
        request
      );

      // Performance monitoring
      const monitoring = await this.performanceMonitor.collectMetrics(
        startTime,
        inventoryOutput,
        request
      );

      // Generate recommendations
      const recommendations = await this.generateRecommendations(
        inventoryOutput,
        optimization,
        monitoring
      );

      const processingTime = Date.now() - startTime;
      const accuracy = Math.min(inventoryOutput.confidence, postValidation.score);

      return {
        success: true,
        accuracy,
        processingTime,
        inventory: inventoryOutput,
        validation: postValidation,
        optimization,
        monitoring,
        recommendations
      };

    } catch (error: any) {
      const processingTime = Date.now() - startTime;
      
      return {
        success: false,
        accuracy: 0,
        processingTime,
        inventory: null,
        validation: { passed: false, score: 0, checks: [], criticalIssues: [error.message], warnings: [] },
        optimization: { allocationScore: 0, warehouseOptimization: 0, reservationEfficiency: 0, stockUtilization: 0, suggestions: [] },
        monitoring: await this.performanceMonitor.collectErrorMetrics(startTime, error),
        recommendations: ['Review inventory data', 'Check system connectivity', 'Validate input parameters']
      };
    }
  }

  private async validateRequest(request: InventoryRequest): Promise<InventoryValidation> {
    const checks: ValidationCheck[] = [];
    const criticalIssues: string[] = [];
    const warnings: string[] = [];

    // Operation validation
    const operationCheck = this.validateOperation(request.operation);
    checks.push(operationCheck);
    if (!operationCheck.passed) criticalIssues.push(operationCheck.details);

    // Product validation
    const productCheck = this.validateProduct(request.productId, request.variantId);
    checks.push(productCheck);
    if (!productCheck.passed) criticalIssues.push(productCheck.details);

    // Quantity validation
    const quantityCheck = this.validateQuantity(request.quantity);
    checks.push(quantityCheck);
    if (!quantityCheck.passed) criticalIssues.push(quantityCheck.details);

    // Warehouse validation
    const warehouseCheck = this.validateWarehouse(request.warehouseId);
    checks.push(warehouseCheck);
    if (!warehouseCheck.passed) criticalIssues.push(warehouseCheck.details);

    const overallScore = checks.reduce((sum, check) => sum + check.score, 0) / checks.length;
    const passed = criticalIssues.length === 0 && overallScore >= this.VALIDATION_THRESHOLD;

    return {
      passed,
      score: overallScore,
      checks,
      criticalIssues,
      warnings
    };
  }

  private async validateOutput(output: InventoryOutput, request: InventoryRequest): Promise<InventoryValidation> {
    const checks: ValidationCheck[] = [];
    const criticalIssues: string[] = [];
    const warnings: string[] = [];

    // Confidence validation
    if (output.confidence < this.ACCURACY_TARGET) {
      criticalIssues.push(`Confidence ${output.confidence}% below target ${this.ACCURACY_TARGET}%`);
    }

    // Stock consistency validation
    const consistencyCheck = this.validateStockConsistency(output);
    checks.push(consistencyCheck);
    if (!consistencyCheck.passed) warnings.push(consistencyCheck.details);

    // Reservation validation
    if (request.operation === 'reserve' && !output.reservationId) {
      criticalIssues.push('Reservation failed to create reservation ID');
    }

    const overallScore = checks.reduce((sum, check) => sum + check.score, 0) / Math.max(checks.length, 1);
    const passed = criticalIssues.length === 0;

    return {
      passed,
      score: overallScore,
      checks,
      criticalIssues,
      warnings
    };
  }

  private convertToInventoryInput(request: InventoryRequest): InventoryInput {
    return {
      productId: request.productId,
      variantId: request.variantId,
      quantity: request.quantity,
      warehouseId: request.warehouseId,
      reservationType: this.mapOperationToReservationType(request.operation),
      customerId: request.customerId,
      orderId: request.orderId,
      priority: 'normal',
      batchId: request.batchId
    };
  }

  private mapOperationToReservationType(operation: string): 'order' | 'cart' | 'quote' | 'allocation' {
    const mapping: Record<string, 'order' | 'cart' | 'quote' | 'allocation'> = {
      'check': 'quote',
      'reserve': 'cart',
      'allocate': 'allocation',
      'release': 'cart',
      'transfer': 'allocation',
      'adjust': 'allocation'
    };
    return mapping[operation] || 'quote';
  }

  private async generateRecommendations(
    output: InventoryOutput,
    optimization: OptimizationResult,
    monitoring: InventoryMonitoring
  ): Promise<string[]> {
    const recommendations: string[] = [];

    // Stock level recommendations
    if (output.stockStatus.level === 'low_stock') {
      recommendations.push('Initiate emergency reorder process');
    }

    // Optimization recommendations
    if (optimization.allocationScore < 0.8) {
      recommendations.push('Review warehouse allocation strategy');
    }

    // Performance recommendations
    if (monitoring.performanceMetrics.responseTime > this.MAX_RESPONSE_TIME) {
      recommendations.push('Optimize database queries for better performance');
    }

    // Accuracy recommendations
    if (output.confidence < 95) {
      recommendations.push('Schedule inventory accuracy audit');
    }

    return recommendations;
  }

  // Validation helper methods
  private validateOperation(operation: string): ValidationCheck {
    const validOperations = ['check', 'reserve', 'allocate', 'release', 'transfer', 'adjust'];
    const isValid = validOperations.includes(operation);
    return {
      name: 'Operation Validation',
      passed: isValid,
      score: isValid ? 100 : 0,
      details: isValid ? 'Valid operation' : 'Invalid operation type'
    };
  }

  private validateProduct(productId: string, variantId?: string): ValidationCheck {
    const isValid = Boolean(productId && productId.length > 0);
    return {
      name: 'Product Validation',
      passed: isValid,
      score: isValid ? 100 : 0,
      details: isValid ? 'Valid product ID' : 'Invalid or missing product ID'
    };
  }

  private validateQuantity(quantity: number): ValidationCheck {
    const isValid = quantity > 0 && quantity <= 10000;
    return {
      name: 'Quantity Validation',
      passed: isValid,
      score: isValid ? 100 : 0,
      details: isValid ? 'Valid quantity' : 'Quantity must be between 1 and 10000'
    };
  }

  private validateWarehouse(warehouseId: string): ValidationCheck {
    const isValid = Boolean(warehouseId && warehouseId.length > 0);
    return {
      name: 'Warehouse Validation',
      passed: isValid,
      score: isValid ? 100 : 0,
      details: isValid ? 'Valid warehouse ID' : 'Invalid or missing warehouse ID'
    };
  }

  private validateStockConsistency(output: InventoryOutput): ValidationCheck {
    const totalStock = output.available + output.reserved + output.allocated;
    const isConsistent = totalStock >= 0;
    return {
      name: 'Stock Consistency Validation',
      passed: isConsistent,
      score: isConsistent ? 100 : 0,
      details: isConsistent ? 'Stock levels are consistent' : 'Stock level inconsistency detected'
    };
  }
}

