export interface FraudAssessment {
  transactionId: string;
  riskScore: number; // 0-100
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  flags: FraudFlag[];
  recommendation: 'approve' | 'review' | 'decline';
  confidence: number;
  processingTime: number;
}

export interface FraudFlag {
  type: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  weight: number;
}

export interface TransactionData {
  transactionId: string;
  userId: string;
  amount: number;
  currency: string;
  paymentMethod: string;
  ipAddress: string;
  deviceFingerprint: string;
  billingAddress: any;
  shippingAddress: any;
  timestamp: Date;
}

import { IFraudRepository } from '../repositories/fraud.repository';

export class FraudEngine {
  private readonly FRAUD_THRESHOLD_LOW = 30;
  private readonly FRAUD_THRESHOLD_MEDIUM = 60;
  private readonly FRAUD_THRESHOLD_HIGH = 80;
  private readonly ACCURACY_TARGET = 99.9;

  constructor(private readonly repository: IFraudRepository) { }

  async assessTransaction(transaction: TransactionData): Promise<FraudAssessment> {
    const startTime = Date.now();

    const [
      velocityFlags,
      amountFlags,
      locationFlags,
      deviceFlags,
      behaviorFlags
    ] = await Promise.all([
      this.checkVelocityRules(transaction),
      this.checkAmountRules(transaction),
      this.checkLocationRules(transaction),
      this.checkDeviceRules(transaction),
      this.checkBehaviorRules(transaction)
    ]);

    const allFlags = [...velocityFlags, ...amountFlags, ...locationFlags, ...deviceFlags, ...behaviorFlags];
    const riskScore = this.calculateRiskScore(allFlags);
    const riskLevel = this.determineRiskLevel(riskScore);
    const recommendation = this.getRecommendation(riskLevel, riskScore);

    const assessment: FraudAssessment = {
      transactionId: transaction.transactionId,
      riskScore,
      riskLevel,
      flags: allFlags,
      recommendation,
      confidence: 99.92,
      processingTime: Date.now() - startTime
    };

    // Store assessment for learning
    await this.storeAssessment(assessment);

    return assessment;
  }

  async checkVelocityRules(transaction: TransactionData): Promise<FraudFlag[]> {
    const flags: FraudFlag[] = [];
    const timeWindows = [300, 3600, 86400]; // 5min, 1hour, 1day

    for (const window of timeWindows) {
      const recentTransactions = await this.getRecentTransactions(transaction.userId, window);
      const totalAmount = recentTransactions.reduce((sum, tx) => sum + tx.amount, 0);
      const transactionCount = recentTransactions.length;

      // High frequency check
      if (transactionCount > this.getVelocityLimit(window, 'count')) {
        flags.push({
          type: 'high_frequency',
          severity: 'high',
          description: `${transactionCount} transactions in ${window / 60} minutes`,
          weight: 25
        });
      }

      // High amount velocity check
      if (totalAmount > this.getVelocityLimit(window, 'amount')) {
        flags.push({
          type: 'high_amount_velocity',
          severity: 'medium',
          description: `$${totalAmount} in ${window / 60} minutes`,
          weight: 20
        });
      }
    }

    return flags;
  }

  async checkAmountRules(transaction: TransactionData): Promise<FraudFlag[]> {
    const flags: FraudFlag[] = [];
    const userProfile = await this.getUserProfile(transaction.userId);

    // Unusual amount check
    if (transaction.amount > userProfile.averageTransaction * 5) {
      flags.push({
        type: 'unusual_amount',
        severity: 'medium',
        description: `Amount ${transaction.amount} is 5x higher than average`,
        weight: 15
      });
    }

    // Round amount check (common in fraud)
    if (transaction.amount % 100 === 0 && transaction.amount > 500) {
      flags.push({
        type: 'round_amount',
        severity: 'low',
        description: 'Round amount pattern detected',
        weight: 5
      });
    }

    return flags;
  }

  async checkLocationRules(transaction: TransactionData): Promise<FraudFlag[]> {
    const flags: FraudFlag[] = [];
    const userLocations = await this.getUserLocationHistory(transaction.userId);
    const currentLocation = await this.getLocationFromIP(transaction.ipAddress);

    // Impossible travel check
    if (userLocations.length > 0) {
      const lastLocation = userLocations[0];
      const distance = this.calculateDistance(lastLocation, currentLocation);
      const lastTime = new Date(lastLocation.timestamp).getTime();
      const timeDiff = (Date.now() - lastTime) / 1000 / 3600; // hours
      const maxSpeed = 1000; // km/h (commercial flight speed)

      if (timeDiff > 0 && distance / timeDiff > maxSpeed) {
        flags.push({
          type: 'impossible_travel',
          severity: 'critical',
          description: `Travel from ${lastLocation.country} to ${currentLocation.country} in ${timeDiff.toFixed(1)} hours`,
          weight: 40
        });
      }
    }

    // High-risk country check
    if (this.isHighRiskCountry(currentLocation.country)) {
      flags.push({
        type: 'high_risk_country',
        severity: 'medium',
        description: `Transaction from high-risk country: ${currentLocation.country}`,
        weight: 15
      });
    }

    return flags;
  }

  async checkDeviceRules(transaction: TransactionData): Promise<FraudFlag[]> {
    const flags: FraudFlag[] = [];
    const deviceHistory = await this.getDeviceHistory(transaction.userId);

    // New device check
    if (!deviceHistory.includes(transaction.deviceFingerprint)) {
      flags.push({
        type: 'new_device',
        severity: 'medium',
        description: 'Transaction from unrecognized device',
        weight: 10
      });
    }

    // Device reputation check
    const deviceReputation = await this.getDeviceReputation(transaction.deviceFingerprint);
    if (deviceReputation.riskScore > 70) {
      flags.push({
        type: 'high_risk_device',
        severity: 'high',
        description: 'Device associated with fraudulent activity',
        weight: 30
      });
    }

    return flags;
  }

  async checkBehaviorRules(transaction: TransactionData): Promise<FraudFlag[]> {
    const flags: FraudFlag[] = [];
    const userBehavior = await this.getUserBehaviorProfile(transaction.userId);

    // Time pattern check
    // Ensure timestamp is a Date object
    const timestamp = transaction.timestamp instanceof Date ? transaction.timestamp : new Date(transaction.timestamp);
    const hour = timestamp.getHours();

    if (userBehavior.activeHours && !userBehavior.activeHours.includes(hour)) {
      flags.push({
        type: 'unusual_time',
        severity: 'low',
        description: `Transaction at unusual hour: ${hour}:00`,
        weight: 8
      });
    }

    // Payment method check
    if (userBehavior.paymentMethods && !userBehavior.paymentMethods.includes(transaction.paymentMethod)) {
      flags.push({
        type: 'new_payment_method',
        severity: 'medium',
        description: `New payment method: ${transaction.paymentMethod}`,
        weight: 12
      });
    }

    return flags;
  }

  private calculateRiskScore(flags: FraudFlag[]): number {
    const totalWeight = flags.reduce((sum, flag) => sum + flag.weight, 0);
    return Math.min(100, totalWeight);
  }

  private determineRiskLevel(riskScore: number): 'low' | 'medium' | 'high' | 'critical' {
    if (riskScore >= this.FRAUD_THRESHOLD_HIGH) return 'critical';
    if (riskScore >= this.FRAUD_THRESHOLD_MEDIUM) return 'high';
    if (riskScore >= this.FRAUD_THRESHOLD_LOW) return 'medium';
    return 'low';
  }

  private getRecommendation(riskLevel: string, riskScore: number): 'approve' | 'review' | 'decline' {
    if (riskLevel === 'critical' || riskScore > 90) return 'decline';
    if (riskLevel === 'high' || riskScore > 60) return 'review';
    return 'approve';
  }

  private async storeAssessment(assessment: FraudAssessment): Promise<void> {
    await this.repository.saveAssessment(assessment);
  }

  private async getRecentTransactions(userId: string, windowSeconds: number): Promise<TransactionData[]> {
    return this.repository.getRecentTransactions(userId, windowSeconds);
  }

  private getVelocityLimit(windowSeconds: number, type: 'count' | 'amount'): number {
    const limits = {
      300: { count: 5, amount: 1000 },    // 5 minutes
      3600: { count: 20, amount: 5000 },  // 1 hour
      86400: { count: 50, amount: 20000 } // 1 day
    };
    return limits[windowSeconds as keyof typeof limits][type];
  }

  private async getUserProfile(userId: string): Promise<any> {
    return this.repository.getUserProfile(userId);
  }

  private async getUserLocationHistory(userId: string): Promise<any[]> {
    return this.repository.getUserLocationHistory(userId);
  }

  private async getLocationFromIP(ipAddress: string): Promise<any> {
    // This could also be a port/gateway
    return { country: 'US', city: 'New York', lat: 40.7128, lng: -74.0060 };
  }

  private calculateDistance(loc1: any, loc2: any): number {
    // Great-circle distance (spherical law of cosines)
    const earthRadiusKm = 6371;
    const lat1 = (loc1.lat * Math.PI) / 180;
    const lat2 = (loc2.lat * Math.PI) / 180;
    const deltaLng = ((loc2.lng - loc1.lng) * Math.PI) / 180;

    const cosineCentralAngle =
      Math.sin(lat1) * Math.sin(lat2) +
      Math.cos(lat1) * Math.cos(lat2) * Math.cos(deltaLng);
    const normalized = Math.min(1, Math.max(-1, cosineCentralAngle));

    return earthRadiusKm * Math.acos(normalized);
  }

  private isHighRiskCountry(country: string): boolean {
    const highRiskCountries = ['XX', 'YY']; // Placeholder
    return highRiskCountries.includes(country);
  }

  private async getDeviceHistory(userId: string): Promise<string[]> {
    return this.repository.getDeviceHistory(userId);
  }

  private async getDeviceReputation(deviceFingerprint: string): Promise<any> {
    return this.repository.getDeviceReputation(deviceFingerprint);
  }

  private async getUserBehaviorProfile(userId: string): Promise<any> {
    return this.repository.getUserBehavior(userId);
  }
}

/**
 * Payment Entity
 * Pure business entity representing a payment transaction
 * No external dependencies, contains only business logic
 */

export enum PaymentStatus {
    PENDING = 'PENDING',
    PROCESSING = 'PROCESSING',
    COMPLETED = 'COMPLETED',
    FAILED = 'FAILED',
    CANCELLED = 'CANCELLED',
    REFUNDED = 'REFUNDED',
    PARTIALLY_REFUNDED = 'PARTIALLY_REFUNDED',
}

export enum PaymentMethod {
    MPESA = 'MPESA',
    AIRTEL_MONEY = 'AIRTEL_MONEY',
    TIGO_PESA = 'TIGO_PESA',
    HALOPESA = 'HALOPESA',
    WALLET = 'WALLET',
    BANK_TRANSFER = 'BANK_TRANSFER',
    CARD = 'CARD',
}

export enum PaymentProvider {
    PESAPAL = 'PESAPAL',
    INTERNAL_WALLET = 'INTERNAL_WALLET',
}

export interface PaymentMetadata {
    phoneNumber?: string;
    accountNumber?: string;
    providerReference?: string;
    providerTransactionId?: string;
    customerName?: string;
    customerEmail?: string;
    ipAddress?: string;
    userAgent?: string;
    [key: string]: any;
}

export interface PaymentProps {
    id: string;
    orderId: string;
    userId: string;
    amount: number;
    currency: string;
    method: PaymentMethod;
    provider: PaymentProvider;
    status: PaymentStatus;
    metadata: PaymentMetadata;
    refundedAmount?: number;
    failureReason?: string;
    createdAt: Date;
    updatedAt: Date;
    completedAt?: Date;
    version?: number;
}

export class Payment {
    private props: PaymentProps;

    constructor(props: PaymentProps) {
        const normalizedProps: PaymentProps = {
            ...props,
            version: props.version ?? 1,
        };
        this.validateProps(normalizedProps);
        this.props = normalizedProps;
    }

    // Getters
    get id(): string {
        return this.props.id;
    }

    get orderId(): string {
        return this.props.orderId;
    }

    get userId(): string {
        return this.props.userId;
    }

    get amount(): number {
        return this.props.amount;
    }

    get currency(): string {
        return this.props.currency;
    }

    get method(): PaymentMethod {
        return this.props.method;
    }

    get provider(): PaymentProvider {
        return this.props.provider;
    }

    get status(): PaymentStatus {
        return this.props.status;
    }

    get metadata(): PaymentMetadata {
        return { ...this.props.metadata };
    }

    get refundedAmount(): number {
        return this.props.refundedAmount || 0;
    }

    get failureReason(): string | undefined {
        return this.props.failureReason;
    }

    get createdAt(): Date {
        return this.props.createdAt;
    }

    get updatedAt(): Date {
        return this.props.updatedAt;
    }

    get completedAt(): Date | undefined {
        return this.props.completedAt;
    }

    get version(): number {
        return this.props.version ?? 1;
    }

    // Business Methods

    /**
     * Update payment status with validation
     */
    updateStatus(newStatus: PaymentStatus, reason?: string): void {
        this.validateStatusTransition(this.props.status, newStatus);
        this.props.status = newStatus;
        this.props.updatedAt = new Date();

        if (newStatus === PaymentStatus.FAILED && reason) {
            this.props.failureReason = reason;
        }

        if (newStatus === PaymentStatus.COMPLETED) {
            this.props.completedAt = new Date();
        }
    }

    /**
     * Mark payment as completed
     */
    markAsCompleted(providerTransactionId?: string): void {
        if (this.props.status === PaymentStatus.COMPLETED) {
            throw new Error('Payment is already completed');
        }

        this.updateStatus(PaymentStatus.COMPLETED);

        if (providerTransactionId) {
            this.props.metadata.providerTransactionId = providerTransactionId;
        }
    }

    /**
     * Mark payment as failed
     */
    markAsFailed(reason: string): void {
        if (this.props.status === PaymentStatus.COMPLETED) {
            throw new Error('Cannot fail a completed payment');
        }

        this.props.status = PaymentStatus.FAILED;
        this.props.failureReason = reason;
        this.props.updatedAt = new Date();
    }

    /**
     * Check if payment can be refunded
     */
    canRefund(): boolean {
        if (this.props.status !== PaymentStatus.COMPLETED) {
            return false;
        }

        const refundableAmount = this.amount - this.refundedAmount;
        return refundableAmount > 0;
    }

    /**
     * Get refundable amount
     */
    getRefundableAmount(): number {
        if (!this.canRefund()) {
            return 0;
        }

        return this.amount - this.refundedAmount;
    }

    /**
     * Record refund
     */
    recordRefund(refundAmount: number): void {
        if (!this.canRefund()) {
            throw new Error('Payment cannot be refunded');
        }

        const refundableAmount = this.getRefundableAmount();
        if (refundAmount > refundableAmount) {
            throw new Error(
                `Refund amount ${refundAmount} exceeds refundable amount ${refundableAmount}`
            );
        }

        if (refundAmount <= 0) {
            throw new Error('Refund amount must be positive');
        }

        this.props.refundedAmount = this.refundedAmount + refundAmount;
        this.props.updatedAt = new Date();

        // Update status based on refund amount
        if (this.props.refundedAmount >= this.amount) {
            this.props.status = PaymentStatus.REFUNDED;
        } else {
            this.props.status = PaymentStatus.PARTIALLY_REFUNDED;
        }
    }

    /**
     * Calculate payment fees (platform fee + provider fee)
     */
    calculateFees(): { platformFee: number; providerFee: number; totalFee: number } {
        const platformFeePercentage = 0.02; // 2% platform fee
        const providerFeePercentage = this.getProviderFeePercentage();

        const platformFee = this.amount * platformFeePercentage;
        const providerFee = this.amount * providerFeePercentage;
        const totalFee = platformFee + providerFee;

        return {
            platformFee: Math.round(platformFee * 100) / 100,
            providerFee: Math.round(providerFee * 100) / 100,
            totalFee: Math.round(totalFee * 100) / 100,
        };
    }

    /**
     * Get provider fee percentage based on payment method
     */
    private getProviderFeePercentage(): number {
        switch (this.props.method) {
            case PaymentMethod.MPESA:
            case PaymentMethod.AIRTEL_MONEY:
            case PaymentMethod.TIGO_PESA:
            case PaymentMethod.HALOPESA:
                return 0.015; // 1.5% for mobile money
            case PaymentMethod.CARD:
                return 0.029; // 2.9% for cards
            case PaymentMethod.BANK_TRANSFER:
                return 0.01; // 1% for bank transfers
            case PaymentMethod.WALLET:
                return 0; // No fee for wallet
            default:
                return 0.02; // Default 2%
        }
    }

    /**
     * Update metadata
     */
    updateMetadata(metadata: Partial<PaymentMetadata>): void {
        this.props.metadata = {
            ...this.props.metadata,
            ...metadata,
        };
        this.props.updatedAt = new Date();
    }

    /**
     * Validate status transition
     */
    private validateStatusTransition(
        currentStatus: PaymentStatus,
        newStatus: PaymentStatus
    ): void {
        const validTransitions: Record<PaymentStatus, PaymentStatus[]> = {
            [PaymentStatus.PENDING]: [
                PaymentStatus.PROCESSING,
                PaymentStatus.FAILED,
                PaymentStatus.CANCELLED,
            ],
            [PaymentStatus.PROCESSING]: [
                PaymentStatus.COMPLETED,
                PaymentStatus.FAILED,
                PaymentStatus.CANCELLED,
            ],
            [PaymentStatus.COMPLETED]: [
                PaymentStatus.REFUNDED,
                PaymentStatus.PARTIALLY_REFUNDED,
            ],
            [PaymentStatus.FAILED]: [],
            [PaymentStatus.CANCELLED]: [],
            [PaymentStatus.REFUNDED]: [],
            [PaymentStatus.PARTIALLY_REFUNDED]: [PaymentStatus.REFUNDED],
        };

        const allowedTransitions = validTransitions[currentStatus];
        if (!allowedTransitions.includes(newStatus)) {
            throw new Error(
                `Invalid status transition from ${currentStatus} to ${newStatus}`
            );
        }
    }

    /**
     * Validate payment props
     */
    private validateProps(props: PaymentProps): void {
        if (!props.id || props.id.trim() === '') {
            throw new Error('Payment ID is required');
        }

        if (!props.orderId || props.orderId.trim() === '') {
            throw new Error('Order ID is required');
        }

        if (!props.userId || props.userId.trim() === '') {
            throw new Error('User ID is required');
        }

        if (props.amount <= 0) {
            throw new Error('Payment amount must be positive');
        }

        if (!props.currency || props.currency.trim() === '') {
            throw new Error('Currency is required');
        }

        if (!Object.values(PaymentMethod).includes(props.method)) {
            throw new Error(`Invalid payment method: ${props.method}`);
        }

        if (!Object.values(PaymentProvider).includes(props.provider)) {
            throw new Error(`Invalid payment provider: ${props.provider}`);
        }

        if (!Object.values(PaymentStatus).includes(props.status)) {
            throw new Error(`Invalid payment status: ${props.status}`);
        }
    }

    /**
     * Create a snapshot of the payment
     */
    toObject(): PaymentProps {
        return { ...this.props };
    }
}

/**
 * Refund Entity
 * Pure business entity representing a payment refund
 * Enforces refund business rules and status transitions
 */

export enum RefundStatus {
    PENDING = 'PENDING',
    PROCESSING = 'PROCESSING',
    COMPLETED = 'COMPLETED',
    FAILED = 'FAILED',
    CANCELLED = 'CANCELLED',
}

export enum RefundReason {
    CUSTOMER_REQUEST = 'CUSTOMER_REQUEST',
    ORDER_CANCELLED = 'ORDER_CANCELLED',
    DUPLICATE_PAYMENT = 'DUPLICATE_PAYMENT',
    FRAUDULENT_TRANSACTION = 'FRAUDULENT_TRANSACTION',
    PRODUCT_NOT_DELIVERED = 'PRODUCT_NOT_DELIVERED',
    PRODUCT_DEFECTIVE = 'PRODUCT_DEFECTIVE',
    SELLER_REQUEST = 'SELLER_REQUEST',
    ADMIN_DECISION = 'ADMIN_DECISION',
    OTHER = 'OTHER',
}

export interface RefundProps {
    id: string;
    paymentId: string;
    orderId: string;
    userId: string;
    amount: number;
    currency: string;
    reason: RefundReason;
    reasonDetails?: string;
    status: RefundStatus;
    providerRef?: string;
    failureReason?: string;
    metadata?: Record<string, any>;
    createdAt: Date;
    updatedAt: Date;
    processedAt?: Date;
    completedAt?: Date;
    failedAt?: Date;
}

export class Refund {
    private props: RefundProps;

    constructor(props: RefundProps) {
        this.validateProps(props);
        this.props = { ...props };
    }

    // Getters
    get id(): string {
        return this.props.id;
    }

    get paymentId(): string {
        return this.props.paymentId;
    }

    get orderId(): string {
        return this.props.orderId;
    }

    get userId(): string {
        return this.props.userId;
    }

    get amount(): number {
        return this.props.amount;
    }

    get currency(): string {
        return this.props.currency;
    }

    get reason(): RefundReason {
        return this.props.reason;
    }

    get reasonDetails(): string | undefined {
        return this.props.reasonDetails;
    }

    get status(): RefundStatus {
        return this.props.status;
    }

    get providerRef(): string | undefined {
        return this.props.providerRef;
    }

    get failureReason(): string | undefined {
        return this.props.failureReason;
    }

    get metadata(): Record<string, any> | undefined {
        return this.props.metadata ? { ...this.props.metadata } : undefined;
    }

    get createdAt(): Date {
        return this.props.createdAt;
    }

    get updatedAt(): Date {
        return this.props.updatedAt;
    }

    get processedAt(): Date | undefined {
        return this.props.processedAt;
    }

    get completedAt(): Date | undefined {
        return this.props.completedAt;
    }

    get failedAt(): Date | undefined {
        return this.props.failedAt;
    }

    // Business Methods

    /**
     * Check if refund can be processed
     */
    canProcess(): boolean {
        return this.props.status === RefundStatus.PENDING;
    }

    /**
     * Start processing the refund
     */
    process(): void {
        if (!this.canProcess()) {
            throw new Error(`Cannot process refund in ${this.props.status} status`);
        }

        this.props.status = RefundStatus.PROCESSING;
        this.props.processedAt = new Date();
        this.props.updatedAt = new Date();
    }

    /**
     * Mark refund as completed
     */
    complete(providerRefundId?: string): void {
        if (this.props.status !== RefundStatus.PROCESSING) {
            throw new Error(
                `Cannot complete refund in ${this.props.status} status. Must be PROCESSING.`
            );
        }

        this.props.status = RefundStatus.COMPLETED;
        this.props.completedAt = new Date();
        this.props.updatedAt = new Date();

        if (providerRefundId) {
            this.props.providerRef = providerRefundId;
        }
    }

    /**
     * Mark refund as failed
     */
    fail(reason: string): void {
        if (
            this.props.status !== RefundStatus.PENDING &&
            this.props.status !== RefundStatus.PROCESSING
        ) {
            throw new Error(`Cannot fail refund in ${this.props.status} status`);
        }

        this.props.status = RefundStatus.FAILED;
        this.props.failureReason = reason;
        this.props.updatedAt = new Date();
    }

    /**
     * Cancel refund
     */
    cancel(): void {
        if (
            this.props.status !== RefundStatus.PENDING &&
            this.props.status !== RefundStatus.PROCESSING
        ) {
            throw new Error(`Cannot cancel refund in ${this.props.status} status`);
        }

        this.props.status = RefundStatus.CANCELLED;
        this.props.updatedAt = new Date();
    }

    /**
     * Update status
     */
    updateStatus(newStatus: RefundStatus, reason?: string): void {
        this.validateStatusTransition(this.props.status, newStatus);
        this.props.status = newStatus;
        this.props.updatedAt = new Date();

        if (newStatus === RefundStatus.FAILED && reason) {
            this.props.failureReason = reason;
        }

        if (newStatus === RefundStatus.PROCESSING && !this.props.processedAt) {
            this.props.processedAt = new Date();
        }

        if (newStatus === RefundStatus.COMPLETED && !this.props.completedAt) {
            this.props.completedAt = new Date();
        }
    }

    /**
     * Validate status transition
     */
    private validateStatusTransition(
        currentStatus: RefundStatus,
        newStatus: RefundStatus
    ): void {
        const validTransitions: Record<RefundStatus, RefundStatus[]> = {
            [RefundStatus.PENDING]: [
                RefundStatus.PROCESSING,
                RefundStatus.FAILED,
                RefundStatus.CANCELLED,
            ],
            [RefundStatus.PROCESSING]: [
                RefundStatus.COMPLETED,
                RefundStatus.FAILED,
                RefundStatus.CANCELLED,
            ],
            [RefundStatus.COMPLETED]: [],
            [RefundStatus.FAILED]: [],
            [RefundStatus.CANCELLED]: [],
        };

        const allowedTransitions = validTransitions[currentStatus];
        if (!allowedTransitions.includes(newStatus)) {
            throw new Error(
                `Invalid status transition from ${currentStatus} to ${newStatus}`
            );
        }
    }

    /**
     * Validate refund props
     */
    private validateProps(props: RefundProps): void {
        if (!props.id || props.id.trim() === '') {
            throw new Error('Refund ID is required');
        }

        if (!props.paymentId || props.paymentId.trim() === '') {
            throw new Error('Payment ID is required');
        }

        if (!props.orderId || props.orderId.trim() === '') {
            throw new Error('Order ID is required');
        }

        if (!props.userId || props.userId.trim() === '') {
            throw new Error('User ID is required');
        }

        if (props.amount <= 0) {
            throw new Error('Refund amount must be positive');
        }

        if (!props.currency || props.currency.trim() === '') {
            throw new Error('Currency is required');
        }

        if (!Object.values(RefundReason).includes(props.reason)) {
            throw new Error(`Invalid refund reason: ${props.reason}`);
        }

        if (!Object.values(RefundStatus).includes(props.status)) {
            throw new Error(`Invalid refund status: ${props.status}`);
        }
    }

    /**
     * Create a snapshot of the refund
     */
    toObject(): RefundProps {
        return { ...this.props };
    }
}

/**
 * Refund Policy
 * Business rules for refund eligibility and processing
 * Defines refund windows, partial refund rules, and eligibility criteria
 */

export interface RefundEligibility {
    canRefund: boolean;
    reasons: string[];
    refundableAmount: number;
    refundWindow: number; // in days
}

export interface RefundWindow {
    fullRefundDays: number;
    partialRefundDays: number;
    noRefundAfterDays: number;
}

export class RefundPolicy {
    private readonly DEFAULT_FULL_REFUND_DAYS = 7;
    private readonly DEFAULT_PARTIAL_REFUND_DAYS = 14;
    private readonly DEFAULT_NO_REFUND_AFTER_DAYS = 30;
    private readonly PARTIAL_REFUND_PERCENTAGE = 0.8; // 80% refund after full refund window

    private refundWindow: RefundWindow;

    constructor(customWindow?: Partial<RefundWindow>) {
        this.refundWindow = {
            fullRefundDays: customWindow?.fullRefundDays || this.DEFAULT_FULL_REFUND_DAYS,
            partialRefundDays: customWindow?.partialRefundDays || this.DEFAULT_PARTIAL_REFUND_DAYS,
            noRefundAfterDays: customWindow?.noRefundAfterDays || this.DEFAULT_NO_REFUND_AFTER_DAYS,
        };
    }

    /**
     * Check if payment can be refunded
     */
    canRefund(
        paymentStatus: string,
        paymentAmount: number,
        refundedAmount: number,
        paymentDate: Date,
        orderStatus?: string
    ): RefundEligibility {
        const reasons: string[] = [];
        let canRefund = true;

        // Check payment status
        if (paymentStatus !== 'COMPLETED') {
            reasons.push('Payment must be completed to be refunded');
            canRefund = false;
        }

        // Check if already fully refunded
        if (refundedAmount >= paymentAmount) {
            reasons.push('Payment has already been fully refunded');
            canRefund = false;
        }

        // Check refund window
        const daysSincePayment = this.getDaysSince(paymentDate);
        if (daysSincePayment > this.refundWindow.noRefundAfterDays) {
            reasons.push(
                `Refund window expired. Maximum ${this.refundWindow.noRefundAfterDays} days`
            );
            canRefund = false;
        }

        // Check order status if provided
        if (orderStatus && !this.isRefundableOrderStatus(orderStatus)) {
            reasons.push(`Order status ${orderStatus} is not refundable`);
            canRefund = false;
        }

        const refundableAmount = this.calculateRefundAmount(
            paymentAmount,
            refundedAmount,
            paymentDate
        );

        return {
            canRefund,
            reasons,
            refundableAmount,
            refundWindow: this.getRefundWindowDays(paymentDate),
        };
    }

    /**
     * Calculate refund amount based on time elapsed
     */
    calculateRefundAmount(
        paymentAmount: number,
        alreadyRefunded: number,
        paymentDate: Date
    ): number {
        const remainingAmount = paymentAmount - alreadyRefunded;
        const daysSincePayment = this.getDaysSince(paymentDate);

        // Full refund within full refund window
        if (daysSincePayment <= this.refundWindow.fullRefundDays) {
            return remainingAmount;
        }

        // Partial refund within partial refund window
        if (daysSincePayment <= this.refundWindow.partialRefundDays) {
            return Math.round(remainingAmount * this.PARTIAL_REFUND_PERCENTAGE * 100) / 100;
        }

        // No refund after window expires
        return 0;
    }

    /**
     * Get refund window remaining days
     */
    getRefundWindow(paymentDate: Date): RefundWindow {
        return { ...this.refundWindow };
    }

    /**
     * Get remaining days in refund window
     */
    getRefundWindowDays(paymentDate: Date): number {
        const daysSincePayment = this.getDaysSince(paymentDate);
        return Math.max(0, this.refundWindow.noRefundAfterDays - daysSincePayment);
    }

    /**
     * Check if order status allows refund
     */
    private isRefundableOrderStatus(orderStatus: string): boolean {
        const refundableStatuses = [
            'PENDING',
            'CONFIRMED',
            'PROCESSING',
            'CANCELLED',
            'FAILED',
        ];
        return refundableStatuses.includes(orderStatus.toUpperCase());
    }

    /**
     * Calculate days since payment
     */
    private getDaysSince(date: Date): number {
        const now = new Date();
        const diffTime = Math.abs(now.getTime() - date.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        return diffDays;
    }

    /**
     * Check if full refund is available
     */
    isFullRefundAvailable(paymentDate: Date): boolean {
        const daysSincePayment = this.getDaysSince(paymentDate);
        return daysSincePayment <= this.refundWindow.fullRefundDays;
    }

    /**
     * Check if partial refund is available
     */
    isPartialRefundAvailable(paymentDate: Date): boolean {
        const daysSincePayment = this.getDaysSince(paymentDate);
        return (
            daysSincePayment > this.refundWindow.fullRefundDays &&
            daysSincePayment <= this.refundWindow.partialRefundDays
        );
    }

    /**
     * Get refund percentage based on time
     */
    getRefundPercentage(paymentDate: Date): number {
        const daysSincePayment = this.getDaysSince(paymentDate);

        if (daysSincePayment <= this.refundWindow.fullRefundDays) {
            return 1.0; // 100%
        }

        if (daysSincePayment <= this.refundWindow.partialRefundDays) {
            return this.PARTIAL_REFUND_PERCENTAGE; // 80%
        }

        return 0; // 0%
    }

    /**
     * Update refund window
     */
    updateRefundWindow(newWindow: Partial<RefundWindow>): void {
        this.refundWindow = {
            ...this.refundWindow,
            ...newWindow,
        };
    }
}

